const TONCENTER_API_KEY_STORAGE_KEY = 'platho.toncenter.apiKey.v1';

const TONCENTER_KEY_STATUS_ICONS = Object.freeze({
  active: { icon: '✓', state: 'ok', title: t('wallet.rpcKeyStatusActive') },
  error: { icon: '✕', state: 'error', title: t('wallet.rpcKeyStatusError') },
  checking: { icon: '⏳', state: '', title: t('wallet.rpcKeyStatusChecking') },
  activating: { icon: '⏳', state: '', title: t('wallet.rpcKeyStatusActivating') },
  empty: { icon: '', state: '', title: '' },
});

function setToncenterKeyStatusIcon(kind) {
  if (!toncenterKeyStatus) return;
  const entry = TONCENTER_KEY_STATUS_ICONS[kind] ?? TONCENTER_KEY_STATUS_ICONS.empty;
  toncenterKeyStatus.textContent = entry.icon;
  toncenterKeyStatus.title = entry.title;
  toncenterKeyStatus.setAttribute('aria-label', entry.title);
  if (entry.state) {
    toncenterKeyStatus.setAttribute('data-state', entry.state);
  } else {
    toncenterKeyStatus.removeAttribute('data-state');
  }
}

function refreshToncenterKeyUi() {
  const key = globalThis.plathoToncenterApiKey ?? null;
  setToncenterKeyStatusIcon(key ? 'active' : 'empty');
  if (toncenterApiKeyInput && document.activeElement !== toncenterApiKeyInput) {
    toncenterApiKeyInput.value = key ?? '';
  }
}

const TONCENTER_API_KEY_SECRET_ID = 'toncenter-api-key-v1';
function toncenterApiKeySecretStore() {
  if (!globalThis.plathoDeviceSecretStore) {
    globalThis.plathoDeviceSecretStore = createIndexedDbDeviceSecretStore({
      dbName: scopedIndexedDbName('platho-device-secrets-v1'),
      id: TONCENTER_API_KEY_SECRET_ID,
    }).catch(() => null);
  }
  return globalThis.plathoDeviceSecretStore;
}

async function loadSealedToncenterApiKey() {
  let legacy = null;
  try { legacy = globalThis.localStorage?.getItem(TONCENTER_API_KEY_STORAGE_KEY) || null; } catch { legacy = null; }
  const store = await toncenterApiKeySecretStore();
  let key = null;
  if (store) {
    try { key = await store.read(); } catch { key = null; }
    if (!key && legacy && legacy.trim()) {
      try {
        key = await store.write(legacy.trim());
        try { globalThis.localStorage?.removeItem(TONCENTER_API_KEY_STORAGE_KEY); } catch { }
      } catch { key = legacy.trim(); }
    }
  } else if (legacy && legacy.trim()) {
    key = legacy.trim();
  }
  if (!key) { refreshToncenterKeyUi(); return null; }
  useToncenterApiKey(key);
  return key;
}

function useToncenterApiKey(rawKey) {
  const key = String(rawKey ?? '').trim();
  globalThis.plathoToncenterApiKey = key || null;
  globalThis.plathoTonRpcTransport = null;
  globalThis.plathoWalletRpcTransport = null;
  try {
    const rebuilt = globalThis.plathoTonRpcConfig ? createTonRpcTransport(globalThis.plathoTonRpcConfig) : null;
    if (rebuilt) globalThis.plathoTonRpcTransport = rebuilt;
  } catch { }
  refreshToncenterKeyUi();
  return Boolean(key);
}

function applyToncenterApiKey(rawKey) {
  const key = String(rawKey ?? '').trim();
  void toncenterApiKeySecretStore().then((store) => store?.write(key)).catch(() => {});
  try { globalThis.localStorage?.removeItem(TONCENTER_API_KEY_STORAGE_KEY); } catch { }
  return useToncenterApiKey(key);
}

async function validateToncenterApiKey(rawKey) {
  const key = String(rawKey ?? '').trim();
  if (!key) return { ok: false, reason: 'empty' };
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), 10000) : null;
  try {
    const response = await fetch('https://toncenter.com/api/v3/masterchainInfo', {
      cache: 'no-store',
      headers: { 'X-API-Key': key },
      signal: controller?.signal,
    });
    if (response.ok) return { ok: true };
    if (response.status === 401 || response.status === 403) return { ok: false, reason: 'invalid' };
    return { ok: false, reason: 'unverified' };
  } catch {
    return { ok: false, reason: 'unverified' };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

let toncenterKeyReverifyTimers = [];
function clearToncenterKeyReverify() {
  for (const timer of toncenterKeyReverifyTimers) { try { clearTimeout(timer); } catch { } }
  toncenterKeyReverifyTimers = [];
}
function scheduleToncenterKeyReverify(key) {
  clearToncenterKeyReverify();
  const attempt = async (isFinal) => {
    if ((globalThis.plathoToncenterApiKey ?? null) !== key) return;
    const result = await validateToncenterApiKey(key);
    if ((globalThis.plathoToncenterApiKey ?? null) !== key) return;
    if (result.ok) {
      clearToncenterKeyReverify();
      setToncenterKeyStatusIcon('active');
      return;
    }
    if (isFinal && result.reason === 'invalid') {
      applyToncenterApiKey('');
      void bringToncenterKeyToTelegram().catch(() => {});
      if (toncenterApiKeyInput && document.activeElement !== toncenterApiKeyInput) toncenterApiKeyInput.value = '';
      setToncenterKeyStatusIcon('error');
    }
  };
  for (const at of [25_000, 60_000, 120_000, 240_000, 420_000]) {
    toncenterKeyReverifyTimers.push(setTimeout(() => { attempt(false).catch(() => {}); }, at));
  }
  toncenterKeyReverifyTimers.push(setTimeout(() => { attempt(true).catch(() => {}); }, 600_000));
}

async function commitToncenterKeyFromInput() {
  if (!toncenterApiKeyInput) return;
  clearToncenterKeyReverify();
  const trimmed = String(toncenterApiKeyInput.value ?? '').trim();
  if (!trimmed) {
    applyToncenterApiKey('');
    void bringToncenterKeyToTelegram().catch(() => {});
    return;
  }
  if (trimmed === (globalThis.plathoToncenterApiKey ?? null)) {
    refreshToncenterKeyUi();
    return;
  }
  setToncenterKeyStatusIcon('checking');
  const minCheckingVisible = new Promise((resolve) => setTimeout(resolve, 450));
  const result = await validateToncenterApiKey(trimmed);
  await minCheckingVisible;
  applyToncenterApiKey(trimmed);
  void bringToncenterKeyToTelegram().catch(() => {});
  if (result.reason === 'invalid') {
    setToncenterKeyStatusIcon('activating');
    scheduleToncenterKeyReverify(trimmed);
  }
}

let toncenterKeyCheckTimer = null;
function scheduleToncenterKeyCheck() {
  if (toncenterKeyCheckTimer) clearTimeout(toncenterKeyCheckTimer);
  toncenterKeyCheckTimer = setTimeout(() => {
    toncenterKeyCheckTimer = null;
    commitToncenterKeyFromInput().catch((error) => console.error(error));
  }, 600);
}
toncenterApiKeyInput?.addEventListener('input', scheduleToncenterKeyCheck);
toncenterApiKeyInput?.addEventListener('change', () => {
  if (toncenterKeyCheckTimer) { clearTimeout(toncenterKeyCheckTimer); toncenterKeyCheckTimer = null; }
  commitToncenterKeyFromInput().catch((error) => console.error(error));
});
toncenterApiKeyInput?.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    toncenterApiKeyInput.blur();
  }
});

