function shortAvatarHashForDiagnostic(value) {
  const hash = String(value ?? '').replace(/^0x/i, '');
  return /^0*$/.test(hash) ? 'zero' : hash.slice(0, 12);
}

function copyPrivateThreadDiagnostic() {
  try {
    const own = ownRuntimeWalletRaw();
    const dump = {
      version: PLATHO_APP_RUNTIME_VERSION,
      build: PLATHO_APP_BUILD_ID,
      own,
      telegram: isTelegramEnv() ? { launchSigned: telegramLaunchedByOfficialBot(), botId: appConfig.telegram?.botId ?? null } : null,
      storage: (() => { try { return globalThis.localStorage?.getItem(RESECURE_STATE_KEY) ?? null; } catch { return null; } })(),
      threads: (threads ?? []).filter((thread) => !thread.publicChannelId).map((thread) => ({
        id: thread.id,
        name: thread.name ?? null,
        convPeer: thread.convPeerKeyId ?? null,
        isSaved: isSavedMessagesThread(thread),
        pending: thread.pendingIdentityResolution === true,
        primaryRaw: threadPrimaryWalletRaw(thread),
        wallets: threadIdentityVariants(thread)
          .filter((variant) => variant?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS)
          .map((variant) => { try { return rawWalletAddress(variant.value); } catch { return String(variant.value); } }),
        vars: threadIdentityVariants(thread)
          .filter((variant) => variant?.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS)
          .map((variant) => `${variant?.type ?? '?'}:${String(variant?.value ?? '')}`.slice(0, 60)),
        msgs: (thread.messages ?? []).length,
        m2: (thread.messages ?? []).slice(-12).map((message) => ({
          d: message?.type ?? null,
          m: message?.meta ?? null,
          ce: message?.chainEntryId !== undefined && message?.chainEntryId !== null ? 'y' : 'n',
          id: message?.chainEntryId ?? null,
          ref: (Array.isArray(message?.blocks) ? message.blocks : []).find((b) => b?.type === 'reply')?.refEntryId ?? null,
          len: String(message?.text ?? '').length,
        })),
        av: (() => {
          const incoming = [...(thread.messages ?? [])].reverse().find((message) => message?.type === 'in');
          return {
            pv: Number(incoming?.profileVersion ?? 0) || 0,
            ah: shortAvatarHashForDiagnostic(incoming?.avatarHash),
            img: thread.avatarImageUrl ? 'y' : 'n',
          };
        })(),
      })),
      avatarLoad: globalThis.plathoLastAvatarLoad ?? null,
      avatarShard: globalThis.plathoLastAvatarShard ?? null,
      ownAvatar: (() => {
        const fields = currentProfilePointerFields();
        return { pv: Number(fields.profileVersion ?? 0) || 0, ah: shortAvatarHashForDiagnostic(fields.avatarHash) };
      })(),
      senderResolve: plathoSenderResolveDebug,
      convSync: globalThis.plathoLastConvSync ?? null,
      syncProfile: globalThis.plathoLastSyncProfile ?? null,
      sendProfile: globalThis.plathoLastSendProfile ?? null,
      spinner: globalThis.plathoLastSpinnerSpan ?? null,
      viewport: {
        css: Math.round(window.innerWidth ?? 0),
        visual: Math.round(window.visualViewport?.width ?? 0),
        dpr: Number(window.devicePixelRatio ?? 0),
        telegram: isTelegramEnv() ? (telegramPlatform() ?? 'unknown') : null,
        toolbar: (() => {
          const composer = document.querySelector('.composer.is-maximized')
            ?? (isPublicViewActive() ? document.querySelector('#publicComposer') : document.querySelector('#composer'));
          const bar = composer?.querySelector('.composer-toolbar') ?? null;
          const scroll = bar?.querySelector('.composer-toolbar-scroll') ?? null;
          if (!bar || !scroll) return null;
          const box = bar.getBoundingClientRect();
          const button = scroll.querySelector('.composer-toolbar-button');
          const style = getComputedStyle(bar);
          return {
            maximized: Boolean(document.querySelector('.composer.is-maximized')),
            barH: Math.round(box.height),
            needed: bar.scrollHeight,
            maxH: style.maxHeight,
            barW: Math.round(scroll.getBoundingClientRect().width),
            btn: button
              ? { w: Math.round(button.getBoundingClientRect().width), h: Math.round(button.getBoundingClientRect().height) }
              : null,
            gap: getComputedStyle(scroll).columnGap || getComputedStyle(scroll).gap || null,
            scrollW: Math.round(scroll.scrollWidth),
            composerH: Math.round(composer?.getBoundingClientRect().height ?? 0),
          };
        })(),
      },
      historyRestore: globalThis.plathoLastEncryptedHistoryRestore
        ? {
          restored: globalThis.plathoLastEncryptedHistoryRestore.restored ?? null,
          failed: globalThis.plathoLastEncryptedHistoryRestore.failedRecords ?? null,
          seeded: globalThis.plathoLastEncryptedHistoryRestore.seededSeqMarks ?? null,
        }
        : null,
      introLane: {
        armed: introReceiveLane !== null,
        identity: localRecipientKeyPair?.keyId ? String(localRecipientKeyPair.keyId).slice(0, 12) : null,
        lastError: plathoIntroScanLastError,
      },
      lastIntroSend: globalThis.plathoLastIntroDirectSend ?? null,
      send: globalThis.plathoLastConvSend ?? null,
      sendInFlight: globalThis.plathoConvSendInFlight ?? 0,
      convs: (() => {
        try {
          return [...(convKeyStore?.snapshot?.() ?? new Map()).entries()].map(([id, record]) => ({
            id: String(id).slice(0, 16),
            peer: record?.peerKeyId ? introKeyIdString(record.peerKeyId).slice(0, 12) : null,
            epochs: Object.keys(record?.outgoingSeq ?? {}),
          }));
        } catch { return 'unreadable'; }
      })(),
    };
    copyTextToClipboard(JSON.stringify(dump, null, 1)).then(() => flashWalletIdentityStatus(t('diag.copied'))).catch(() => {});
  } catch (error) { console.error(error); }
}
