function createSerialLane() {
  const waiting = [];
  let running = false;
  const pump = () => {
    if (running || waiting.length === 0) return;
    const at = waiting.findIndex((item) => !item.background);
    const [next] = waiting.splice(at >= 0 ? at : 0, 1);
    running = true;
    Promise.resolve().then(next.task).then(next.resolve, next.reject).finally(() => { running = false; pump(); });
  };
  const enqueue = (task, { background = false, key = null } = {}) => new Promise((resolve, reject) => {
    waiting.push({ task, background, key, resolve, reject });
    pump();
  });
  enqueue.promote = (key) => { for (const item of waiting) if (item.key === key) item.background = false; };
  enqueue.drop = () => { const dropped = waiting.splice(0); for (const item of dropped) item.resolve(null); return dropped.length; };
  return enqueue;
}

