  if (!store) return Promise.resolve(false);
  const snapshot = map.size > 0 ? JSON.stringify(Object.fromEntries(map)) : '';
  const write = contactLabelState.persist
    .then(() => store.write(snapshot))
    .then(() => true, (error) => { console.warn('[contacts] a label change could not be sealed', error); return false; });
  contactLabelState.persist = write;
  return write;
