async function showChannelDescriptionPopover(authorWallet, anchor, options = {}) {
  if (!authorWallet || !anchor) return;
  const isOwn = options.isOwn === true;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'dialog');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('public.channelAbout');
  const body = document.createElement('div');
  body.className = 'channel-about-popover';
  popover.append(title, body);
  const renderBody = (profile) => {
    body.replaceChildren();
    const description = typeof profile?.description === 'string' ? profile.description.trim() : '';
    const tags = (profile?.tags ?? []).filter(Boolean);
    if (description) {
      const paragraph = document.createElement('p');
      paragraph.className = 'channel-about-description';
      paragraph.textContent = description;
      body.append(paragraph);
    }
    if (tags.length > 0) {
      const tagRow = document.createElement('div');
      tagRow.className = 'channel-about-tags';
      for (const tag of tags) {
        const chip = document.createElement('span');
        chip.className = 'channel-about-tag';
        chip.textContent = `#${tag}`;
        tagRow.append(chip);
      }
      body.append(tagRow);
    }
    if (!description && tags.length === 0) {
      const empty = document.createElement('p');
      empty.className = 'channel-about-empty';
      empty.textContent = t('public.noDescriptionYet');
      body.append(empty);
    }
    if (!(publicChannelViewOpen && publicChannelViewWallet && sameWalletAddress(publicChannelViewWallet, authorWallet))) {
      const openChannelButton = document.createElement('button');
      openChannelButton.type = 'button';
      openChannelButton.className = 'discovery-cta-action channel-about-open';
      openChannelButton.textContent = t('public.openChannel');
      openChannelButton.addEventListener('click', () => {
        hideIdentityPopover();
        openPublicChannelView({ authorWallet });
      });
      body.append(openChannelButton);
    }
    if (isOwn) {
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'discovery-cta-action channel-about-edit';
      editButton.textContent = (description || tags.length > 0) ? t('public.editDescription') : t('public.addDescription');
      editButton.addEventListener('click', () => {
        hideIdentityPopover();
        openEditChannelProfileDialog().catch((error) => console.error(error));
      });
      body.append(editButton);
    }
  };
  const cached = cachedChannelProfile(authorWallet);
  if (cached && cached.fetchedAt) {
    renderBody(cached);
  } else {
    const loading = document.createElement('p');
    loading.className = 'channel-about-empty';
    loading.textContent = t('public.loadingDescription');
    body.append(loading);
  }
  popover.classList.remove('is-closing');
  popover.hidden = false;
  positionIdentityPopover(popover, anchor);
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
  if (!cached || !cached.fetchedAt) {
    let resolved = null;
    try {
      resolved = await resolveChannelProfile(authorWallet);
    } catch (error) {
      resolved = cachedChannelProfile(authorWallet);
    }
    if (!popover.hidden && identityPopoverAnchor === anchor) {
      renderBody(resolved);
      positionIdentityPopover(popover, anchor);
    }
  }
}

const CHANNEL_LOOK_STEPS = Object.freeze({ plasma: [5, 1, 25, 10], nodes: [10, 10, 5, 10] });
const CHANNEL_LOOK_SETTING_LABELS = Object.freeze({
  plasma: ['profile.auroraBrightness', 'profile.auroraCount', 'profile.auroraSpeed', 'profile.auroraEnergy'],
  nodes: ['appearance.nodesBrightness', 'appearance.nodesRunners', 'appearance.nodesSpeed', 'appearance.nodesLights'],
});
const CHANNEL_LOOK_BACKGROUND_LABELS = Object.freeze({ none: 'appearance.backgroundNone', plasma: 'appearance.backgroundPlasma', nodes: 'appearance.backgroundNodes' });

function ownLookNow() {
  return {
    theme: currentEffectiveTheme(),
    background: PROFILE_LOOK_BACKGROUNDS.includes(backgroundMode) ? backgroundMode : 'none',
    settings: {
      plasma: [auroraLevel, auroraCount, auroraSpeed, auroraEnergy],
      nodes: [nodesLevel, nodesRunners, nodesSpeed, nodesLights],
    },
    gift: wornGiftTheme?.itemAddress ? 'gift' : 'none',
  };
}

function buildChannelLookEditor({ preset = null, current = null, onEdit = null } = {}) {
  const mine = ownLookNow();
  const onChain = current?.kind === 'look' ? current : null;
  const state = {
    enabled: preset === 'custom' ? true : preset === 'none' ? false : Boolean(current),
    theme: onChain?.theme ?? mine.theme,
    background: onChain?.background ?? mine.background,
    settings: { plasma: [...mine.settings.plasma], nodes: [...mine.settings.nodes] },
    gift: (onChain ? Boolean(onChain.itemAddress) : current?.kind === 'telegram-gift') ? 'gift' : 'none',
  };
  if (onChain?.background && Array.isArray(onChain.settings) && onChain.settings.length === state.settings[onChain.background]?.length) {
    state.settings[onChain.background] = [...onChain.settings];
  }
  const box = document.createElement('div');
  box.className = 'settings-list channel-look-editor';
  const refreshCost = () => { try { renderActionSummary(activeActionDialog?.summary, collectActionDialogValues()); } catch { } };
  const selectRow = (labelKey, options, value, onChange) => {
    const label = document.createElement('label');
    label.className = 'settings-select-row compact-select-row';
    const caption = document.createElement('span');
    caption.textContent = t(labelKey);
    const select = document.createElement('select');
    for (const [optionValue, optionKey] of options) {
      const option = document.createElement('option');
      option.value = optionValue;
      option.textContent = t(optionKey);
      select.append(option);
    }
    select.value = value;
    select.addEventListener('change', () => { onChange(select.value); sync(); refreshCost(); onEdit?.(); });
    label.append(caption, select);
    return { row: label, select };
  };
  const rangeRow = (labelKey, [min, max], step, value, onInput) => {
    const label = document.createElement('label');
    label.className = 'settings-select-row compact-select-row settings-range-row';
    const caption = document.createElement('span');
    caption.textContent = t(labelKey);
    const range = document.createElement('input');
    range.type = 'range';
    range.min = String(min);
    range.max = String(max);
    range.step = String(step);
    range.value = String(value);
    range.addEventListener('input', () => { onInput(Math.max(min, Math.min(max, Math.round(Number(range.value) || 0)))); onEdit?.(); });
    label.append(caption, range);
    return label;
  };
  const enabledRow = selectRow('public.channelAppearance', [['none', 'public.channelAppearanceNone'], ['custom', 'public.channelAppearanceCustom']],
    state.enabled ? 'custom' : 'none', (value) => { state.enabled = value === 'custom'; });
  const themeRow = selectRow('appearance.theme', PROFILE_LOOK_THEMES.map((theme) => [theme, theme === 'light' ? 'appearance.themeLight' : 'appearance.themeDark']),
    state.theme, (value) => { state.theme = value; });
  const backgroundRow = selectRow('appearance.background', PROFILE_LOOK_BACKGROUNDS.map((mode) => [mode, CHANNEL_LOOK_BACKGROUND_LABELS[mode]]),
    state.background, (value) => { state.background = value; });
  const groups = {};
  for (const mode of ['plasma', 'nodes']) {
    const group = document.createElement('div');
    group.className = 'settings-list channel-look-settings';
    PROFILE_LOOK_SETTING_RANGES[mode].forEach((range, index) => {
      group.append(rangeRow(CHANNEL_LOOK_SETTING_LABELS[mode][index], range, CHANNEL_LOOK_STEPS[mode][index], state.settings[mode][index],
        (value) => { state.settings[mode][index] = value; }));
    });
    groups[mode] = group;
  }
  const giftRow = selectRow('profileCard.gifts', [['none', 'public.channelAppearanceNone'], ['gift', 'public.channelAppearanceGift']],
    state.gift, (value) => { state.gift = value; });
  const previewHint = document.createElement('p');
  previewHint.className = 'channel-look-preview-hint';
  previewHint.textContent = t('public.channelLookPreviewHint');
  const sync = () => {
    themeRow.row.hidden = !state.enabled;
    backgroundRow.row.hidden = !state.enabled;
    giftRow.row.hidden = !state.enabled;
    previewHint.hidden = !state.enabled;
    for (const [mode, group] of Object.entries(groups)) group.hidden = !state.enabled || state.background !== mode;
  };
  box.append(enabledRow.row, themeRow.row, backgroundRow.row, groups.plasma, groups.nodes, giftRow.row, previewHint);
  sync();
  return {
    node: box,
    wantsGift: () => state.enabled && state.gift === 'gift',
    read: () => (state.enabled ? normalizeProfileAppearance({
      kind: 'look',
      theme: state.theme,
      background: state.background,
      settings: state.settings[state.background] ?? [],
      itemAddress: state.gift === 'gift' ? wornGiftClaimAddress() : null,
    }) : null),
  };
}

async function openEditChannelProfileDialog({ appearance: presetAppearance = null } = {}) {
  const wallet = rawWalletAddress(plathoWallet?.address);
  if (!wallet) { setPublicStatus('channel description needs a wallet'); return; }
  if (!hasActivePlathoAccount()) { setPublicStatus('channel description needs an active account'); return; }
  const current = await readOwnProfileForPublish(wallet);
  if (!current) return null;
  const editor = buildChannelLookEditor({ preset: presetAppearance, current: current?.appearance ?? null, onEdit: () => previewChannelLook(editor) });
  const appearanceOf = () => editor.read();
  previewChannelLook(editor);
  const result = await openActionDialog({
    title: t('public.channelDescriptionTitle'),
    hint: t('public.channelDescriptionHint'),
    submitLabel: t('common.save'),
    checkingHint: t('public.descriptionSaving'),
    priced: true,
    summary: (values) => {
      try {
        return [channelProfilePriceLine(values.description, values.tags, appearanceOf(values), normalizeProfileWornGift(current?.wornGift ?? null), current?.groups ?? [])];
      } catch {
        return [];
      }
    },
    fields: [
      { type: 'custom', className: 'action-custom-field channel-look-field', render: () => editor.node },
      {
        id: 'description',
        label: t('public.descriptionLabel'),
        type: 'textarea',
        placeholder: t('public.descriptionPlaceholder'),
        value: current?.description ?? '',
        required: false,
        counter: (value) => {
          const used = utf8ByteLength(value);
          return { text: t('public.profileDescriptionBudget', { used, max: PROFILE_DESCRIPTION_MAX_BYTES }), over: used > PROFILE_DESCRIPTION_MAX_BYTES };
        },
      },
      {
        id: 'tags',
        label: t('public.tagsLabel'),
        placeholder: t('public.tagsPlaceholder'),
        value: (current?.tags ?? []).join(', '),
        required: false,
        autocomplete: 'off',
        counter: (value) => {
          const raw = String(value).split(/[,\n]+/).map((s) => s.trim().toLowerCase()).filter(Boolean);
          const over = raw.length > PROFILE_MAX_TAGS || raw.some((tag) => utf8ByteLength(tag) > PROFILE_TAG_MAX_BYTES);
          return { text: t('public.profileTagsBudget', { count: raw.length, max: PROFILE_MAX_TAGS, bytes: PROFILE_TAG_MAX_BYTES }), over };
        },
      },
    ],
    validateSubmit: async (values) => {
      if (tonRpcLimited()) return { ok: false, error: t('sync.rpcBusy') };
      if (editor.wantsGift() && !wornGiftClaimAddress()) {
        return { ok: false, error: t('public.channelAppearanceNeedsGift') };
      }
      try {
        const description = String(values.description ?? '').trim();
        const tags = String(values.tags ?? '').split(/[,\n]+/);
        const published = await publishChannelProfile(description, tags, appearanceOf(values), normalizeProfileWornGift(current?.wornGift ?? null), current?.groups ?? []);
        const meta = { description: published.description, tags: published.tags, ownerUsername: published.ownerUsername, appearance: published.appearance ?? null, wornGift: published.wornGift ?? null, groups: published.groups ?? current?.groups ?? [], balanceCard: published.balanceCard === true };
        setChannelProfileOptimistic(wallet, meta, published.createdAtSec);
        return { ok: true, result: { status: 'submitted' } };
      } catch (error) {
        if (noteTonRpcRateLimit(error)) return { ok: false, error: t('sync.rpcBusy') };
        if (error?.code === 'PLATHO_WALLET_GRAM_REQUIRED') return { ok: false, error: String(error.message) };
        console.error(error);
        return { ok: false, error: t('public.descriptionSaveFailed') };
      }
    },
  }).finally(() => endChannelLookPreview());
  if (result) {
    setPublicStatus('channel description saved');
    if (isPublicViewActive()) renderPublicSurface({ anchorUnread: false });
  }
}

function renderDisplayAsPopover({
  options, selectedKey, localLabelExists, anchor, onSelect, onSetLocalName,
  pinned = null, onTogglePin = null, muted = null, onToggleMute = null, onOpenProfile = null, onOpenChannel = null,
  groupActions = null,
}) {
  if (!anchor) return;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'menu');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('chat.displayAs');
  popover.append(title);
  const menuRow = (labelText, hintText, onPick, dialog = false) => {
    const rowNode = document.createElement('button');
    rowNode.type = 'button';
    rowNode.className = 'identity-variant identity-variant-action';
    rowNode.setAttribute('role', 'menuitem');
    if (dialog) rowNode.setAttribute('aria-haspopup', 'dialog');
    const strong = document.createElement('strong');
    strong.textContent = labelText;
    const hint = document.createElement('span');
    hint.textContent = hintText;
    rowNode.append(strong, hint);
    rowNode.addEventListener('click', () => { hideIdentityPopover(); onPick(); });
    return rowNode;
  };
  const openEdit = () => {
    hideIdentityPopover();
    onSetLocalName();
  };
  let pinRow = null;
  if (pinned !== null && typeof onTogglePin === 'function') {
    pinRow = document.createElement('button');
    pinRow.type = 'button';
    pinRow.className = 'identity-variant identity-variant-action';
    pinRow.setAttribute('role', 'menuitem');
    const pinLabel = document.createElement('strong');
    pinLabel.textContent = pinned ? t('chat.unpinContact') : t('chat.pinContact');
    const pinType = document.createElement('span');
    pinType.textContent = t('chat.pinHint');
    pinRow.append(pinLabel, pinType);
    pinRow.addEventListener('click', () => {
      hideIdentityPopover();
      onTogglePin(!pinned);
    });
  }
  let muteRow = null;
  if (muted !== null && typeof onToggleMute === 'function') {
    muteRow = document.createElement('button');
    muteRow.type = 'button';
    muteRow.className = 'identity-variant identity-variant-action';
    muteRow.setAttribute('role', 'menuitem');
    const muteLabel = document.createElement('strong');
    muteLabel.textContent = muted ? t('chat.unmuteContact') : t('chat.muteContact');
    const muteType = document.createElement('span');
    muteType.textContent = t('chat.muteHint');
    muteRow.append(muteLabel, muteType);
    muteRow.addEventListener('click', () => {
      hideIdentityPopover();
      onToggleMute(!muted);
    });
  }
  if (!localLabelExists) {
    const localNameRow = document.createElement('button');
    localNameRow.type = 'button';
    localNameRow.className = 'identity-variant identity-variant-action';
    localNameRow.setAttribute('role', 'menuitem');
    const localNameLabel = document.createElement('strong');
    localNameLabel.textContent = t('chat.setLocalName');
    const localNameType = document.createElement('span');
    localNameType.textContent = t('chat.onlyShownThisDevice');
    localNameRow.append(localNameLabel, localNameType);
    localNameRow.addEventListener('click', openEdit);
    popover.append(localNameRow);
  }
  if (typeof groupActions?.onRename === 'function') {
    popover.append(menuRow(t('group.rename'), t('group.renameHint'), groupActions.onRename, true));
  }
  if (typeof groupActions?.onEntryFee === 'function') {
    popover.append(menuRow(t('group.entryFee'), t('group.entryFeeMenuHint'), groupActions.onEntryFee, true));
  }
  if (groupActions?.picture && typeof groupActions.picture.onPick === 'function') {
    popover.append(menuRow(groupActions.picture.label, groupActions.pictureVisibility ?? t('group.avatarVisibility'), groupActions.picture.onPick));
  }
  for (const option of options ?? []) {
    if (option.key === 'local-label') {
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'identity-variant-edit';
      editButton.setAttribute('role', 'menuitem');
      editButton.setAttribute('aria-label', t('chat.editLocalName'));
      editButton.title = t('chat.editLocalName');
      editButton.append(createPencilIcon());
      editButton.addEventListener('click', openEdit);
      row.append(selectRow, editButton);
      popover.append(row);
      continue;
    }
    if (option.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS && option.identity.value) {
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'identity-variant-edit';
      copyButton.setAttribute('role', 'menuitem');
      copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
      copyButton.title = t('profile.copyWalletAddress');
      copyButton.append(createCopyIcon());
      const addressToCopy = option.identity.value;
      copyButton.addEventListener('click', async (event) => {
        event.stopPropagation();
        try {
          await copyTextToClipboard(addressToCopy);
          copyButton.classList.add('identity-variant-copied');
          copyButton.title = t('wallet.addressCopied');
          copyButton.setAttribute('aria-label', t('wallet.addressCopied'));
          window.setTimeout(() => {
            copyButton.classList.remove('identity-variant-copied');
            copyButton.title = t('profile.copyWalletAddress');
            copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
          }, 1200);
        } catch (error) {
          console.error(error);
        }
      });
      row.append(selectRow, copyButton);
      popover.append(row);
      continue;
    }
    popover.append(identityVariantRow(option, option.key === selectedKey, (selected) => {
      hideIdentityPopover();
      onSelect(selected);
    }));
  }
  let profileRow = null;
  if (typeof onOpenProfile === 'function') {
    profileRow = document.createElement('button');
    profileRow.type = 'button';
    profileRow.className = 'identity-variant identity-variant-action';
    profileRow.setAttribute('role', 'menuitem');
    profileRow.setAttribute('aria-haspopup', 'dialog');
    const profileLabel = document.createElement('strong');
    profileLabel.textContent = t('profileCard.open');
    const profileHint = document.createElement('span');
    profileHint.textContent = t('profileCard.openHint');
    profileRow.append(profileLabel, profileHint);
    profileRow.addEventListener('click', () => {
      hideIdentityPopover();
      onOpenProfile();
    });
  }
  let channelRow = null;
  if (typeof onOpenChannel === 'function') {
    channelRow = document.createElement('button');
    channelRow.type = 'button';
    channelRow.className = 'identity-variant identity-variant-action';
    channelRow.setAttribute('role', 'menuitem');
    const channelLabel = document.createElement('strong');
    channelLabel.textContent = t('public.openChannel');
    const channelHint = document.createElement('span');
    channelHint.textContent = t('chat.openChannelHint');
    channelRow.append(channelLabel, channelHint);
    channelRow.addEventListener('click', () => {
      hideIdentityPopover();
      onOpenChannel();
    });
  }
  const groupRows = [];
  const groupActionRow = menuRow;
  if (groupActions && typeof groupActions.onOpenMembers === 'function') {
    groupRows.push(groupActionRow(t('group.membersOpen'), t('group.membersCount', { count: groupActions.memberCount ?? 0 }), groupActions.onOpenMembers, true));
    if (typeof groupActions.onInvite === 'function') {
      groupRows.push(groupActionRow(t('group.inviteAction'), t('group.inviteHint'), groupActions.onInvite, true));
    }
  }
  if (typeof groupActions?.onCopyAskLink === 'function') {
    groupRows.push(groupActionRow(groupActions.linkLabel ?? t('group.askLinkAction'), groupActions.linkHint ?? t('group.askLinkHint'), groupActions.onCopyAskLink));
  }
  if (typeof groupActions?.onLeave === 'function') {
    groupRows.push(groupActionRow(t('group.leave'), groupActions.leaveHint ?? t('group.leaveHint'), groupActions.onLeave, true));
  }
  if (groupActions?.profilePin && typeof groupActions.profilePin.onToggle === 'function') {
    groupRows.push(groupActionRow(
      groupActions.profilePin.pinned ? t('group.profileUnpin') : t('group.profilePin'),
      groupActions.profilePin.hint ?? (groupActions.profilePin.pinned ? t('group.profileUnpinHint') : t('group.profilePinHint')),
      groupActions.profilePin.onToggle,
      true,
    ));
  }
  const actionRows = [...groupRows, profileRow, channelRow, pinRow, muteRow].filter(Boolean);
  if (actionRows.length > 0) {
    const actionsTitle = document.createElement('div');
    actionsTitle.className = 'identity-popover-title';
    actionsTitle.textContent = groupRows.length > 0 ? t('group.groupActions') : t('chat.contactActions');
    popover.append(actionsTitle, ...actionRows);
  }
  popover.classList.remove('is-closing');
  popover.hidden = false;
  positionIdentityPopover(popover, anchor);
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) {
    identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  }
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
}

async function copyGroupAskLink(groupId, record) {
  const wallet = walletAddressForCopy(plathoWallet);
  if (!wallet) return;
  let link = null;
  const entryFee = record?.entryFee ?? null;
  const ownerWallet = entryFee ? groupOwnerWallet(record) : null;
  try {
    link = groupAskLink(location.origin, encodeGroupAskToken({
      groupId, wallet, name: record?.name ?? null,
      ...(entryFee ? { entryFee, ownerWallet: ownerWallet ? displayWalletAddress(ownerWallet) : null } : {}),
    }));
  } catch (error) { console.warn('[groups] request link', error); flashWalletIdentityStatus(t('group.controlFailed')); return; }
  link = telegramSharedLinkFor(link);
  const shown = document.createElement('code');
  shown.className = 'group-ask-link';
  shown.textContent = link;
  shown.tabIndex = 0;
  await openActionDialog({
    title: t('group.askLinkAction'),
    hint: `${t('group.askLinkHint')} ${entryFee ? t('group.askLinkFee', { fee: formatAthAtomicUp(entryFee) }) : ''}`.trim(),
    submitLabel: t('dialog.shareCopyLink'),
    fields: [{ type: 'custom', render: () => shown }],
    validateSubmit: async () => {
      try {
        await copyTextToClipboard(link);
        return { ok: true };
      } catch (error) {
        console.warn('[groups] request link', error);
        return { ok: false, error: t('dialog.shareCopyFailed') };
      }
    },
  });
}

async function renameGroupRoom(groupId, record) {
  const runtime = await ensureGroupRuntime();
  if (!runtime) return;
  const held = String(record?.name ?? '');
  const price = () => groupChainPriceLine(runtime.controlPlan(groupId, GROUP_KIND.PROFILE, { name: held }), groupId);
  await openActionDialog({
    title: t('group.rename'),
    hint: () => joinHintSentences(t('group.renameHint'), price()),
    submitLabel: t('group.rename'),
    fields: [{
      id: 'name',
      label: t('group.nameLabel'),
      placeholder: t('group.namePlaceholder'),
      value: held,
      required: true,
      autocomplete: 'off',
    }],
    validateSubmit: async (values) => {
      const next = String(values?.name ?? '').trim();
      if (!next) return { ok: false, error: t('group.renameEmpty') };
      if (next === held) return { ok: true };
      try {
        const after = await runtime.setName(groupId, next);
        refreshThreadAfterMessageChange(ensureGroupThread(after));
        renderThreads();
        renderConversation();
        return { ok: true };
      } catch (error) {
        if (!noteTonRpcRateLimit(error)) console.warn('[groups] rename', error);
        return { ok: false, repaint: error?.code === 'PRICES_MOVED', error: groupWriteRefusalText(error) };
      }
    },
  });
}

async function setGroupEntryFeeDialog(groupId, record) {
  const runtime = await ensureGroupRuntime();
  if (!runtime) return;
  const held = record?.entryFee ?? null;
  const price = () => groupChainPriceLine(runtime.controlPlan(groupId, GROUP_KIND.PROFILE, { entryFee: held }), groupId);
  await openActionDialog({
    title: t('group.entryFee'),
    hint: () => joinHintSentences(t('group.entryFeeHint'), price()).replace(/\s+/g, ' '),
    submitLabel: t('common.save'),
    fields: [{
      id: 'fee',
      label: t('group.entryFeeLabel'),
      placeholder: '0',
      value: held ? formatDecimalAmount(held, 9, 9) : '',
      required: false,
      inputMode: 'decimal',
      autocomplete: 'off',
    }],
    summary: (values) => {
      const text = String(values?.fee ?? '').trim();
      if (!text || /^0+(?:[.,]0*)?$/.test(text)) return [{ label: t('group.entryFeeLabel'), value: t('group.entryFeeNone') }];
      try { return [{ label: t('group.entryFeeLabel'), value: `${formatDecimalAmount(parseDecimalAmount(text, 9, 'ATH'), 9, 9)} ATH` }]; }
      catch { return [{ label: t('group.entryFeeLabel'), value: t('group.entryFeeInvalid') }]; }
    },
    validateSubmit: async (values) => {
      const text = String(values?.fee ?? '').trim();
      let next = null;
      if (text && !/^0+(?:[.,]0*)?$/.test(text)) {
        try { next = parseDecimalAmount(text, 9, 'ATH').toString(); } catch { return { ok: false, error: t('group.entryFeeInvalid') }; }
      }
      if (next === held) return { ok: true };
      try {
        const after = await runtime.setEntryFee(groupId, next);
        refreshThreadAfterMessageChange(ensureGroupThread(after));
        renderThreads();
        renderConversation();
        return { ok: true };
      } catch (error) {
        if (!noteTonRpcRateLimit(error)) console.warn('[groups] entry fee', error);
        return { ok: false, repaint: error?.code === 'PRICES_MOVED', error: groupWriteRefusalText(error) };
      }
    },
  });
}

async function togglePinnedProfileGroup(groupId, record) {
  const wallet = rawWalletAddress(plathoWallet?.address);
  if (!wallet) return;
  const current = await readOwnProfileForPublish(wallet);
  if (!current) return;
  const held = normalizeProfileGroups(current?.groups ?? []);
  const pinned = held.some((entry) => entry.groupId === groupId);
  const next = pinned
    ? held.filter((entry) => entry.groupId !== groupId)
    : [...held, { groupId, name: record?.name ?? '', ...publicGroupPinFields(record) }];
  if (!pinned && held.length >= PROFILE_GROUPS_MAX) {
    flashWalletIdentityStatus(t('group.profilePinFull'));
    return;
  }
  const description = String(current?.description ?? '');
  const tags = Array.isArray(current?.tags) ? current.tags : [];
  const appearance = normalizeProfileAppearance(current?.appearance ?? null);
  const worn = normalizeProfileWornGift(current?.wornGift ?? null);
  const confirmed = await openActionDialog({
    title: pinned ? t('group.profileUnpin') : t('group.profilePin'),
    hint: () => joinHintSentences(groupProfilePinHint(groupId, pinned), channelProfilePriceLine(description, tags, appearance, worn, next)),
    submitLabel: pinned ? t('group.profileUnpin') : t('group.profilePin'),
    fields: [],
    validateSubmit: async () => {
      try {
        const published = await publishChannelProfile(description, tags, appearance, worn, next);
        setChannelProfileOptimistic(wallet, {
          description: published.description, tags: published.tags, ownerUsername: published.ownerUsername,
          appearance: published.appearance ?? null, wornGift: published.wornGift ?? null, groups: published.groups ?? next,
          balanceCard: published.balanceCard === true,
        }, published.createdAtSec);
        return { ok: true };
      } catch (error) {
        if (error?.code === 'PLATHO_WALLET_GRAM_REQUIRED') return { ok: false, error: String(error.message) };
        if (!noteTonRpcRateLimit(error)) console.warn('[groups] profile pin', error);
        return { ok: false, error: t('group.controlFailed') };
      }
    },
  });
  if (confirmed) renderProfileCardActions(wallet, true);
}


function publicGroupSelfIsAdmin(record) {
  return Boolean(record?.self) && isPublicGroupAdmin(record, record.self);
}

function publicGroupSelfIsOwner(record) {
  return Boolean(record?.self) && isPublicGroupOwner(record, record.self);
}

function publicGroupMenuActionsFor(groupId, record) {
  const admin = publicGroupSelfIsAdmin(record);
  return {
    memberCount: (record?.members ?? []).length,
    onOpenMembers: () => { void openPublicGroupMembersDialog(groupId); },
    onInvite: null,
    onCopyAskLink: () => { void copyPublicGroupJoinLink(groupId, record); },
    linkLabel: t('group.joinLinkAction'),
    linkHint: t('group.joinLinkHint'),
    onRename: admin ? () => { void renamePublicGroup(groupId, record); } : null,
    profilePin: admin && plathoWallet?.address
      ? { pinned: groupIsPinnedToProfile(groupId), hint: groupProfilePinHint(groupId, groupIsPinnedToProfile(groupId)), onToggle: () => { void togglePinnedProfileGroup(groupId, record); } }
      : null,
    picture: admin
      ? { label: record?.avatar ? t('group.avatarChange') : t('group.avatarSet'), onPick: () => { pendingGroupAvatarId = groupId; groupAvatarInput?.click(); } }
      : null,
    onLeave: publicGroupSelfIsOwner(record) ? () => { flashWalletIdentityStatus(t('group.leaveNeedsAdmin'), 3200); } : () => { void leavePublicGroup(groupId, record); },
    leaveHint: publicGroupSelfIsOwner(record) ? t('group.leaveNeedsAdmin') : null,
    pictureVisibility: t('group.publicAvatarVisibility'),
  };
}

function publicGroupControlPriceLine(kind, payload, room = null, { upTo = false } = {}) {
  let bytes;
  try { bytes = encodePublicGroupControl(kind, { ...payload, sentAt: Math.floor(Date.now() / 1000) }); } catch { return ''; }
  return publicGroupPriceLine([{ type: 'group', bytes }], room, { upTo });
}

async function joinPublicGroup(pointer, button) {
  if (!(pointer?.groupId instanceof Uint8Array) || !(pointer?.founder instanceof Uint8Array)) return;
  if (!plathoWallet?.address) {
    pendingPublicGroupJoinPointer = pointer;
    flashWalletIdentityStatus(t(hasStoredPlathoWalletRecord() ? 'wallet.unlockRequired' : 'common.walletRequired'));
    return;
  }
  const runtime = await ensurePublicGroupRuntime();
  if (!runtime) return;
  const idHex = [...pointer.groupId].map((b) => b.toString(16).padStart(2, '0')).join('');
  const held = runtime.get(idHex);
  if (held && !held.leftAt) { openGroupThread(ensureGroupThread(held)); return; }
  if (await groupIdOnOtherLane(idHex, 'public')) { flashWalletIdentityStatus(t('group.laneClash'), 3200); return; }
  const name = pointer.name || held?.name || t('group.untitled');
  const price = () => publicGroupControlPriceLine(PUBLIC_GROUP_KIND.JOIN, {}, null, { upTo: true });
  if (button) button.disabled = true;
  try {
    const confirmed = await runGroupControlDialog({
      title: t('group.joinTitle', { name }),
      hint: () => joinHintSentences(t('group.joinHint'), price()),
      submitLabel: t('group.joinSubmit'),
      unprompted: !button,
      act: async () => {
        const record = await runtime.join(pointer.groupId, {
          founder: pointer.founder, owner: pointer.owner ?? null, foundedEra: pointer.foundedEra ?? null, name: pointer.name ?? null,
        });
        const thread = ensureGroupThread(record);
        refreshThreadAfterMessageChange(thread);
        openGroupThread(thread);
        void syncGroupsFromChain();
      },
    });
    void confirmed;
  } finally {
    if (button) button.disabled = false;
  }
}

async function joinOrAskGroup(room, raw) {
  if (room?.founder) {
    void joinPublicGroup({
      public: true,
      groupId: hexToBytes(String(room.groupId)),
      founder: hexToBytes(String(room.founder)),
      owner: room.owner ? hexToBytes(String(room.owner)) : null,
      foundedEra: null,
      name: room.name || null,
    }, null);
    return;
  }
  void requestGroupJoin({ groupId: room.groupId, wallet: displayWalletAddress(raw), name: room.name || null, pinned: true }, null);
}

async function copyPublicGroupJoinLink(groupId, record) {
  void record;
  let link = null;
  try {
    const runtime = await ensurePublicGroupRuntime();
    const pointer = runtime?.pointerOf(groupId) ?? null;
    if (!pointer) throw new Error('no pointer for this group');
    link = publicGroupJoinLink(location.origin, encodePublicGroupJoinToken(pointer));
  } catch (error) { console.warn('[groups] join link', error); return; }
  link = telegramSharedLinkFor(link);
  const shown = document.createElement('code');
  shown.className = 'group-ask-link';
  shown.textContent = link;
  shown.tabIndex = 0;
  await openActionDialog({
    title: t('group.joinLinkAction'),
    hint: t('group.joinLinkHint'),
    submitLabel: t('dialog.shareCopyLink'),
    fields: [{ type: 'custom', render: () => shown }],
    validateSubmit: async () => {
      try {
        await copyTextToClipboard(link);
        return { ok: true };
      } catch (error) {
        console.warn('[groups] join link', error);
        return { ok: false, error: t('dialog.shareCopyFailed') };
      }
    },
  });
}

