    if (Array.isArray(partial) && partial.length > 0) publicDiscoveryResults = keep ? mergeCatalogueFrame(publicDiscoveryResults, partial) : partial;
    publicDiscoveryProgress = progress ? { done: Number(progress.done ?? 0), total: Number(progress.total ?? 0) } : null;
