async function readSelfSlotLedger({ force = false, only = null } = {}) {
  const seed = plathoWallet?.seed;
  const walletRaw = rawWalletAddress(plathoWallet?.address);
  if (!seed || !walletRaw) return null;
  if (!force && !only && selfSlotLedger?.walletRaw === walletRaw && Date.now() - selfSlotLedger.at < SELF_SLOT_LEDGER_FRESH_MS) return selfSlotLedger;
  const readStates = createSelfSlotStatesReader();
  if (!readStates) return null;
  const space = await selfSlotSpaceFor(seed, walletRaw);
  let states = null;
  try { states = await readStates((only ? space[only] ?? [] : space.all).map((slot) => slot.address)); } catch { states = null; }
  if (rawWalletAddress(plathoWallet?.address) !== walletRaw) return null;
  const trusted = states instanceof Map;
  const ledger = { walletRaw, at: Date.now(), trusted, states: trusted ? states : null, space };
  if (trusted && !only) selfSlotLedger = ledger;
  return ledger;
}

function selfSlotVerdicts(ledger, slots) {
  const stored = readSelfSlotMarkers();
  const verdict = { absent: [], moved: [], unmoved: [] };
  for (const slot of slots) {
    const key = publicAddrKey(slot.address);
    const state = ledger.states.get(key);
    if (state?.status === 'unknown') { verdict.moved.push(slot); continue; }
    if (!isActiveAccountState(state)) { verdict.absent.push(slot); continue; }
    const marker = changeMarkerOf(state);
    if (stored[key] === marker) verdict.unmoved.push(slot);
    else verdict.moved.push(slot);
  }
  return verdict;
}

function rememberSelfSlotMarkers(ledger, slots) {
  const markers = readSelfSlotMarkers();
  for (const slot of slots) {
    const key = publicAddrKey(slot.address);
    const state = ledger.states.get(key);
    const marker = isActiveAccountState(state) ? changeMarkerOf(state) : null;
    if (marker === null) delete markers[key];
    else markers[key] = marker;
  }
  writeSelfSlotMarkers(markers);
}

function forgetSelfSlotMarkers(slots) {
  const markers = readSelfSlotMarkers();
  let changed = false;
  for (const slot of slots) {
    const key = publicAddrKey(slot.address);
    if (key in markers) { delete markers[key]; changed = true; }
  }
  if (changed) writeSelfSlotMarkers(markers);
}

function selfSlotLedgerStatesReader(ledger) {
  return async (addresses) => {
    const out = new Map();
    for (const address of addresses) {
      const key = publicAddrKey(address);
      const state = ledger.states.get(key);
      if (state) out.set(key, state);
    }
    return out;
  };
}

function criticalRecoveryReaders(transport) {
  const run = (call) => transport.runGetMethod({ ...call, priority: 'critical', cacheTtlMs: 0 });
  return { readView: createRecoveryViewReader(run), readBody: createRecoveryBodyReader(run) };
}

async function restoreConvKeysFromRecoveryIfBehind(ledger = undefined) {
  if (!convKeyStore || !plathoWallet?.seed) return;
  const transport = globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;
  const storeEmpty = convKeyStore.snapshot().size === 0;
  if (!storeEmpty && convRecoveryRestoreAttempted && Date.now() - convRecoveryMergeCheckedAt < 60_000) return;
  const wallet = plathoWallet;
  try {
    if (ledger === undefined) ledger = await readSelfSlotLedger();
    if (plathoWallet !== wallet) return;
    if (ledger && ledger.walletRaw !== rawWalletAddress(wallet.address)) ledger = null;
    const trusted = ledger?.trusted === true;
    let onlySlots = null;
    if (storeEmpty && ledger?.space?.conv) forgetSelfSlotMarkers(ledger.space.conv);
    if (!storeEmpty) {
      if (!trusted) return;
      convRecoveryMergeCheckedAt = Date.now();
      const { moved } = selfSlotVerdicts(ledger, ledger.space.conv);
      if (moved.length === 0) {
        convRecoveryRestoreAttempted = true;
        convRecoveryBackupAllowed = true;
        return;
      }
      convRecoveryBackupAllowed = false;
      onlySlots = new Set(moved.map((slot) => publicAddrKey(slot.address)));
    }
    const { readView, readBody } = criticalRecoveryReaders(transport);
    const { map, found, clean } = await restoreConvKeysFromRecovery({
      seed: plathoWallet.seed, readView, readBody, onlySlots,
      readStates: trusted ? selfSlotLedgerStatesReader(ledger) : createSelfSlotStatesReader(),
    });
    if (plathoWallet !== wallet) return;
    const imported = map.size > 0 ? await convKeyStore.importConversations(map) : 0;
    globalThis.plathoLastConvRecoveryRestore = { imported, slots: found.length, clean, merged: !storeEmpty, at: new Date().toISOString() };
    if (clean) {
      convRecoveryRestoreAttempted = true;
      convRecoveryBackupAllowed = true;
      if (trusted && convKeyStorePersistent) rememberSelfSlotMarkers(ledger, ledger.space.conv);
    }
    if (imported > 0) {
      renderThreads();
      scheduleMessageAutoSync(2_000);
    }
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[recovery] restore failed', error);
  }
}

async function restorePrefsFromRecoveryIfFresh(ledger = undefined) {
  if (!plathoWallet?.seed) return;
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;
  const wallet = plathoWallet;
  try {
    if (ledger === undefined) ledger = await readSelfSlotLedger();
    if (plathoWallet !== wallet) return;
    if (ledger && ledger.walletRaw !== rawWalletAddress(wallet.address)) ledger = null;
    if (ledger?.trusted === true) {
      const { moved } = selfSlotVerdicts(ledger, ledger.space.prefs);
      if (moved.length === 0) {
        prefsBackupAllowed = true;
        prefsRestoreSettled = true;
        applyRestoredConversationFollows();
        return;
      }
    }
    const { readView, readBody } = criticalRecoveryReaders(transport);
    const { chunks, clean } = await restorePrefsChunks({
      seed: wallet.seed, readView, readBody,
      readStates: ledger?.trusted === true ? selfSlotLedgerStatesReader(ledger) : createSelfSlotStatesReader(),
    });
    if (plathoWallet !== wallet) return;
    prefsBackupAllowed = clean === true;
    const snapshot = clean === true ? mergePrefsSnapshotChunks(chunks) : null;
    if (snapshot) {
      pendingRestoredPrefsSnapshots.push(snapshot);
      if (drainRestoredPrefsSnapshots()) { rebuildPublicChannelRegistry(); renderThreads(); }
    }
    if (clean === true) { prefsRestoreSettled = true; applyRestoredConversationFollows(); }
    if (clean === true && ledger?.trusted === true) rememberSelfSlotMarkers(ledger, ledger.space.prefs);
  } catch (error) {
    prefsBackupAllowed = false;
    if (!noteTonRpcRateLimit(error)) console.warn('[prefs] recovery restore failed', error);
  }
}

let selfNotesRestoreIncomplete = true;
const NOTES_DURABLE_RESTORE_KEY = 'platho.notes.durableRestore.v2';
function notesDurableRestoreKey(owner = plathoWallet?.address) {
  const raw = rawWalletAddress(owner);
  return raw ? `${NOTES_DURABLE_RESTORE_KEY}:${deploymentStorageSuffix()}:${raw}` : null;
}
function notesDurableCount(owner) {
  const key = notesDurableRestoreKey(owner);
  if (!key) return null;
  try {
    const parsed = JSON.parse(walletLocalStorage().getItem(key) ?? 'null');
    const count = Number(parsed?.count);
    return Number.isSafeInteger(count) && count >= 0 ? count : null;
  } catch { return null; }
}
function markNotesDurablyRestored(owner, count) {
  const key = notesDurableRestoreKey(owner);
  if (!key || !Number.isSafeInteger(count) || count < 0) return;
  try { walletLocalStorage().setItem(key, JSON.stringify({ count })); } catch { }
}
async function savedThreadHoldsRestoredNotes(thread, owner) {
  const need = notesDurableCount(owner);
  if (need === null) return false;
  if (need === 0) return true;
  if (typeof encryptedMessageStore?.countThreadMessages !== 'function' || !thread?.id) return false;
  try { return (await encryptedMessageStore.countThreadMessages(thread.id)) >= need; } catch { return false; }
}

async function restoreSelfNotesFromRecovery(ledger = undefined) {
  const seed = plathoWallet?.seed;
  if (!seed) return;
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;
  const thread = threads.find((item) => isRealSavedThread(item));
  if (!thread) return;
  const wallet = plathoWallet;
  try {
    if (ledger === undefined) ledger = await readSelfSlotLedger();
    if (plathoWallet !== wallet) return;
    if (ledger && ledger.walletRaw !== rawWalletAddress(wallet.address)) ledger = null;
    if (ledger?.trusted === true && await savedThreadHoldsRestoredNotes(thread, wallet.address)) {
      if (plathoWallet !== wallet) return;
      const { moved } = selfSlotVerdicts(ledger, ledger.space.notes);
      if (moved.length === 0) {
        selfNotesRestoreIncomplete = false;
        return;
      }
    }
    const { readView, readBody } = criticalRecoveryReaders(transport);
    const { notes, clean } = await restoreNotes({
      seed, readView, readBody,
      readStates: ledger?.trusted === true ? selfSlotLedgerStatesReader(ledger) : createSelfSlotStatesReader(),
    });
    if (plathoWallet !== wallet) return;
    selfNotesRestoreIncomplete = !clean;
    if (clean && ledger?.trusted === true) rememberSelfSlotMarkers(ledger, ledger.space.notes);
    const held = await selfNotesForBackup(thread);
    if (plathoWallet !== wallet) return;
    const known = new Set(held.map((note) => `${note.at}:${note.text}`));
    const chainNotes = new Map();
    for (const note of notes) {
      const text = String(note?.text ?? '');
      if (text.trim().length === 0) continue;
      const at = Number(note.at) || 0;
      chainNotes.set(`${at}:${text}`, { at, text });
    }
    if (clean) markNotesDurablyRestored(wallet.address, chainNotes.size);
    if (chainNotes.size === 0) return;
    let added = 0;
    for (const [id, note] of [...chainNotes].sort((a, b) => a[1].at - b[1].at)) {
      if (known.has(id)) continue;
      known.add(id);
      const message = { type: 'out', text: note.text, meta: 'published', ...localMessageOrderFields(note.at) };
      insertThreadMessage(thread, message);
      await persistMessageToEncryptedHistory(thread, message);
      added += 1;
    }
    if (added === 0) return;
    refreshThreadAfterMessageChange(thread);
    renderThreads();
    renderConversation();
    if (!clean) console.warn('[notes] restore was incomplete — some chunks did not load; saving is held');
  } catch (error) {
    selfNotesRestoreIncomplete = true;
    if (!noteTonRpcRateLimit(error)) console.warn('[notes] recovery restore failed', error);
  }
}

const RECOVERY_BACKUP_DEBOUNCE_MS = 45_000;
let recoveryBackupTimer = null;
const convRecoveryDirtySlots = new Set();
const convRecoveryDirtyMarks = new Map();
const RECOVERY_QUIET_MIN_MS = 6 * 3_600_000;
const RECOVERY_QUIET_SPAN_MS = 42 * 3_600_000;
const RECOVERY_QUIET_AFTER_UNLOCK_MIN_MS = 2 * 60_000;
const RECOVERY_QUIET_AFTER_UNLOCK_SPAN_MS = 18 * 60_000;
const RECOVERY_QUIET_URGENT_AFTER_MS = 5 * 86_400_000;
const RECOVERY_QUIET_URGENT_MIN_MS = 20_000;
const RECOVERY_QUIET_URGENT_SPAN_MS = 40_000;
const RECOVERY_QUIET_LATE_MS = 5 * 60_000;
const RECOVERY_QUIET_TIMER_MAX_MS = 6 * 3_600_000;
const RECOVERY_QUIET_SLOTS_PER_DAY = 4;
const RECOVERY_QUIET_BUDGET_WINDOW_MS = 86_400_000;
const RECOVERY_QUIET_FUTURE_SLACK_MS = 3_600_000;
const RECOVERY_QUIET_SPENT_STORAGE_KEY = 'platho.recovery.quiet-spent.v1';
const RECOVERY_QUIET_SPENT_SEAL_DOMAIN = 'platho.recovery-quiet-spent.v1';
const RECOVERY_PENDING_STORAGE_KEY = 'platho.recovery.pending.v1';
const RECOVERY_PENDING_SEAL_DOMAIN = 'platho.recovery-pending.v2';
