        cancellable: true,
        passwordManagerUsername: shown?.address,
        passwordManagerNetworkGlobalId: shown?.networkGlobalId,
        before: picker ? [{ id: 'unlockWallet', name: 'unlockWallet', label: t('wallet.unlockWhichWallet'), type: 'select', value: picked.value,
          options: picker.map(({ value, label }) => ({ value, label })) }] : [],
