function estimatedChannelProfileChargeNanotons(description, tags, appearance = null, wornGift = null, groups = null, balanceCard = publishedBalanceCard()) {
  const desc = String(description ?? '').trim();
  const normalizedTags = normalizeProfileTags(tags);
  const linkedLabel = readLinkedPlathoUsername(plathoWallet?.address)?.label ?? '';
  const ownerUsername = linkedLabel ? canonicalUsernameDisplay(linkedLabel) : '';
  const documentBytes = encodeMessageDocumentBlocks([{ type: 'profile', description: desc, tags: normalizedTags, ownerUsername, appearance, wornGift: normalizeProfileWornGift(wornGift), groups: normalizeProfileGroups(groups), balanceCard: balanceCard === true }]);
  const parts = splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES);
  return composerEstimatedNetCostNanotons(channelProfilePublishProfiles(parts), 1);
}

function channelProfilePriceLine(description, tags, appearance = null, wornGift = null, groups = null, balanceCard = publishedBalanceCard()) {
  const desc = String(description ?? '').trim();
  const linkedLabel = readLinkedPlathoUsername(plathoWallet?.address)?.label ?? '';
  const documentBytes = encodeMessageDocumentBlocks([{
    type: 'profile', description: desc, tags: normalizeProfileTags(tags), ownerUsername: linkedLabel ? canonicalUsernameDisplay(linkedLabel) : '',
    appearance, wornGift: normalizeProfileWornGift(wornGift), groups: normalizeProfileGroups(groups), balanceCard: balanceCard === true,
  }]);
  const bytes = splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES)[0]?.length ?? documentBytes.length;
  const nowUnix = chainNowSec();
  const generation = generationForUnixSeconds(nowUnix);
  const prices = composerNetworkPrices();
  const shard = composerChannelShardFact(nowUnix);
  const channelFirst = !(shard?.live === true);
  const parts = [{ bytes }];
  const cost = publicPartsFinalCost({ generation, kind: 0, parts, first: channelFirst, entryIndex: channelFirst ? 1 : Number(shard.entries ?? 1) + 1, prices, nowUnix })
    + publicPartsFinalCost({ generation, kind: 2, parts, first: true, prices, nowUnix })
    - walletOnceFinalCost({ generation, prices });
  const hold = estimatedChannelProfileChargeNanotons(description, tags, appearance, wornGift, groups, balanceCard)
    + composerPublicRoutedHoldExtra(0, parts, channelFirst, generation, nowUnix)
    + composerPublicRoutedHoldExtra(2, parts, true, generation, nowUnix);
  return composerCostAndHoldLine({ cost, hold, upTo: true }).text;
}

function composerCostPrecondition(parts, { ignoreTonRpcLimit = false } = {}) {
  if (!plathoWallet) { const text = walletNeededReason(); return { text, state: 'short', parts, action: activationComposerAction(text) }; }
  if (ignoreTonRpcLimit !== true && tonRpcLimited()) return { text: TON_RPC_CONNECTING_STATUS, state: 'short', parts };
  if (pendingServiceWorkerAppShellReload === true) return { text: t('common.updateReadyReload'), state: 'short', parts };
  return null;
}



let composerFactReadsHeld = 0;
function withoutComposerFactReads(fn) {
  composerFactReadsHeld += 1;
  try { return fn(); } finally { composerFactReadsHeld -= 1; }
}

function composerChainFact(key, read, ttlMs = COMPOSER_FACT_TTL_MS) {
  if (composerFactReadsHeld > 0) return composerChainFacts.get(key)?.value;
  const held = composerChainFacts.get(key);
  if (!held || (!held.pending && Date.now() - held.at >= ttlMs)) {
    if (!held && composerChainFacts.size >= COMPOSER_FACT_LIMIT) composerChainFacts.delete(composerChainFacts.keys().next().value);
    composerChainFacts.set(key, { at: held?.at ?? 0, value: held?.value, pending: true });
    Promise.resolve().then(read).then((value) => {
      composerChainFacts.set(key, { at: Date.now(), value, pending: false });
      refreshComposerCostStatus();
    }, (error) => {
      noteTonRpcRateLimit(error);
      composerChainFacts.set(key, { at: Date.now(), value: held?.value, pending: false });
    });
  }
  return composerChainFacts.get(key)?.value;
}

function forgetComposerChainFacts() {
  for (const key of [...composerChainFacts.keys()]) if (!COMPOSER_KEPT_FACTS.has(key)) composerChainFacts.delete(key);
}

function composerNetworkPrices() {
  return composerChainFact('network-prices', () => readNetworkPrices({ priority: 'background' })) ?? null;
}

function composerVaultTerms() {
  const mine = feeVaultState.wallet === plathoWallet?.address ? feeVaultState.snapshot : null;
  if (!mine || mine.state === VAULT_UNKNOWN || vaultSnapshotOutdated()) composerChainFact('vault', () => refreshFeeVaultState());
  const fresh = mine?.state === VAULT_LIVE && !mine.stale && !mine.assumed && !vaultSnapshotOutdated();
  const kept = !fresh && (!mine || mine.state === VAULT_UNKNOWN) && rememberedVaultReading
    && rememberedVaultReading.wallet === plathoWallet?.address ? rememberedVaultReading : null;
  if (kept) return { feeDue: ownVaultFeeDue({ feeDue: kept.feeDue, nowSec: 0 }), vaultDeposit: kept.low === true };
  return {
    feeDue: fresh ? ownVaultFeeDue(mine) : FV_PROTOCOL_FEE,
    vaultDeposit: !mine || mine.state !== VAULT_LIVE
      || (mine.assumed !== true && BigInt(mine.balance ?? 0n) < FV_FLOAT_TOPUP_BELOW),
  };
}

function composerConvShardFact(thread) {
  const selfKeyId = localRecipientKeyPair?.keyId;
  const peerKeyId = thread?.convPeerKeyId ?? null;
  const rec = selfKeyId && peerKeyId ? (convKeyStore?.getConversation(selfKeyId, peerKeyId) ?? null) : null;
  if (!rec?.kRootCurrent) return { rec, fact: null };
  const fact = composerChainFact(`conv:${conversationId(selfKeyId, peerKeyId)}:${currentEpochUtc(walletChainNowMs())}`, async () => {
    const route = await outgoingRecordShard({ kRoot: rec.kRootCurrent, selfKeyId, peerKeyId, createdAtSec: chainNowSec() });
    const transport = globalThis.plathoTonRpcTransport;
    const coldFloor = rec.outgoingSeq?.[route.epoch] === undefined
      ? Number(await createRecordShardLastSeqReader((call) => transport.runGetMethod({ ...call, priority: 'background' }))(route.address))
      : 0;
    return { address: route.address, epoch: route.epoch, coldFloor };
  });
  return { rec, fact };
}

function composerPrivateMessageShape(thread) {
  const { rec, fact } = composerConvShardFact(thread);
  const epoch = currentEpochUtc(walletChainNowMs());
  const local = rec?.outgoingSeq?.[epoch];
  const claimed = Number(local ?? 0) > 0;
  if (!fact || fact.epoch !== epoch) return { first: !claimed, halves: claimed, recordIndex: Number(local ?? 0) + 1 };
  const floor = Math.max(local === undefined ? Number(fact.coldFloor ?? 0) : 0, convBucketSeqHighWater(fact.address), 0);
  const live = floor > 0;
  return { first: !live && !claimed, halves: !live && claimed, recordIndex: Math.max(Number(local ?? 0), floor) + 1 };
}

function groupLaneShape(groupId, lane = 'daily') {
  const record = groupId ? (groupRuntimeInstance?.get?.(groupId) ?? null) : null;
  const state = record ? currentGroupEpoch(record) : null;
  if (lane === 'avatar' || !state || Number(state.epoch) !== currentEpochUtc(walletChainNowMs())) return { first: true, recordIndex: 1 };
  const wrote = Number(record.seqHighWater?.[`${lane === 'roster' ? 'r.' : ''}${state.epoch}.${state.generation}`] ?? 0);
  const proven = groupRuntimeInstance?.laneProvenLive?.(groupId, lane === 'roster' ? 'roster' : 'daily') === true;
  return { first: !(wrote > 0 && proven), recordIndex: wrote + 1 };
}

function composerGroupLaneShape(thread) {
  return groupLaneShape(groupIdOfThread(thread), 'daily');
}

function composerFirstContactFact(thread) {
  return composerChainFact(`intro:${thread?.id ?? ''}:${currentEpochUtc(walletChainNowMs())}`, async () => {
    const peerWallet = requireBasechainAddress(await resolveRecipientWalletForThread(thread), 'Recipient wallet');
    const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
    const provider = createKeyShardTonRpcProvider({
      profileRegistryAddress: registry, predecessorRegistryAddress: configuredProfileRegistryPredecessorAddress(),
      decodeAddressSliceBoc: decodeTonAddressSliceBoc,
    });
    const bundle = await resolveRecipientBundleByWallet({ provider, wallet: peerWallet, callOptions: { priority: 'background' } });
    const transport = globalThis.plathoTonRpcTransport;
    const readScanPage = createScanPageReader((call) => transport.runGetMethod({ ...call, priority: 'background' }));
    const slot = await pickIntroSendSlot({ readScanPage, epoch: currentEpochUtc(walletChainNowMs()) });
    return { peerKeyId: bundle.keyId, fill: Math.max(0, Number(slot.expectedEntryId ?? 0)) };
  }, COMPOSER_INTRO_FACT_TTL_MS);
}

function composerFirstContactExtraNanotons(thread, generation, prices) {
  const fact = composerFirstContactFact(thread);
  const fill = fact ? fact.fill : 0;
  let newSlot = true;
  let conversations = 1;
  const selfKeyId = localRecipientKeyPair?.keyId;
  if (fact?.peerKeyId && selfKeyId) {
    const slot = recoverySlotForConversation(conversationId(selfKeyId, fact.peerKeyId));
    const partition = partitionRecoveryMap(convKeyStore?.snapshot?.() ?? new Map()).get(slot);
    newSlot = !(partition?.size > 0);
    conversations = (partition?.size ?? 0) + 1;
  }
  return introFinalCost({ generation, born: fill === 0, entryIndex: fill + 1, prices })
    + recoveryWriteFinalCost({ newSlot, conversations, prices });
}

function composerCostAndHoldLine({ cost, hold, setup = 0n, parts = 1, upTo = false }) {
  const setupText = setup > 0n
    ? t('composer.vaultSetupSuffix', { amount: formatTonNanotonsUp(setup), label: t('profile.stakeSummarySetup') })
    : '';
  const params = { cost: formatTonNanotonsUp(cost), setup: setupText, surcharge: setupText, hold: formatTonNanotonsUp(hold) };
  const balance = vaultPocketState?.wallet?.ton_balance;
  if (typeof balance === 'bigint' && balance < hold) {
    return {
      text: t(upTo ? 'composer.needHoldStatusUpTo' : 'composer.needHoldStatus', { ...params, available: formatTonNanotons(balance) }), state: 'short', parts,
      action: { label: t('wallet.receiveGram'), run: () => { void showReceiveWalletTonDialog(); } },
    };
  }
  return { text: t(upTo ? 'composer.costStatus' : 'composer.costFinal', params), state: 'ready', parts };
}

function balanceNeededText(hold, { intoVault = false } = {}) {
  const balance = vaultPocketState?.wallet?.ton_balance;
  return typeof balance === 'bigint' && balance < hold
    ? t('common.balanceNeededShort', { amount: formatTonNanotonsUp(hold), available: formatTonNanotons(balance) })
    : t(intoVault ? 'common.balanceNeededVaultValue' : 'common.balanceNeededValue', { amount: formatTonNanotonsUp(hold) });
}

function privateComposerFinalCostLine(thread, plan) {
  const classes = (Array.isArray(plan) && plan.length > 0 ? plan : [{ sizeClass: 1 }]).map((part) => Number(part?.sizeClass ?? 1));
  const { cost, deposit, hold } = privateMessagePriceAndHold(thread, plan);
  return composerCostAndHoldLine({ cost, setup: deposit, hold, parts: classes.length });
}

function privateMessagePriceAndHold(thread, plan, { afterDeploy = false } = {}) {
  const hold = composerEstimatedNetCostNanotons(privateComposerPublishProfilesForPlan(plan), 1, { afterDeploy }) + privateFirstContactExtraNanotons(thread);
  const { cost, deposit } = privateMessageFinalCost(thread, plan, { afterDeploy });
  return { cost, deposit, hold };
}

function privateMessageFinalCost(thread, plan, { afterDeploy = false } = {}) {
  const generation = generationForUnixSeconds(chainNowSec());
  const prices = composerNetworkPrices();
  const classes = (Array.isArray(plan) && plan.length > 0 ? plan : [{ sizeClass: 1 }]).map((part) => Number(part?.sizeClass ?? 1));
  const group = isGroupThread(thread);
  const firstContact = !group && Boolean(thread) && !thread.convPeerKeyId;
  const shape = group ? composerGroupLaneShape(thread)
    : firstContact ? { first: true, recordIndex: 1 }
    : composerPrivateMessageShape(thread);
  const vault = generation >= 18 ? composerVaultTerms() : { feeDue: null, vaultDeposit: false };
  const message = convMessageFinalCost({
    generation, sizeClasses: classes, first: shape.first, halves: shape.halves === true, recordIndex: shape.recordIndex,
    feeDue: vault.feeDue, vaultDeposit: vault.vaultDeposit === true && !afterDeploy, prices,
  });
  const extra = firstContact ? composerFirstContactExtraNanotons(thread, generation, prices) : 0n;
  return { cost: message.cost + extra, deposit: message.deposit };
}

function composerChannelShardFact(nowUnix) {
  if (!plathoWallet?.address) return null;
  const epochTag = publicEpochTag(0, publicEraOf(0, nowUnix));
  const walletHash = publicWalletHash(plathoWallet.address);
  return composerChainFact(`channel:${plathoWallet.address}:${epochTag}`, () => resolvePublicWriteShard(directPublicLaneReader(), {
    kind: 0, partitionKeyOf: (seq) => publicChannelPartitionKey(walletHash, seq), epochTag, need: 1, nowUnix,
  }));
}

function composerThreadShardFact(target, nowUnix) {
  const epochTag = publicEpochTag(1, publicEraOf(1, nowUnix));
  const key = target?.postUid !== undefined ? `uid:${target.postUid}` : `post:${target?.id ?? ''}:${target?.entryId ?? ''}`;
  return composerChainFact(`thread:${key}:${epochTag}`, async () => {
    let postUid = target?.postUid;
    if (postUid === undefined) {
      const coords = publicPostChainCoordinates(target);
      if (!coords) return { seq: 0, live: false };
      const channelPk = await publicChannelPartitionKey(publicWalletHash(coords.authorWallet), coords.shardSeq);
      postUid = await publicPostUid(channelPk, coords.epochTag, coords.shardEntryId, coords.generation);
    }
    return resolvePublicWriteShard(directPublicLaneReader(), {
      kind: 1, partitionKeyOf: (seq) => publicThreadPartitionKey(BigInt(postUid), seq), epochTag, need: 1, nowUnix,
    });
  });
}

function composerPublicRoutes(kind, parts, first, generation, nowUnix) {
  const direct = { routes: parts.map(() => 'direct'), feeDue: null };
  if (generation < 18 || !vaultSupported() || feeVaultState.wallet !== plathoWallet?.address || !feeVaultState.address) return direct;
  const snapshot = feeVaultState.snapshot;
  if (vaultSnapshotOutdated()) { composerChainFact('vault', () => refreshFeeVaultState()); return direct; }
  if (snapshot?.state !== VAULT_LIVE || snapshot.stale || snapshot.assumed) return direct;
  const epochTag = publicEpochTag(kind, publicEraOf(kind, nowUnix));
  const stateInit = { code: publicShardCodeCellFor(generation), data: publicShardDataCellFor(0n, epochTag) };
  const feeDue = ownVaultFeeDue(snapshot);
  const prices = composerNetworkPrices();
  const routes = parts.map((part, index) => publicPublishRoute({
    kind, feeDue, prices,
    capsuleBytes: BigInt(part.bytes + 91 + 3 * Math.ceil(part.bytes / 127)),
    stateInit: first && index === 0 ? stateInit : null,
  }).route);
  return { routes, feeDue };
}

function composerPublicRoutedHoldExtra(kind, parts, first, generation, nowUnix) {
  const { routes, feeDue } = composerPublicRoutes(kind, parts, first, generation, nowUnix);
  if (!routes.includes('vault')) return 0n;
  const directValue = publicPublishValueForKind(kind, generation);
  const prices = composerNetworkPrices();
  const directLive = directValue + publicDirectLiveExtraNanotons(prices);
  const epochTag = publicEpochTag(kind, publicEraOf(kind, nowUnix));
  let extra = 0n;
  parts.forEach((part, index) => {
    if (routes[index] !== 'vault') return;
    const stateInit = first && index === 0 ? { code: publicShardCodeCellFor(generation), data: publicShardDataCellFor(0n, epochTag) } : null;
    const attach = vaultInternalPublishValue({
      directValue, capsuleBytes: BigInt(part.bytes + 91 + 3 * Math.ceil(part.bytes / 127)), feeDue, stateInit, prices,
      shardGas: FV_PUBLIC_SHARD_PUBLISH_GAS_MAX,
    });
    if (attach > directLive) extra += attach - directLive;
  });
  return extra;
}

function publicComposerFinalCostLine(plan, target = null, hold = null) {
  const row = publicRowFinalCost(plan, target ?? (publicCommentTarget ? publicCommentTarget : null));
  const need = (hold ?? composerEstimatedNetCostNanotons(publicComposerPublishProfilesForPlan(plan, row.kind), 1))
    + composerPublicRoutedHoldExtra(row.kind, row.routedParts, row.first, row.generation, row.nowUnix);
  return composerCostAndHoldLine({ cost: row.cost, hold: need, parts: row.parts });
}

function publicRowFinalCost(plan, thread) {
  const nowUnix = chainNowSec();
  const generation = generationForUnixSeconds(nowUnix);
  const prices = composerNetworkPrices();
  const parts = (Array.isArray(plan) && plan.length > 0 ? plan : [{ bytes: 0 }])
    .map((part) => ({ bytes: Number(part?.bytes?.length ?? part?.bytes ?? 0) }));
  const kind = thread ? 1 : 0;
  const shard = thread ? composerThreadShardFact(thread, nowUnix) : composerChannelShardFact(nowUnix);
  const first = !(shard?.live === true);
  const entryIndex = first ? 1 : Number(shard.entries ?? 1) + 1;
  return {
    cost: publicPartsFinalCost({ generation, kind, parts, first, entryIndex, prices, nowUnix }), kind, parts: parts.length,
    routedParts: parts, first, generation, nowUnix,
  };
}

function publicPartsFinalCost({ generation, kind, parts, first = false, halves = false, entryIndex = null, prices = null, nowUnix }) {
  const { routes, feeDue } = composerPublicRoutes(kind, parts, first || halves, generation, nowUnix);
  const vaultParts = parts.filter((_, index) => routes[index] === 'vault');
  const directParts = parts.filter((_, index) => routes[index] !== 'vault');
  const priced = (list, route, lead, index) => (list.length === 0 ? 0n
    : publicPostFinalCost({ generation, kind, parts: list, first: lead && first, halves: lead && halves, entryIndex: index, route, feeDue, prices }));
  const firstRoute = routes[0] ?? 'direct';
  let cost = priced(firstRoute === 'vault' ? vaultParts : directParts, firstRoute, true, entryIndex);
  const others = firstRoute === 'vault' ? directParts : vaultParts;
  if (others.length > 0) {
    const alone = priced(others, firstRoute === 'vault' ? 'direct' : 'vault', false, entryIndex === null ? null : entryIndex + parts.length - others.length);
    const once = publicPostFinalCost({ generation, kind, parts: [{ bytes: 0 }], prices })
      + publicPostFinalCost({ generation, kind, parts: [{ bytes: 0 }], prices })
      - publicPostFinalCost({ generation, kind, parts: [{ bytes: 0 }, { bytes: 0 }], prices });
    cost += alone - once;
  }
  return cost;
}

function composerAvatarShardFact(nowUnix, generation) {
  if (!plathoWallet?.address) return undefined;
  const wallet = plathoWallet.address;
  const epochTag = publicEpochTag(3, publicEraOf(3, nowUnix));
  return composerChainFact(`avatar:${wallet}:${epochTag}:${generation}`, async () => {
    const partitionKey = await publicAvatarPartitionKey(publicWalletHash(wallet));
    const address = rawShardAddress(await publicShardAddressBytesFor(generation, partitionKey, epochTag));
    const verdict = await defaultShardDebtResolver()(address, LANE_PUBLIC, nowUnix);
    return verdict?.status === 'active';
  });
}

function profileAvatarFinalCostNanotons(attachment) {
  const nowUnix = chainNowSec();
  const generation = generationForUnixSeconds(nowUnix);
  const prices = composerNetworkPrices();
  const parts = imagePartsForSend(attachment, 'profile avatar').map((part) => ({ bytes: Number(part?.bytes?.length ?? 0) }));
  const live = composerAvatarShardFact(nowUnix, generation) === true;
  return publicPartsFinalCost({ generation, kind: 3, parts, first: !live, halves: live, prices, nowUnix })
    + avatarRequestFinalCost({ prices, withParts: true, generation });
}

function publicGroupUidOfThread(thread) {
  return publicGroupUidOf(groupIdOfThread(thread));
}

function publicGroupUidOf(groupId) {
  const record = groupId ? (publicGroupRuntimeInstance?.get?.(groupId) ?? null) : null;
  if (!record?.founder) return null;
  try { return publicGroupChatUid(record.groupId, record.founder); } catch { return null; }
}

function publicGroupRowPrice(blocks, room = null) {
  let plan;
  try { plan = publicSendPlanFromDocumentBytes(encodeMessageDocumentBlocks(publicGroupDocumentBlocks(blocks))); } catch { plan = []; }
  const uid = room?.uid ?? publicGroupUidOf(room?.groupId ?? null);
  const row = publicRowFinalCost(plan, uid === null ? { kind: 1 } : { kind: 1, postUid: uid });
  return {
    cost: row.cost,
    hold: publicGroupChargeFor(blocks).nanotons + composerPublicRoutedHoldExtra(row.kind, row.routedParts, row.first, row.generation, row.nowUnix),
    parts: row.parts,
  };
}

const INTRO_CAPSULE_SIZE_CLASS = 2;

const KEYSHARD_REGISTER_SIZE_CLASS = 4;

function privateFirstContactExtraNanotons(thread) {
  if (!thread || isRealSavedThread(thread)) return 0n;
  if (isGroupThread(thread)) return 0n;
  if (thread.convPeerKeyId) return 0n;
  return INTRO_PUBLISH_VALUE + introDirectLiveExtraNanotons() + squatCushionNanotons(LANE_INTRO) + walletSendFeeReserveNanotons([INTRO_CAPSULE_SIZE_CLASS])
    + privateFirstContactRecoveryExtraNanotons();
}

const RECOVERY_BLOB_ENVELOPE_BYTES = 256;
const RECOVERY_BLOB_BYTES_PER_CONVERSATION = 375;

function recoveryBackupSizeClassAfterOneMore() {
  let widest = 0;
  const map = convKeyStore?.snapshot?.() ?? new Map();
  for (const partition of partitionRecoveryMap(map).values()) {
    if (partition.size > widest) widest = partition.size;
  }
  return walletSendSizeClassForPayloadBytes(
    RECOVERY_BLOB_ENVELOPE_BYTES + RECOVERY_BLOB_BYTES_PER_CONVERSATION * (widest + 1),
  );
}

function privateFirstContactRecoveryExtraNanotons() {
  return RECOVERY_PUBLISH_VALUE + walletSendFeeReserveNanotons([recoveryBackupSizeClassAfterOneMore()]);
}

function selfNotesComposerCostLine(thread = activeThread()) {
  if (!plathoWallet) { const text = walletNeededReason(); return { text, state: 'short', parts: 1, action: activationComposerAction(text) }; }
  const sizeClass = capsuleSizeClassForUsefulBytes(minimalCapsuleUsefulBytesForLength(NOTES_SLOT_MAX_BLOB_BYTES));
  const hold = RECOVERY_PUBLISH_VALUE + walletSendFeeReserveNanotons([sizeClass]);
  const cost = recoveryWriteFinalCost({
    newSlot: !(thread?.messages?.length > 0), blobBytes: NOTES_SLOT_MAX_BLOB_BYTES, prices: composerNetworkPrices(),
  });
  return composerCostAndHoldLine({ cost, hold, parts: 1, upTo: true });
}

function walletNeededReason() {
  return walletLockedOnDevice() ? t('chat.unlockToSend') : t('common.walletRequired');
}
function walletUnlockAction() {
  if (!walletLockedOnDevice() || !unlockWalletButton || unlockWalletButton.disabled) return null;
  return { label: t('wallet.unlock'), run: () => unlockWalletButton.click() };
}
function activationComposerAction(reason) {
  if (reason === t('chat.unlockToSend')) return walletUnlockAction();
  if (reason === t('send.vaultFrozen')) return { label: t('profile.vaultRestoreAction'), run: (event) => { void openVaultRestoreDialog({ line: event?.currentTarget?.parentNode ?? null }); } };
  if (!plathoWallet || hasActivePlathoAccount() || !activationAnswerKnownFor(plathoWallet.address)) return null;
  if (reason !== t('send.activateBeforeSending') && reason !== publicComposerBlockReason()) return null;
  if (!registerVaultKeysButton || registerVaultKeysButton.disabled) return null;
  return { label: t('wallet.activateAccount'), run: (event) => { void runAccountActivation({ line: event?.currentTarget?.parentNode ?? null }); } };
}

function paintComposerCostLine(node, status) {
  if (!node) return;
  const until = composerPricesMovedNotice.get(node) ?? 0;
  const notice = until > Date.now();
  if (!notice) composerPricesMovedNotice.delete(node);
  const text = notice ? `${t('dialog.pricesMoved')}\n${status.text}` : status.text;
  const action = status.action && !notice ? status.action : null;
  const standing = action && node.dataset.actionText === text ? node.querySelector?.('.composer-cost-action') : null;
  if (!standing || standing.textContent !== action.label) {
    const focused = globalThis.document?.activeElement;
    const had = Boolean(focused) && Boolean(node.contains?.(focused));
    node.textContent = text;
    if (action) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'composer-cost-action';
      button.textContent = action.label;
      button.addEventListener('click', action.run);
      node.append(' ', button);
      node.dataset.actionText = text;
      if (had) { try { button.focus({ preventScroll: true }); } catch { } }
    } else {
      delete node.dataset.actionText;
    }
    if (had && !node.contains?.(globalThis.document?.activeElement)) {
      if (!node.hasAttribute?.('tabindex')) node.setAttribute?.('tabindex', '-1');
      try { node.focus({ preventScroll: true }); } catch { }
    }
  }
  node.dataset.state = status.state;
  node.dataset.pricedGeneration = String(writeGenerationNow());
  if (notice) node.dataset.notice = 'prices-moved';
  else delete node.dataset.notice;
}

function announceComposerPricesMoved(statusElement) {
  if (!statusElement) return;
  composerPricesMovedNotice.set(statusElement, Date.now() + STATUS_HOLD_MS);
  releaseHeldStatus(statusElement);
  refreshComposerCostStatus();
  speakToScreenReader(t('dialog.pricesMoved'));
  setTimeout(() => { if (!composerPricesMovedNotice.has(statusElement) || (composerPricesMovedNotice.get(statusElement) ?? 0) <= Date.now()) refreshComposerCostStatus(); }, STATUS_HOLD_MS + 50);
}

function refreshComposerCostStatus() {
  if (privateComposerCostStatus) {
    const privatePlan = privateComposerSendPlan(messageInput?.value ?? '', privateImageAttachments, currentPrivateSenderOptions(), {
    });
    const limitMessage = privateComposerPartLimitMessage(privatePlan.length);
    const blockReason = privateSendBlockReason(activeThread(), { includeVaultShortfall: false });
    const status = blockReason
      ? { text: blockReason, state: 'short', action: activationComposerAction(blockReason) }
      : limitMessage
      ? { text: limitMessage, state: 'short' }
      : isPublicGroupThread(activeThread())
      ? publicGroupComposerCostLine(messageInput?.value ?? '')
      : isRealSavedThread(activeThread())
      ? selfNotesComposerCostLine()
      : composerCostPrecondition(Math.max(1, privatePlan.length), { ignoreTonRpcLimit: true })
        ?? privateComposerFinalCostLine(activeThread(), privatePlan);
    if (!statusHeld(privateComposerCostStatus, activeThreadId)) paintComposerCostLine(privateComposerCostStatus, status);
  }
  refreshPrivateSendButtonState();
  if (publicComposerCostStatus) {
    const publicPlan = publicComposerSendPlan(publicMessageInput?.value ?? '', publicImageAttachments);
    const publicLimitMessage = publicComposerPartLimitMessage(publicPlan.length);
    const status = publicLimitMessage
      ? { text: publicLimitMessage, state: 'short' }
      : plathoWallet && !hasActivePlathoAccount() && pendingServiceWorkerAppShellReload !== true
      ? { text: publicComposerBlockReason(), state: 'short', action: accountActivationInFlight() ? null : activationComposerAction(publicComposerBlockReason()) }
      : composerCostPrecondition(Math.max(1, publicPlan.length)) ?? publicComposerFinalCostLine(publicPlan);
    if (!statusHeld(publicComposerCostStatus, publicComposerHoldScope())) paintComposerCostLine(publicComposerCostStatus, status);
  }
  refreshPublicSendButtonState();
}

function normalizePublicCommentsDefault(value) {
  const text = String(value ?? 'disabled').toLowerCase();
  return ['enabled', 'disabled'].includes(text) ? text : 'disabled';
}

function readPublicCommentsDefault() {
  try {
    return normalizePublicCommentsDefault(localStorageOrNull()?.getItem(PUBLIC_COMMENTS_DEFAULT_STORAGE_KEY));
  } catch {
    return 'disabled';
  }
}

function writePublicCommentsDefault(value) {
  const normalized = normalizePublicCommentsDefault(value);
  try {
    localStorageOrNull()?.setItem(PUBLIC_COMMENTS_DEFAULT_STORAGE_KEY, normalized);
  } catch {
  }
  return normalized;
}

function publicCommentsDefaultLabel(value = readPublicCommentsDefault()) {
  return normalizePublicCommentsDefault(value) === 'disabled' ? t('public.commentsClosedStatus') : t('public.commentsAllowedStatus');
}

