function serializeComposerEditor(el, keepTrailingBr = false) {
  if (!el) return '';
  const serChildren = (node, delim) => {
    let out = '';
    let seg = '';
    const flush = () => { if (seg !== '') { out += delim + seg + delim; seg = ''; } };
    for (const child of node.childNodes) {
      if (child.nodeType === 3) {
        seg += child.nodeValue;
      } else if (child.nodeType === 1) {
        const tag = child.tagName;
        const cls = child.classList;
        if (tag === 'BR') {
          if (!keepTrailingBr && node === el && !child.nextSibling) { }
          else { flush(); out += '\n'; }
        } else if (child.dataset && child.dataset.marker) {
          flush(); out += child.dataset.marker;
        } else if (cls.contains('fmt-bold')) {
          seg += serChildren(child, '**');
        } else if (cls.contains('fmt-italic')) {
          seg += serChildren(child, '*');
        } else if (cls.contains('fmt-heading')) {
          flush();
          if (out && !out.endsWith('\n')) out += '\n';
          const level = Math.min(Math.max(Number(child.dataset?.level) || 1, 1), 3);
          out += `${'#'.repeat(level)} ${serChildren(child, '')}`;
        } else if (cls.contains('fmt-code')) {
          seg += serChildren(child, '`');
        } else if (tag === 'DIV' || tag === 'P') {
          flush();
          if (out && !out.endsWith('\n')) out += '\n';
          out += serChildren(child, '');
        } else {
          seg += serChildren(child, '');
        }
      }
    }
    flush();
    return out;
  };
  return serChildren(el, '');
}

const EDITOR_INLINE_RE = /\*\*\*([^*\n]+)\*\*\*|\*\*([^*\n]+)\*\*|\*([^*\n]+)\*|`([^`\n]+)`|(\[(?:image|img)\s+\d+\]|\[file\s+\d+\]|\[post\])(?!\()|\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)/g;

function composerChipLabelForMarker(marker) {
  const m = String(marker);
  if (/^\[(?:image|img)\s+\d+\]$/i.test(m)) return t('composer.image');
  if (/^\[file\s+\d+\]$/i.test(m)) return t('composer.file');
  if (/^\[post\]$/i.test(m)) return t('public.sharedPost');
  return m;
}

function composerBlockContextForEditor(el) {
  if (el === publicMessageInput) {
    return { kind: 'public', images: publicImageAttachments, files: publicFileAttachments, share: publicShareDraft };
  }
  return { kind: 'private', images: privateImageAttachments, files: privateFileAttachments, share: privateShareDraft };
}

function composerBlockInner(marker, ctx) {
  let m;
  if ((m = marker.match(/^\[(?:image|img)\s+(\d+)\]$/i))) {
    const att = ctx.images?.[Number(m[1]) - 1];
    if (!att?.bytes?.length) return null;
    const img = document.createElement('img');
    img.className = 'composer-block-image';
    img.src = bytesToImageDataUrl(att.bytes, 'image/webp');
    img.alt = String(att.name ?? '');
    img.draggable = false;
    return img;
  }
  if ((m = marker.match(/^\[file\s+(\d+)\]$/i))) {
    const att = ctx.files?.[Number(m[1]) - 1];
    if (!att) return null;
    const chip = document.createElement('span');
    chip.className = 'composer-block-file';
    const icon = document.createElement('span'); icon.className = 'icon icon-download';
    const name = document.createElement('span'); name.className = 'message-file-name'; name.textContent = String(att.name ?? t('chat.fileFallbackName'));
    const size = document.createElement('span'); size.className = 'message-file-size'; size.textContent = imageByteCountLabel(att.bytes?.length ?? 0);
    chip.append(icon, name, size);
    return chip;
  }
  if (/^\[post\]$/i.test(marker)) {
    if (!ctx.share?.entryId) return null;
    return buildSharedPostEmbed(ctx.share);
  }
  return null;
}

function buildComposerBlock(marker, el) {
  const block = document.createElement('div');
  block.className = 'composer-block';
  block.contentEditable = 'false';
  block.dataset.marker = String(marker);
  const inner = el ? composerBlockInner(String(marker), composerBlockContextForEditor(el)) : null;
  if (inner) {
    block.append(inner);
  } else {
    block.classList.add('composer-block-pill');
    block.textContent = composerChipLabelForMarker(marker);
  }
  return block;
}

function buildComposerLinkBlock(markup, label) {
  const block = document.createElement('span');
  block.className = 'composer-block composer-block-link';
  block.contentEditable = 'false';
  block.dataset.marker = String(markup);
  block.textContent = String(label || markup);
  return block;
}

function composerEditorLinkClick(el, event) {
  if (!el || el.disabled) return;
  const chip = event.target?.closest?.('.composer-block-link');
  if (!chip || !el.contains(chip)) return;
  event.preventDefault();
  openLinkComposerDialog(el, chip);
}

function composerEditorCopySelection(el, event, isCut) {
  if (!el || !event.clipboardData) return;
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  const wrapper = document.createElement('div');
  wrapper.appendChild(range.cloneContents());
  const fillerBr = el.lastChild && el.lastChild.nodeName === 'BR' && !el.lastChild.nextSibling ? el.lastChild : null;
  const keepTrailingBr = !(fillerBr && range.intersectsNode(fillerBr));
  event.clipboardData.setData('text/plain', serializeComposerEditor(wrapper, keepTrailingBr));
  event.preventDefault();
  if (isCut && !el.disabled) {
    const hasAttachmentAtom = [...wrapper.querySelectorAll('[data-marker]')].some((a) => !/\]\(/.test(a.dataset.marker || ''));
    if (!hasAttachmentAtom) {
      range.deleteContents();
      composerEditorPruneEmptyFmt(el);
      composerEditorAfterEdit(el);
    }
  }
}

function appendEditorInline(target, text, context = target, renderAttachmentMarkers = true) {
  const str = String(text ?? '');
  if (!str) return;
  EDITOR_INLINE_RE.lastIndex = 0;
  let last = 0;
  let match;
  while ((match = EDITOR_INLINE_RE.exec(str)) !== null) {
    if (match.index > last) target.append(document.createTextNode(str.slice(last, match.index)));
    if (match[1] !== undefined) {
      const b = document.createElement('span'); b.className = 'fmt-bold';
      const i = document.createElement('span'); i.className = 'fmt-italic'; i.textContent = match[1];
      b.append(i); target.append(b);
    }
    else if (match[2] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-bold'; s.textContent = match[2]; target.append(s); }
    else if (match[3] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-italic'; s.textContent = match[3]; target.append(s); }
    else if (match[4] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-code'; s.textContent = match[4]; target.append(s); }
    else if (match[5] !== undefined) { target.append(renderAttachmentMarkers ? buildComposerBlock(match[5], context) : document.createTextNode(match[5])); }
    else { target.append(buildComposerLinkBlock(`[${match[6]}](${match[7]})`, match[6])); }
    last = match.index + match[0].length;
  }
  if (last < str.length) target.append(document.createTextNode(str.slice(last)));
}

function buildComposerEditorDom(el, text) {
  el.replaceChildren();
  const lines = String(text ?? '').split('\n');
  lines.forEach((line, index) => {
    if (index > 0) el.append(document.createElement('br'));
    const heading = MSG_HEADING_RE.exec(line);
    if (heading) {
      const span = document.createElement('span');
      span.className = 'fmt-heading';
      span.dataset.level = String(heading[1].length);
      appendEditorInline(span, heading[2], el);
      el.append(span);
      return;
    }
    appendEditorInline(el, line);
  });
}



function composerEditorRange(el) {
  const sel = window.getSelection();
  if (sel && sel.rangeCount) {
    const range = sel.getRangeAt(0);
    if (el.contains(range.commonAncestorContainer)) return range;
  }
  const range = document.createRange();
  range.selectNodeContents(el);
  range.collapse(false);
  return range;
}

function composerEditorPlaceCaretAfter(node) {
  const sel = window.getSelection();
  if (!sel) return;
  const range = document.createRange();
  range.setStartAfter(node);
  range.collapse(true);
  sel.removeAllRanges();
  sel.addRange(range);
}

function composerEditorAfterEdit(el) {
  el.classList.toggle('is-empty', serializeComposerEditor(el).trim() === '');
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function composerEditorInsertText(el, text) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const range = composerEditorRange(el);
  range.deleteContents();
  const node = document.createTextNode(String(text ?? ''));
  range.insertNode(node);
  composerEditorPlaceCaretAfter(node);
  composerEditorAfterEdit(el);
}

function composerEditorEscapeTrailingFmt(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!range.collapsed) return;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = range.startContainer;
  let span = null;
  while (n && n !== el) {
    if (isFmt(n)) span = n;
    n = n.parentNode;
  }
  if (!span) return;
  const lead = document.createRange();
  lead.setStart(span, 0);
  lead.setEnd(range.startContainer, range.startOffset);
  const before = lead.cloneContents();
  const atLeadingEdge = before.textContent === '' && !before.querySelector('br, [data-marker]');
  const r = document.createRange();
  if (atLeadingEdge) r.setStartBefore(span); else r.setStartAfter(span);
  r.collapse(true);
  sel.removeAllRanges();
  sel.addRange(r);
}

function composerEditorPruneEmptyFmt(el) {
  for (const span of [...el.querySelectorAll('[class*="fmt-"]')]) {
    if (!span.isConnected) continue;
    if (/\bfmt-/.test(span.className || '') && span.textContent === '' && !span.querySelector('br, [data-marker]')) span.remove();
  }
}

function composerEditorStripNativeFormatting(el) {
  if (!el) return;
  const natives = el.querySelectorAll('b, strong, i, em, u, s, font, [style*="font-weight"], [style*="font-style"], [style*="text-decoration"]');
  for (const node of natives) {
    if (!node.isConnected || node.nodeType !== 1) continue;
    if (/\bfmt-/.test(node.className || '')) continue;
    if (node.closest && node.closest('[data-marker]')) continue;
    while (node.firstChild) node.parentNode.insertBefore(node.firstChild, node);
    node.remove();
  }
}

function composerEditorNormalizeEmptyFmt(el) {
  if (!el) return;
  if ((el.textContent || '').trim() === '') {
    let strippedFmt = false;
    el.querySelectorAll('[class*="fmt-"]').forEach((span) => {
      if (!span.isConnected || !/\bfmt-/.test(span.className || '')) return;
      while (span.firstChild) span.parentNode.insertBefore(span.firstChild, span);
      span.remove();
      strippedFmt = true;
    });
    if (strippedFmt) {
      const sel = window.getSelection();
      if (sel) { const r = document.createRange(); r.setStart(el, 0); r.collapse(true); sel.removeAllRanges(); sel.addRange(r); }
    }
    return;
  }
  const empties = [...el.querySelectorAll('[class*="fmt-"]')].filter((s) =>
    s.isConnected && /\bfmt-/.test(s.className || '') && s.textContent === '' && !s.querySelector('br, [data-marker]'));
  if (!empties.length) return;
  const sel = window.getSelection();
  let caretSpan = null;
  if (sel && sel.rangeCount) {
    let n = sel.getRangeAt(0).startContainer;
    while (n && n !== el) { if (empties.includes(n)) { caretSpan = n; break; } n = n.parentNode; }
  }
  let anchorParent = null, anchorNext = null;
  if (caretSpan) {
    anchorParent = caretSpan.parentNode;
    anchorNext = caretSpan.nextSibling;
    while (anchorNext && empties.includes(anchorNext)) anchorNext = anchorNext.nextSibling;
  }
  empties.forEach((s) => s.remove());
  if (caretSpan && anchorParent && anchorParent.isConnected && sel) {
    const r = document.createRange();
    if (anchorNext && anchorNext.parentNode === anchorParent) r.setStartBefore(anchorNext);
    else r.setStart(anchorParent, anchorParent.childNodes.length);
    r.collapse(true);
    sel.removeAllRanges(); sel.addRange(r);
  }
}

function composerEditorSplitFmtAtCaret(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const caret = sel.getRangeAt(0);
  if (!caret.collapsed) return;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = caret.startContainer, span = null;
  while (n && n !== el) { if (isFmt(n)) span = n; n = n.parentNode; }
  if (!span) return;
  const tail = document.createRange();
  tail.setStart(caret.startContainer, caret.startOffset);
  tail.setEnd(span, span.childNodes.length);
  const afterFrag = tail.extractContents();
  if (afterFrag && afterFrag.textContent !== '') {
    const afterSpan = span.cloneNode(false);
    afterSpan.appendChild(afterFrag);
    span.after(afterSpan);
  }
  const r = document.createRange();
  r.setStartAfter(span);
  r.collapse(true);
  sel.removeAllRanges();
  sel.addRange(r);
}

function composerEditorSplitFmtForNewlineIfMidWord(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return false;
  const range = sel.getRangeAt(0);
  if (!range.collapsed) return false;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = range.startContainer, span = null;
  while (n && n !== el) { if (isFmt(n)) span = n; n = n.parentNode; }
  if (!span) return false;
  const emptyRun = (from, fromOff, to, toOff) => {
    const r = document.createRange(); r.setStart(from, fromOff); r.setEnd(to, toOff);
    const frag = r.cloneContents();
    return frag.textContent === '' && !frag.querySelector('br, [data-marker]');
  };
  const nothingBefore = emptyRun(span, 0, range.startContainer, range.startOffset);
  const nothingAfter = emptyRun(range.startContainer, range.startOffset, span, span.childNodes.length);
  if (nothingBefore || nothingAfter) return false;
  composerEditorSplitFmtAtCaret(el);
  return true;
}

function composerEditorInsertLineBreak(el) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const sel = window.getSelection();
  if (sel && sel.rangeCount && !sel.isCollapsed && el.contains(sel.getRangeAt(0).commonAncestorContainer)) {
    const r = sel.getRangeAt(0); r.collapse(false); sel.removeAllRanges(); sel.addRange(r);
  }
  if (!composerEditorSplitFmtForNewlineIfMidWord(el)) composerEditorEscapeTrailingFmt(el);
  composerEditorPruneEmptyFmt(el);
  const range = composerEditorRange(el);
  range.deleteContents();
  const br = document.createElement('br');
  range.insertNode(br);
  while (br.nextSibling && br.nextSibling.nodeType === 3 && br.nextSibling.nodeValue === '') br.nextSibling.remove();
  if (!br.nextSibling) br.after(document.createElement('br'));
  composerEditorPlaceCaretAfter(br);
  composerEditorAfterEdit(el);
}

function composerEditorInsertChip(el, marker) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const sel = window.getSelection();
  if (sel && sel.rangeCount && !sel.isCollapsed) { const r = sel.getRangeAt(0); r.collapse(false); sel.removeAllRanges(); sel.addRange(r); }
  composerEditorEscapeTrailingFmt(el);
  const range = composerEditorRange(el);
  range.deleteContents();
  const block = buildComposerBlock(marker, el);
  range.insertNode(block);
  composerEditorPlaceCaretAfter(block);
  composerEditorAfterEdit(el);
}

function composerEditorInsertLinkBlock(el, markup, label, savedRange) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  if (savedRange) { const s = window.getSelection(); s.removeAllRanges(); s.addRange(savedRange); }
  const sel = window.getSelection();
  const hadSelection = sel && sel.rangeCount && !sel.isCollapsed;
  if (hadSelection) {
    sel.getRangeAt(0).deleteContents();
    composerEditorSplitFmtAtCaret(el);
  } else {
    composerEditorEscapeTrailingFmt(el);
  }
  const range = composerEditorRange(el);
  range.deleteContents();
  const block = buildComposerLinkBlock(markup, label);
  range.insertNode(block);
  composerEditorPruneEmptyFmt(el);
  composerEditorPlaceCaretAfter(block);
  composerEditorAfterEdit(el);
}

function refreshComposerEditorBlocks(el) {
  if (!el || el.dataset?.editorReady !== '1') return;
  el.value = serializeComposerEditor(el);
}

function composerEditorIsAtom(node) {
  return Boolean(node && node.nodeType === 1 && node.dataset && node.dataset.marker);
}

function composerEditorAdjacentAtom(range, el, dir) {
  const c = range.startContainer;
  const off = range.startOffset;
  if (c === el) {
    const node = dir < 0 ? el.childNodes[off - 1] : el.childNodes[off];
    return composerEditorIsAtom(node) ? node : null;
  }
  if (c.nodeType === 3) {
    if (dir < 0 && off === 0) return composerEditorIsAtom(c.previousSibling) ? c.previousSibling : null;
    if (dir > 0 && off === (c.nodeValue || '').length) return composerEditorIsAtom(c.nextSibling) ? c.nextSibling : null;
  }
  return null;
}

function removeComposerAtom(el, atom) {
  const marker = atom?.dataset?.marker || '';
  const kind = el === publicMessageInput ? 'public' : 'private';
  let m;
  if ((m = marker.match(/^\[(?:image|img)\s+(\d+)\]$/i))) { removeComposerImageAt(kind, Number(m[1]) - 1); return; }
  if ((m = marker.match(/^\[file\s+(\d+)\]$/i))) { removeComposerFileAt(kind, Number(m[1]) - 1); return; }
  if (/^\[post\]$/i.test(marker)) { removeComposerShareAtom(kind); return; }
  atom.remove();
  composerEditorAfterEdit(el);
}

function removeComposerImageAt(kind, index) {
  if (kind === 'public') publicImageAttachments = publicImageAttachments.filter((_, i) => i !== index);
  else privateImageAttachments = privateImageAttachments.filter((_, i) => i !== index);
  removeImageMarkerForComposer(kind, index);
  updateImageAttachmentUi(kind);
  refreshComposerCostStatus();
}

function removeFileMarkerForComposer(kind, removedIndex) {
  const editor = kind === 'public' ? publicMessageInput : messageInput;
  if (!editor) return;
  const removedNum = Number(removedIndex) + 1;
  let dropped = false;
  const next = String(editor.value ?? '').replace(/\[file\s+(\d+)\](?!\()/ig, (match, numStr) => {
    const n = Number(numStr);
    if (!dropped && n === removedNum) { dropped = true; return ''; }
    if (n > removedNum) return `[file ${n - 1}]`;
    return match;
  });
  let value = next.replace(/\n{3,}/g, '\n\n');
  if (!value.trim()) value = '';
  editor.value = value;
}

function removeComposerFileAt(kind, index) {
  if (kind === 'public') publicFileAttachments = publicFileAttachments.filter((_, i) => i !== index);
  else privateFileAttachments = privateFileAttachments.filter((_, i) => i !== index);
  removeFileMarkerForComposer(kind, index);
  if (kind === 'public') updatePublicFileAttachmentUi(); else updatePrivateFileAttachmentUi();
  refreshComposerCostStatus();
}


function removeComposerShareAtom(kind) {
  const editor = kind === 'public' ? publicMessageInput : messageInput;
  if (kind === 'public') setPublicShareDraft(null); else setPrivateShareDraft(null);
  removeShareMarkerForComposer(editor);
  refreshComposerCostStatus();
}

function reconcileMarkerArray(value, arr, re, fmt) {
  const present = [];
  re.lastIndex = 0;
  let m;
  while ((m = re.exec(value)) !== null) present.push(Number(m[1]));
  const keptIdx = [];
  const seen = new Set();
  for (const n of present) { if (n >= 1 && n <= arr.length && !seen.has(n)) { seen.add(n); keptIdx.push(n - 1); } }
  if (keptIdx.length === arr.length) return { changed: false, value, arr };
  const newArr = keptIdx.map((i) => arr[i]);
  const remap = new Map();
  keptIdx.forEach((oldI, newPos) => remap.set(oldI + 1, newPos + 1));
  const newValue = value.replace(re, (full, numStr) => {
    const n = Number(numStr);
    return remap.has(n) ? fmt(remap.get(n)) : full;
  });
  return { changed: true, value: newValue, arr: newArr };
}

function reconcileComposerAttachments(el) {
  const kind = el === publicMessageInput ? 'public' : 'private';
  let value = serializeComposerEditor(el);
  let changed = false;
  const imgArr = kind === 'public' ? publicImageAttachments : privateImageAttachments;
  const ri = reconcileMarkerArray(value, imgArr, /\[(?:image|img)\s+(\d+)\]/ig, (n) => `[image ${n}]`);
  if (ri.changed) { changed = true; value = ri.value; if (kind === 'public') publicImageAttachments = ri.arr; else privateImageAttachments = ri.arr; }
  const fileArr = kind === 'public' ? publicFileAttachments : privateFileAttachments;
  const rf = reconcileMarkerArray(value, fileArr, /\[file\s+(\d+)\]/ig, (n) => `[file ${n}]`);
  if (rf.changed) { changed = true; value = rf.value; if (kind === 'public') publicFileAttachments = rf.arr; else privateFileAttachments = rf.arr; }
  if (!changed) return false;
  el.value = value;
  if (kind === 'private') { updatePrivateAttachmentUi(); updatePrivateFileAttachmentUi(); }
  else { updateImageAttachmentUi('public'); updatePublicFileAttachmentUi(); }
  refreshComposerPublishPolicy();
  refreshComposerCostStatus();
  return true;
}

function composerEditorWordRangeAtCaret(range, el) {
  const caretNode = range.startContainer;
  if (caretNode.nodeType !== 3) return null;
  const root = el || caretNode.parentNode;
  if (!root || !root.contains(caretNode)) return null;
  const isWord = (ch) => ch !== undefined && /[\p{L}\p{N}_]/u.test(ch);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode(n) {
      if (n.nodeType === 3) {
        return (n.parentElement && n.parentElement.closest('[data-marker]')) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      }
      if (n.nodeName === 'BR' || n.nodeName === 'DIV' || n.nodeName === 'P' || (n.dataset && n.dataset.marker)) return NodeFilter.FILTER_ACCEPT;
      return NodeFilter.FILTER_SKIP;
    },
  });
  const seq = [];
  let n;
  while ((n = walker.nextNode())) seq.push(n);
  const caretIdx = seq.indexOf(caretNode);
  if (caretIdx === -1) return null;
  let a = caretIdx;
  let b = caretIdx;
  while (a > 0 && seq[a - 1].nodeType === 3) a--;
  while (b < seq.length - 1 && seq[b + 1].nodeType === 3) b++;
  const textNodes = seq.slice(a, b + 1);
  let concat = '';
  const map = [];
  let caretGlobal = 0;
  for (const tn of textNodes) {
    if (tn === caretNode) caretGlobal = concat.length + range.startOffset;
    const v = tn.nodeValue || '';
    for (let i = 0; i < v.length; i++) map.push({ node: tn, local: i });
    concat += v;
  }
  let s = caretGlobal;
  let e = caretGlobal;
  while (s > 0 && isWord(concat[s - 1])) s--;
  while (e < concat.length && isWord(concat[e])) e++;
  if (s === e) return null;
  const startPos = map[s];
  const lastPos = map[e - 1];
  return {
    startNode: startPos.node, startOffset: startPos.local,
    endNode: lastPos.node, endOffset: lastPos.local + 1,
    caretInWord: caretGlobal - s,
  };
}

function composerEditorEnclosingFormat(range, className, el) {
  let node = range.commonAncestorContainer;
  while (node && node !== el) {
    if (node.nodeType === 1 && node.classList && node.classList.contains(className)) return node;
    node = node.parentNode;
  }
  return null;
}

function composerEditorSelectionFullyFormatted(range, className, el) {
  const overlaps = (n) => {
    const nr = document.createRange();
    nr.selectNodeContents(n);
    return range.compareBoundaryPoints(Range.END_TO_START, nr) < 0
      && range.compareBoundaryPoints(Range.START_TO_END, nr) > 0;
  };
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => ((n.nodeValue || '') !== '' && !(n.parentElement && n.parentElement.closest('[data-marker]')) && overlaps(n))
      ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP,
  });
  let n;
  let any = false;
  while ((n = walker.nextNode())) {
    any = true;
    if (!(n.parentElement && n.parentElement.closest('.' + className))) return false;
  }
  return any;
}

function composerEditorUnformatRange(range, className, el) {
  const frag = range.extractContents();
  frag.querySelectorAll('.' + className).forEach((span) => {
    if (!/\bfmt-/.test(span.className || '')) return;
    while (span.firstChild) span.parentNode.insertBefore(span.firstChild, span);
    span.remove();
  });
  let node = range.startContainer;
  let encl = null;
  while (node && node !== el) {
    if (node.nodeType === 1 && /\bfmt-/.test(node.className || '') && node.classList.contains(className)) encl = node;
    node = node.parentNode;
  }
  if (encl) { range.setStartAfter(encl); range.collapse(true); }
  const first = frag.firstChild;
  const last = frag.lastChild;
  range.insertNode(frag);
  const sel = window.getSelection();
  if (sel && first && last && first.isConnected && last.isConnected) {
    const r = document.createRange();
    r.setStartBefore(first);
    r.setEndAfter(last);
    sel.removeAllRanges();
    sel.addRange(r);
  }
}

function composerEditorLineNodes(el, range) {
  let node = range.startContainer;
  if (node === el) node = el.childNodes[Math.min(range.startOffset, Math.max(0, el.childNodes.length - 1))] ?? null;
  else { while (node && node.parentNode !== el) node = node.parentNode; }
  if (!node) return null;
  if (node.tagName === 'BR') node = node.previousSibling;
  if (!node) return null;
  let first = node;
  while (first.previousSibling && first.previousSibling.tagName !== 'BR') first = first.previousSibling;
  let last = node;
  while (last.nextSibling && last.nextSibling.tagName !== 'BR') last = last.nextSibling;
  const nodes = [];
  for (let n = first; n; n = n.nextSibling) { nodes.push(n); if (n === last) break; }
  return nodes.length ? nodes : null;
}

function composerEditorToggleHeading(el) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  const nodes = composerEditorLineNodes(el, range);
  if (!nodes) return;

  const caretNode = range.startContainer;
  const caretOffset = range.startOffset;
  const restoreCaret = () => {
    if (!caretNode?.isConnected) return;
    const r = document.createRange();
    try { r.setStart(caretNode, Math.min(caretOffset, caretNode.nodeType === 3 ? caretNode.nodeValue.length : caretNode.childNodes.length)); }
    catch { return; }
    r.collapse(true);
    sel.removeAllRanges();
    sel.addRange(r);
  };

  const existing = nodes.length === 1 && nodes[0].nodeType === 1 && nodes[0].classList?.contains('fmt-heading') ? nodes[0] : null;
  if (existing) {
    const parent = existing.parentNode;
    while (existing.firstChild) parent.insertBefore(existing.firstChild, existing);
    existing.remove();
  } else {
    if (nodes.some((n) => n.nodeType === 1 && (n.dataset?.marker || n.querySelector?.('[data-marker]')))) return;
    if (nodes.every((n) => (n.textContent ?? '') === '')) return;
    const span = document.createElement('span');
    span.className = 'fmt-heading';
    span.dataset.level = '1';
    nodes[0].parentNode.insertBefore(span, nodes[0]);
    for (const n of nodes) span.append(n);
    span.querySelectorAll('.fmt-heading').forEach((n) => { while (n.firstChild) n.parentNode.insertBefore(n.firstChild, n); n.remove(); });
  }
  restoreCaret();
  composerEditorAfterEdit(el);
}

function composerEditorToggleFormat(el, className) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  const startedCollapsed = range.collapsed;
  let caretInWord = -1;
  if (range.collapsed) {
    const word = composerEditorWordRangeAtCaret(range, el);
    if (!word) return;
    caretInWord = word.caretInWord;
    range.setStart(word.startNode, word.startOffset);
    range.setEnd(word.endNode, word.endOffset);
    sel.removeAllRanges();
    sel.addRange(range);
  }
  for (const block of el.querySelectorAll('[data-marker]')) {
    if (range.intersectsNode(block)) return;
  }
  const enclosing = composerEditorEnclosingFormat(range, className, el);
  if (enclosing) {
    const hasElementChild = Array.from(enclosing.childNodes).some((n) => n.nodeType === 1);
    if (!hasElementChild) {
      const spanText = enclosing.textContent;
      const pre = document.createRange();
      pre.selectNodeContents(enclosing);
      pre.setEnd(range.startContainer, range.startOffset);
      const startOff = pre.toString().length;
      const endOff = startOff + range.toString().length;
      const head = spanText.slice(0, startOff);
      const mid = spanText.slice(startOff, endOff);
      const tail = spanText.slice(endOff);
      const frag = document.createDocumentFragment();
      if (head) { const s = document.createElement('span'); s.className = className; s.textContent = head; frag.append(s); }
      const midNode = document.createTextNode(mid);
      frag.append(midNode);
      if (tail) { const s = document.createElement('span'); s.className = className; s.textContent = tail; frag.append(s); }
      enclosing.replaceWith(frag);
      const r = document.createRange();
      r.selectNode(midNode);
      sel.removeAllRanges(); sel.addRange(r);
    } else {
      const parent = enclosing.parentNode;
      const kids = [];
      while (enclosing.firstChild) { kids.push(enclosing.firstChild); parent.insertBefore(enclosing.firstChild, enclosing); }
      parent.removeChild(enclosing);
      if (kids.length) {
        const r = document.createRange();
        r.setStartBefore(kids[0]);
        r.setEndAfter(kids[kids.length - 1]);
        sel.removeAllRanges(); sel.addRange(r);
      }
    }
  } else if (composerEditorSelectionFullyFormatted(range, className, el)) {
    composerEditorUnformatRange(range, className, el);
  } else {
    const span = document.createElement('span');
    span.className = className;
    span.appendChild(range.extractContents());
    range.insertNode(span);
    span.querySelectorAll('.' + className).forEach((n) => { while (n.firstChild) n.parentNode.insertBefore(n.firstChild, n); n.remove(); });
    span.normalize();
    const r = document.createRange();
    r.selectNodeContents(span);
    sel.removeAllRanges(); sel.addRange(r);
  }
  if (startedCollapsed && sel.rangeCount) {
    const r = sel.getRangeAt(0);
    const wordTexts = [];
    const rootEl = r.commonAncestorContainer.nodeType === 1 ? r.commonAncestorContainer : r.commonAncestorContainer.parentNode;
    if (rootEl) {
      const tw = document.createTreeWalker(rootEl, NodeFilter.SHOW_TEXT, { acceptNode: (tn) => r.intersectsNode(tn) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP });
      let tn; while ((tn = tw.nextNode())) wordTexts.push(tn);
    }
    let node = r.startContainer, off = r.startOffset;
    if (wordTexts.length) {
      const want = caretInWord >= 0 ? caretInWord : Infinity;
      let acc = 0, placed = false;
      for (const tn of wordTexts) {
        const from = tn === r.startContainer ? r.startOffset : 0;
        const to = tn === r.endContainer ? r.endOffset : tn.nodeValue.length;
        const len = to - from;
        if (acc + len >= want) { node = tn; off = from + (want - acc); placed = true; break; }
        acc += len;
      }
      if (!placed) { const last = wordTexts[wordTexts.length - 1]; node = last; off = last === r.endContainer ? r.endOffset : last.nodeValue.length; }
    } else if (node.nodeType === 1) {
      let c = node.childNodes[off] || node.firstChild;
      while (c && c.nodeType === 1) c = c.firstChild;
      if (c && c.nodeType === 3) { node = c; off = caretInWord >= 0 ? Math.min(caretInWord, c.nodeValue.length) : c.nodeValue.length; }
    }
    const r2 = document.createRange();
    r2.setStart(node, off);
    r2.collapse(true);
    sel.removeAllRanges();
    sel.addRange(r2);
  }
  composerEditorPruneEmptyFmt(el);
  composerEditorAfterEdit(el);
}

function composerEditorTrailingFmtSpan(range, el) {
  const node = range.startContainer;
  if (node.nodeType !== 3 || range.startOffset !== node.nodeValue.length) return null;
  let span = node.parentNode;
  if (!(span && span !== el && span.nodeType === 1 && /\bfmt-/.test(span.className || '') && node === span.lastChild)) return null;
  while (span.parentNode && span.parentNode !== el && span.parentNode.nodeType === 1
    && /\bfmt-/.test(span.parentNode.className || '') && span === span.parentNode.lastChild) {
    span = span.parentNode;
  }
  return span;
}

function composerEditorEscapeFmtForComposition(el) {
  if (!el || el.disabled) return;
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
  const span = composerEditorTrailingFmtSpan(sel.getRangeAt(0), el);
  if (!span) return;
  const r = document.createRange();
  r.setStartAfter(span);
  r.collapse(true);
  sel.removeAllRanges(); sel.addRange(r);
}

function composerEditorBeforeInput(el, event) {
  if (event.isComposing) return;
  if (event.inputType === 'insertParagraph' || event.inputType === 'insertLineBreak') {
    event.preventDefault();
    composerEditorInsertLineBreak(el);
    return;
  }
  if (event.inputType === 'deleteContentBackward' || event.inputType === 'deleteContentForward') {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
    const atom = composerEditorAdjacentAtom(sel.getRangeAt(0), el, event.inputType === 'deleteContentBackward' ? -1 : 1);
    if (atom) { event.preventDefault(); removeComposerAtom(el, atom); }
    return;
  }
  if ((event.inputType === 'insertText' || event.inputType === 'insertReplacementText'
    || event.inputType === 'insertFromComposition' || event.inputType === 'insertFromAutofill')
    && typeof event.data === 'string') {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
    const span = composerEditorTrailingFmtSpan(sel.getRangeAt(0), el);
    if (!span) return;
    event.preventDefault();
    const textNode = document.createTextNode(event.data);
    span.after(textNode);
    const r = document.createRange();
    r.setStart(textNode, textNode.length);
    r.collapse(true);
    sel.removeAllRanges(); sel.addRange(r);
    composerEditorAfterEdit(el);
  }
}

function composerEditorInsertPlainMultiline(el, text) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  let raw = String(text ?? '').replace(/\r\n?/g, '\n');
  raw = raw.replace(/\[((?:image|img)\s+\d+|file\s+\d+|post)\](?!\()/gi, '[\u200b$1]');
  composerEditorRange(el).deleteContents();
  const hasLink = /\[[^\]\n]{1,200}\]\([^\s()]{1,2000}\)/.test(raw);
  if (hasLink) composerEditorEscapeTrailingFmt(el);
  const range = composerEditorRange(el);
  const frag = document.createDocumentFragment();
  const lines = raw.split('\n');
  lines.forEach((line, index) => {
    if (index > 0) frag.append(document.createElement('br'));
    appendEditorInline(frag, line, el, false);
  });
  const last = frag.lastChild;
  range.insertNode(frag);
  if (last) composerEditorPlaceCaretAfter(last);
  composerEditorAfterEdit(el);
}

function initComposerEditor(el) {
  if (!el || el.dataset.editorReady === '1') return;
  el.dataset.editorReady = '1';
  el.contentEditable = 'true';
  el.setAttribute('role', 'textbox');
  el.setAttribute('aria-multiline', 'true');
  el.classList.add('composer-input');
  el.classList.toggle('is-empty', serializeComposerEditor(el).trim() === '');
  let disabledFlag = false;
  Object.defineProperty(el, 'value', {
    configurable: true,
    get() { return serializeComposerEditor(this); },
    set(v) { buildComposerEditorDom(this, String(v ?? '')); this.classList.toggle('is-empty', String(v ?? '').trim() === ''); },
  });
  Object.defineProperty(el, 'disabled', {
    configurable: true,
    get() { return disabledFlag; },
    set(v) {
      disabledFlag = Boolean(v);
      this.contentEditable = disabledFlag ? 'false' : 'true';
      this.classList.toggle('is-disabled', disabledFlag);
      if (disabledFlag) this.setAttribute('aria-disabled', 'true'); else this.removeAttribute('aria-disabled');
    },
  });
  Object.defineProperty(el, 'placeholder', {
    configurable: true,
    get() { return this.getAttribute('placeholder') ?? ''; },
    set(v) { this.setAttribute('placeholder', String(v ?? '')); },
  });
}

function privateAttachmentLabelForImage(attachment) {
  return attachment
    ? t('composer.imageAttachmentLabel', { name: attachment.name, kib: Math.ceil(attachment.bytes.length / 1024), mode: attachment.mode.label.toLowerCase() })
    : t('composer.image');
}

function createImageModeSelect(attachment, onChange) {
  const select = document.createElement('select');
  select.setAttribute('aria-label', t('composer.imageCompressionAria'));
  for (const mode of Object.values(IMAGE_COMPRESSION_MODES)) {
    const option = document.createElement('option');
    option.value = mode.id;
    option.textContent = t('composer.imageModeOption', { mode: mode.label, kib: Math.round(mode.maxBytes / 1024) });
    select.append(option);
  }
  select.value = attachment?.mode?.id ?? DEFAULT_IMAGE_COMPRESSION_MODE_ID;
  select.addEventListener('change', onChange);
  return select;
}

function updatePrivateAttachmentUi() {
  const panel = privateAttachmentPanel;
  if (!panel) return;
  const imageAttachments = normalizePrivateImageAttachments(privateImageAttachments);
  const hasAttachments = imageAttachments.length > 0;
  panel.hidden = !hasAttachments;
  panel.classList.toggle('is-list', hasAttachments);
  if (!hasAttachments) {
    panel.replaceChildren();
    return;
  }
  const rows = [];
  imageAttachments.forEach((attachment, index) => {
    const row = document.createElement('div');
    row.className = 'composer-attachment-row';
    const label = document.createElement('span');
    label.className = 'composer-attachment-label';
    label.textContent = privateAttachmentLabelForImage(attachment);
    const modeSelect = createImageModeSelect(attachment, () => {
      recompressPrivateImageAttachment(index, modeSelect.value).catch((error) => console.error(error));
    });
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = t('common.remove');
    remove.addEventListener('click', () => removeComposerImageAt('private', index));
    row.append(label, modeSelect, remove);
    rows.push(row);
  });
  panel.replaceChildren(...rows);
}

function updateImageAttachmentUi(kind) {
  if (kind === 'private') {
    updatePrivateAttachmentUi();
    return;
  }
  const attachments = normalizePublicImageAttachments(publicImageAttachments);
  const attachment = attachments[0] ?? null;
  const panel = kind === 'public' ? publicAttachmentPanel : privateAttachmentPanel;
  const label = kind === 'public' ? publicAttachmentLabel : privateAttachmentLabel;
  const modeSelect = kind === 'public' ? publicImageModeSelect : privateImageModeSelect;
  if (panel) panel.hidden = attachments.length === 0;
  if (label) {
    label.textContent = attachments.length > 1
      ? tPlural('composer.imagesAttached', attachments.length)
      : attachment
      ? t('composer.imageAttachmentLabel', { name: attachment.name, kib: Math.ceil(attachment.bytes.length / 1024), mode: attachment.mode.label.toLowerCase() })
      : t('composer.noImage');
  }
  if (modeSelect && attachment) modeSelect.value = attachment.mode.id;
}

async function setImageAttachment(kind, file, modeId) {
  const status = kind === 'public' ? publicComposerCostStatus : privateComposerCostStatus;
  const input = kind === 'public' ? publicImageInput : privateImageInput;
  const button = kind === 'public' ? publicImageButton : privateImageButton;
  try {
    if (status) {
      status.textContent = t('composer.preparingImagePreview');
      status.dataset.state = 'short';
    }
    if (button) button.disabled = true;
    const attachment = await requestCompressedImageFile(file, {
      modeId,
      title: kind === 'public' ? t('composer.attachPublicImageTitle') : t('composer.attachPrivateImageTitle'),
      hint: kind === 'public'
        ? t('composer.publicImageHint')
        : t('composer.privateImageHint'),
      submitLabel: t('composer.attachImage'),
      partCounter: kind === 'private' ? privateImageAttachmentPartCount : imageAttachmentPartCount,
      extraRows: [
        { label: t('composer.gramFee'), value: t('composer.feeDependsOnCapsuleCount') },
      ],
    });
    if (!attachment) {
      refreshComposerCostStatus();
      return;
    }
    if (kind === 'public') {
      publicImageAttachments = [...publicImageAttachments, attachment];
      insertImageMarkerForComposer('public', publicImageAttachments.length);
    } else {
      privateImageAttachments = [...privateImageAttachments, attachment];
      insertImageMarkerForComposer('private', privateImageAttachments.length);
    }
    updateImageAttachmentUi(kind);
    refreshComposerPublishPolicy();
  } catch (error) {
    if (kind === 'public') {
      publicImageAttachments = [];
    }
    updateImageAttachmentUi(kind);
    if (status) {
      status.textContent = error?.message ?? t('composer.imageCompressionBlocked');
      status.dataset.state = 'short';
    }
    console.error(error);
  } finally {
    if (input) input.value = '';
    if (button) button.disabled = kind === 'public' ? publicComposerSendBlocked() : Boolean(privateSendBlockReason());
  }
}

async function recompressPrivateImageAttachment(index, modeId) {
  const attachment = privateImageAttachments[index];
  if (!attachment?.sourceFile) return;
  const status = privateComposerCostStatus;
  try {
    if (status) {
      status.textContent = t('composer.recompressingImage');
      status.dataset.state = 'short';
    }
    const next = await compressImageFile(attachment.sourceFile, modeId);
    privateImageAttachments = privateImageAttachments.map((item, itemIndex) => (
      itemIndex === index ? next : item
    ));
    updateImageAttachmentUi('private');
    refreshComposerEditorBlocks(messageInput);
    refreshComposerCostStatus();
  } catch (error) {
    if (status) {
      status.textContent = error?.message ?? t('composer.imageCompressionBlocked');
      status.dataset.state = 'short';
    }
    throw error;
  }
}

async function recompressImageAttachment(kind) {
  const attachment = kind === 'public' ? normalizePublicImageAttachments(publicImageAttachments)[0] : privateImageAttachments[0];
  const modeSelect = kind === 'public' ? publicImageModeSelect : privateImageModeSelect;
  if (!attachment?.sourceFile || !modeSelect) return;
  if (kind === 'public') {
    const next = await compressImageFile(attachment.sourceFile, modeSelect.value);
    publicImageAttachments = publicImageAttachments.map((item, index) => (index === 0 ? next : item));
    updateImageAttachmentUi('public');
    refreshComposerEditorBlocks(publicMessageInput);
    refreshComposerCostStatus();
  } else {
    await recompressPrivateImageAttachment(0, modeSelect.value);
  }
}

function privateComposerPlaceholder({ readOnly = false, group = false, muted = false, banned = false } = {}) {
  if (!plathoWallet) return walletNeededReason();
  if (banned) return t('composer.bannedInGroup');
  if (readOnly) return t('composer.readOnlyChannel');
  if (muted) return t('composer.mutedInGroup');
  if (group === 'public') return t('composer.publicGroupMessage');
  if (group) return t('composer.privateGroupMessage');
  return t('composer.privateMessage');
}

function publicComposerPlaceholder() {
  return publicCommentTarget ? t('composer.publicComment') : t('composer.publicMessage');
}

function refreshComposerPublishPolicy() {
  const canPublish = Boolean(plathoWallet);
  if (composer) composer.dataset.publishMode = canPublish ? 'vault-balance' : 'wallet-required';
  if (messageInput) {
    messageInput.removeAttribute('maxlength');
    messageInput.placeholder = privateComposerPlaceholder({
      readOnly: composer?.dataset.readOnly === 'true', group: groupLaneOfThread(activeThread()), muted: groupSelfIsMuted(activeThread()), banned: groupSelfIsBanned(activeThread()),
    });
  }
  if (publicComposer) publicComposer.dataset.publishMode = canPublish ? 'vault-balance' : 'wallet-required';
  if (publicMessageInput) {
    publicMessageInput.removeAttribute('maxlength');
    publicMessageInput.placeholder = publicComposerPlaceholder();
  }
  for (const control of attachmentControls) {
    control.hidden = false;
    if (control.classList?.contains('attachment-button')) {
      control.title = canPublish ? t('composer.attachImage') : t('composer.walletToAttachImages');
    }
  }
  if (privateImageModeSelect) {
    privateImageModeSelect.disabled = !canPublish;
  }
  if (publicImageModeSelect) {
    publicImageModeSelect.disabled = !canPublish;
  }
  updateImageAttachmentUi('private');
  updateImageAttachmentUi('public');
  updatePrivateFileAttachmentUi();
  refreshComposerCostStatus();
}

function privateComposerAddMenuVisible() {
  return Boolean(privateComposerAddMenu && !privateComposerAddMenu.hidden);
}

function hidePrivateComposerAddMenu() {
  if (privateComposerAddMenu) privateComposerAddMenu.hidden = true;
  privateComposerAddButton?.setAttribute('aria-expanded', 'false');
}

function showPrivateComposerAddMenu() {
  if (!privateComposerAddMenu || !privateComposerAddButton || privateComposerAddButton.disabled) return;
  privateComposerAddMenu.hidden = false;
  privateComposerAddButton.setAttribute('aria-expanded', 'true');
}

function togglePrivateComposerAddMenu() {
  if (privateComposerAddMenuVisible()) hidePrivateComposerAddMenu();
  else showPrivateComposerAddMenu();
}

function publicComposerAddMenuVisible() {
  return Boolean(publicComposerAddMenu && !publicComposerAddMenu.hidden);
}
function hidePublicComposerAddMenu() {
  if (publicComposerAddMenu) publicComposerAddMenu.hidden = true;
  publicComposerAddButton?.setAttribute('aria-expanded', 'false');
}
function showPublicComposerAddMenu() {
  if (!publicComposerAddMenu || !publicComposerAddButton || publicComposerAddButton.disabled) return;
  publicComposerAddMenu.hidden = false;
  publicComposerAddButton.setAttribute('aria-expanded', 'true');
}
function togglePublicComposerAddMenu() {
  if (publicComposerAddMenuVisible()) hidePublicComposerAddMenu();
  else showPublicComposerAddMenu();
}

function composerBlocksFromDraft(text, attachments = [], replyDraft = privateReplyDraft, fileAttachments = privateFileAttachments, shareDraft = privateShareDraft) {
  const source = String(text ?? '');
  const images = normalizePrivateImageAttachments(attachments);
  const usedImages = new Set();
  const blocks = [];
  const pushText = (value) => {
    const trimmed = String(value ?? '').trim();
    if (trimmed) blocks.push({ type: 'text', text: trimmed });
  };
  const pushImage = (index) => {
    const imageIndex = Number(index) - 1;
    const attachment = images[imageIndex];
    if (!attachment || usedImages.has(imageIndex)) return;
    usedImages.add(imageIndex);
    blocks.push({
      type: 'image',
      attachment,
      bytes: attachment.bytes,
      width: attachment.width,
      height: attachment.height,
      format: attachment.mediaFormat ?? PLATHO_COMPACT_IMAGE_FORMATS.WEBP,
      url: attachment.dataUrl,
      mode: attachment.mode?.id,
      modeLabel: attachment.mode?.label,
    });
  };
  let usedShare = false;
  const pushShare = () => {
    if (!shareDraft?.entryId || usedShare) return;
    usedShare = true;
    blocks.push({ type: 'share', ...shareDraft });
  };
  const files = Array.isArray(fileAttachments) ? fileAttachments : [];
  const usedFiles = new Set();
  const pushFile = (index) => {
    const fileIndex = Number(index) - 1;
    const file = files[fileIndex];
    if (!file?.bytes?.length || usedFiles.has(fileIndex)) return;
    usedFiles.add(fileIndex);
    blocks.push({ type: 'file', name: file.name, mime: file.mime, bytes: file.bytes });
  };
  let cursor = 0;
  COMPOSER_MARKER_RE.lastIndex = 0;
  for (const match of source.matchAll(COMPOSER_MARKER_RE)) {
    pushText(source.slice(cursor, match.index));
    if (match[1] !== undefined) pushImage(match[1]);
    else if (match[2] !== undefined) pushFile(match[2]);
    else if (match[3] !== undefined) pushShare();
    cursor = match.index + match[0].length;
  }
  pushText(source.slice(cursor));
  images.forEach((_, index) => {
    if (!usedImages.has(index)) pushImage(index + 1);
  });
  files.forEach((_, index) => {
    if (!usedFiles.has(index)) pushFile(index + 1);
  });
  if (shareDraft?.entryId && !usedShare) {
    usedShare = true;
    blocks.unshift({ type: 'share', ...shareDraft });
  }
  if (blocks.length > 0 && replyDraft?.refEntryId !== undefined && replyDraft?.refEntryId !== null) {
    blocks.unshift({ type: 'reply', refEntryId: String(replyDraft.refEntryId), author: replyDraft.author ?? '', snippet: replyDraft.snippet ?? '' });
  }
  return blocks;
}

function displayBlocksFromDocumentBlocks(blocks) {
  return (blocks ?? []).map((block) => {
    if (block.type === 'text') return { type: 'text', text: block.text ?? '' };
    if (block.type === 'image') {
      const bytes = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
      return {
        type: 'image',
        url: block.url ?? bytesToImageDataUrl(bytes, 'image/webp'),
        bytes: bytes.length,
        width: block.width,
        height: block.height,
        mode: block.mode,
        modeLabel: block.modeLabel,
      };
    }
    if (block.type === 'reply') {
      return { type: 'reply', refEntryId: block.refEntryId, author: block.author ?? '', snippet: block.snippet ?? '' };
    }
    if (block.type === 'share') {
      return {
        type: 'share',
        entryId: String(block.entryId ?? ''),
        bodyHash: String(block.bodyHash ?? ''),
        authorWallet: String(block.authorWallet ?? ''),
        author: String(block.author ?? ''),
        title: String(block.title ?? ''),
        snippet: String(block.snippet ?? ''),
        hasImage: block.hasImage === true,
        textTruncated: block.textTruncated === true,
      };
    }
    if (block.type === 'file') {
      const bytes = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
      return {
        type: 'file',
        name: String(block.name ?? 'file'),
        mime: String(block.mime ?? 'application/octet-stream'),
        size: block.url ? Number(block.size ?? 0) : bytes.length,
        url: block.url ?? `data:${block.mime ?? 'application/octet-stream'};base64,${bytesToBase64(bytes)}`,
      };
    }
    if (block.type === 'sender') return { type: 'sender', username: String(block.username ?? '') };
    return null;
  }).filter(Boolean);
}

function messageDocumentBytesFromDraft(text, attachments = [], options = {}, replyDraft = privateReplyDraft, fileAttachments = privateFileAttachments, shareDraft = privateShareDraft) {
  const blocks = composerBlocksFromDraft(text, attachments, replyDraft, fileAttachments, shareDraft);
  if (blocks.length <= 0) return null;
  return encodeMessageDocumentBlocks(blocks, options);
}

function stripInlineFormatting(text) {
  return String(text ?? '')
    .replace(/\*\*\*([^*\n]+)\*\*\*/g, '$1')
    .replace(/\*\*([^*\n]+)\*\*/g, '$1')
    .replace(/\*([^*\n]+)\*/g, '$1')
    .replace(/`([^`\n]+)`/g, '$1')
    .replace(/\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function messagePreviewFromBlocks(input = []) {
  const blocks = Array.isArray(input) ? input : [];
  const text = blocks.find((block) => block?.type === 'text' && String(block.text ?? '').trim())?.text;
  if (text) return messagePreviewText(text);
  const imageCount = blocks.filter((block) => block?.type === 'image').length;
  if (imageCount > 0) return tPlural('chat.previewImages', imageCount);
  const fileBlocks = blocks.filter((block) => block?.type === 'file');
  if (fileBlocks.length === 1) return String(fileBlocks[0].name ?? '').trim() || t('chat.previewFile');
  if (fileBlocks.length > 1) return tPlural('chat.previewFiles', fileBlocks.length);
  if (blocks.some((block) => block?.type === 'share')) return t('chat.previewSharedPost');
  return '';
}

function insertComposerMarker(editor, marker) {
  if (!editor) return;
  composerEditorInsertChip(editor, marker);
}


function composerToolbarForTextarea(textarea) {
  const form = textarea?.closest?.('.composer');
  return form ? form.querySelector('.composer-toolbar') : null;
}

function showComposerToolbar(textarea) {
  composerToolbarForTextarea(textarea)?.classList.add('is-open');
}

function hideComposerToolbar(textarea) {
  composerToolbarForTextarea(textarea)?.classList.remove('is-open');
}

function applyComposerFormat(editor, format) {
  if (!editor) return;
  switch (format) {
    case 'bold': composerEditorToggleFormat(editor, 'fmt-bold'); break;
    case 'italic': composerEditorToggleFormat(editor, 'fmt-italic'); break;
    case 'heading': composerEditorToggleHeading(editor); break;
    case 'select': composerEditorSelectWordAtCaret(editor); break;
    default: break;
  }
}

function composerEditorSelectWordAtCaret(el) {
  if (!el || el.disabled) return;
  focusComposerField(el);
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  if (!range.collapsed) {
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    return;
  }
  const word = composerEditorWordRangeAtCaret(range, el);
  if (!word) return;
  const r = document.createRange();
  r.setStart(word.startNode, word.startOffset);
  r.setEnd(word.endNode, word.endOffset);
  sel.removeAllRanges();
  sel.addRange(r);
}

function setupComposerToolbar(toolbar, textarea, hideButton) {
  if (!toolbar || !textarea) return;
  hideButton?.addEventListener('click', () => hideComposerToolbar(textarea));
  toolbar.addEventListener('mousedown', (event) => {
    if (event.target.closest('.composer-toolbar-button, .composer-toolbar-hide, .composer-toolbar-dock, .composer-toolbar-maximize')) event.preventDefault();
  });
  toolbar.addEventListener('click', (event) => {
    const button = event.target.closest('[data-format]');
    if (!button) return;
    event.preventDefault();
    applyComposerFormat(textarea, button.dataset.format);
  });
  textarea.addEventListener('click', () => showComposerToolbar(textarea));
}


function insertImageMarkerForComposer(kind, index) {
  const marker = `[image ${index}]`;
  insertComposerMarker(kind === 'public' ? publicMessageInput : messageInput, marker);
}

function insertFileMarkerForComposer(kind, index) {
  insertComposerMarker(kind === 'public' ? publicMessageInput : messageInput, `[file ${index}]`);
}

function removeAllFileMarkersForComposer(kind) {
  const textarea = kind === 'public' ? publicMessageInput : messageInput;
  if (!textarea) return;
  let value = String(textarea.value ?? '').replace(/\n?\[file\s+\d+\](?!\()(?=\n|$)/ig, '');
  value = value.replace(/\[file\s+\d+\](?!\()/ig, '');
  if (!value.trim()) value = '';
  textarea.value = value;
}

function removeImageMarkerForComposer(kind, removedIndex) {
  const textarea = kind === 'public' ? publicMessageInput : messageInput;
  if (!textarea) return;
  const removedMarkerNum = Number(removedIndex) + 1;
  let droppedOne = false;
  const next = String(textarea.value ?? '').replace(/\[(?:image|img)\s+(\d+)\](?!\()/ig, (match, numStr) => {
    const n = Number(numStr);
    if (!droppedOne && n === removedMarkerNum) { droppedOne = true; return ''; }
    if (n > removedMarkerNum) return `[image ${n - 1}]`;
    return match;
  });
  let value = next.replace(/\n{3,}/g, '\n\n');
  if (!value.trim()) value = '';
  textarea.value = value;
}


