function applyPublicPaneTab() {
  if (publicPane) publicPane.dataset.publicTab = publicPaneTab;
  if (appShell) appShell.dataset.publicTab = publicPaneTab;
  markPublicPaneTabs();
  if (publicSectionHeading) {
    const key = PUBLIC_SECTION_HEADINGS[publicPaneTab] ?? PUBLIC_SECTION_HEADINGS.following;
    publicSectionHeading.setAttribute('data-i18n', key);
    publicSectionHeading.textContent = t(key);
  }
}

function markPublicPaneTabs() {
  const roomOnScreen = appShell?.dataset?.roomOpen === 'true';
  for (const button of publicTabButtons) {
    const section = button.dataset.publicTab;
    const selected = section === publicPaneTab && (section === 'groups' || !roomOnScreen);
    button.setAttribute('aria-selected', selected ? 'true' : 'false');
    button.tabIndex = selected ? 0 : -1;
  }
  for (const strip of [publicTabs, publicNavTabs]) {
    const buttons = strip ? publicTabButtons.filter((button) => strip.contains(button)) : [];
    if (buttons.length > 0 && !buttons.some((button) => button.tabIndex === 0)) buttons[0].tabIndex = 0;
  }
}

function publicRoomMoved() {
  markPublicPaneTabs();
  if (!isPublicViewActive()) return;
  if (appShell?.dataset?.roomOpen === 'true') {
    closePublicDiscovery();
    return;
  }
  showPublicPaneTabBody();
  if (publicPaneTab === 'following') renderPublicSurface({ anchorUnread: false });
}

function choosePublicPaneTab(tab) {
  if (publicPostDetailOpen) closePublicPostDetail();
  if (publicChannelViewOpen) closePublicChannelView({ reopenReturnTo: false });
  setPublicPaneTab(tab);
  syncNavBackAffordance();
}

function setPublicPaneTab(tab) {
  const next = PUBLIC_PANE_TABS.includes(tab) ? tab : 'following';
  if (next !== 'groups') closePublicRoom();
  const previous = publicPaneTab;
  if (next !== previous) {
    exitComposerMaximize();
    publicPaneTab = next;
    applyPublicPaneTab();
    if (previous === 'following') flushPublicFeedRead();
    if (next === 'following' && isPublicViewActive()) {
      renderPublicSurface({ anchorUnread: !publicPostDetailOpen && !publicChannelViewOpen });
    }
  }
  showPublicPaneTabBody();
  markPublicFollowingTab();
}

function showPublicPaneTabBody() {
  if (publicPaneTab === 'all') openPublicDiscovery().catch((error) => console.error(error));
  else closePublicDiscovery();
  if (publicPaneTab === 'groups') renderPublicGroupsList();
}

function setView(view, { restoreRoom = true } = {}) {
  exitComposerMaximize();
  if (view === 'public' && !restoreRoom) publicRoomThreadId = null;
  const activeBefore = activeThreadId;
  const room = view === 'public' ? livePublicRoomThread() : null;
  if (room) putPublicRoomOnScreen(room);
  else takePublicRoomOffScreen();
  appShell.dataset.view = view;
  if (activeThreadId !== activeBefore || (view === 'chats' && threadListOwesDraw)) renderThreads();
  if (view !== 'chats') {
    appShell.dataset.chatOpen = 'false';
  } else {
    appShell.dataset.chatOpen = activeThreadId ? 'true' : 'false';
  }
  if (view !== 'public') flushPublicFeedRead();
  if (view !== 'public') closePublicDiscovery();
  railItems.forEach((item) => item.classList.toggle('is-active', item.dataset.tab === view));
  panels.forEach((panel) => panel.classList.toggle('is-active', panel.dataset.panel === view));
  if (globalThis.__plathoGiftRuntimeReady) applyGiftAppearance();
  labelConversationBackButton();
  if (view === 'chats') {
    conversationStickToBottom = true;
    renderConversation();
  }
  if (view === 'public' && appShell.dataset.roomOpen === 'true') {
    conversationStickToBottom = true;
    renderConversation();
  }
  if (view === 'public') {
    renderPublicSurface({ anchorUnread: publicPane?.dataset?.postOpen !== 'true' && publicPane?.dataset?.channelOpen !== 'true' });
    showPublicPaneTabBody();
  }
  syncWalletCardLife(view === 'wallet');
  syncGiftMarkMotion();
  if (view === 'wallet') {
    refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
      const rateLimited = noteTonRpcRateLimit(error);
      setVaultStatus(rateLimited ? 'RPC busy, retrying' : 'sync blocked');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
    void refreshWalletAssets();
    refreshWalletIncomingBadges();
  } else {
    scheduleVaultAutoRefresh(2_000);
  }
}

function refreshProfilePaneReads() {
  if (!plathoWallet?.address) return;
  (async () => {
    try { await refreshWalletTonBalanceForProfile(); } catch (error) { if (!noteTonRpcRateLimit(error)) console.error(error); }
    try { await refreshAthProtocolStats(); } catch { }
    try { await refreshOwnProfileAvatar(); } catch (error) {
      if (!isUninitializedAccountError(error) && !noteTonRpcRateLimit(error)) console.error(error);
    }
  })();
}

