actionSubmitButton?.addEventListener('click', (event) => {
  if (activeActionDialog) activeActionDialog.submitClick = { at: Date.now(), detail: Number(event.detail) || 0 };
}, { capture: true });
actionForm?.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (!activeActionDialog) return;
  if (!actionDialogPressAccepted(activeActionDialog, lastActionPressAt, Date.now())) return;
  const waiting = [...(actionFields?.querySelectorAll('input[data-fill-on-touch="waiting"]') ?? [])].find((input) => input.required && !input.value);
  if (waiting) {
    waiting.readOnly = false;
    waiting.dataset.fillOnTouch = 'open';
    if (document.activeElement === waiting) waiting.blur();
    waiting.reportValidity();
    return;
  }
  const values = collectActionDialogValues();
  const dialogAtStart = activeActionDialog;
  if (dialogAtStart.priced && dialogAtStart.paintedGeneration !== writeGenerationNow()) {
    repaintActiveActionDialogPrices({ force: true });
    if (actionHint) {
      actionHint.textContent = joinHintSentences(t('dialog.pricesMoved'), actionHint.textContent);
      actionHint.dataset.tone = 'error';
      actionHint.hidden = false;
      speakToScreenReader(t('dialog.pricesMoved'));
    }
    return;
  }
  const validate = dialogAtStart.validateSubmit;
  if (typeof validate === 'function') {
    if (actionSubmitButton) actionSubmitButton.disabled = true;
    if (actionCancelButton) actionCancelButton.disabled = true;
    if (actionDismissButton) actionDismissButton.disabled = true;
    if (actionHint) { actionHint.textContent = dialogAtStart.checkingHint ?? t('dialog.checking'); actionHint.dataset.tone = 'muted'; }
    dialogAtStart.hintOverridden = true;
    let outcome = null;
    dialogAtStart.validating = true;
    try {
      outcome = await validate(values);
    } catch (error) {
      outcome = { ok: false, error: error?.message || t('dialog.validationFailed') };
    } finally {
      dialogAtStart.validating = false;
    }
    if (activeActionDialog !== dialogAtStart) return;
    if (outcome && outcome.ok) {
      closeActionDialog(outcome.result ?? values);
      return;
    }
    if (outcome?.repaint === true) repaintActiveActionDialogPrices({ force: true });
    if (actionHint) {
      actionHint.textContent = (outcome && outcome.error) || t('dialog.invalidInput');
      appendDialogActionButton(actionHint, outcome?.action ?? null);
      actionHint.dataset.tone = 'error';
      actionHint.hidden = false;
      speakToScreenReader(actionHint.textContent);
    }
    dialogAtStart.hintOverridden = true;
    if (actionSubmitButton) actionSubmitButton.disabled = false;
    if (actionCancelButton) actionCancelButton.disabled = !dialogAtStart.cancellable;
    if (actionDismissButton) actionDismissButton.disabled = false;
    return;
  }
  if (actionSubmitButton) actionSubmitButton.disabled = true;
  window.setTimeout(() => closeActionDialog(values), 0);
});
