async function openAddPublicChannelDialog() {
  try {
    const result = await openActionDialog({
      title: t('public.addChannelTitle'),
      hint: t('public.addChannelHint'),
      submitLabel: t('public.addChannelSubmit'),
      validateSubmit: async (values) => {
        try {
          const resolved = await resolvePublicChannelIdentity(values.channelIdentity);
          return { ok: true, result: { ...values, resolved } };
        } catch (error) {
          if (error instanceof UsernameNotRegisteredError) {
            return { ok: false, error: t('chat.usernameNotRegistered', { name: canonicalUsernameDisplay(values.channelIdentity) }) };
          }
          return { ok: false, error: t('dialog.invalidInput') };
        }
      },
      fields: [
        {
          id: 'channelIdentity',
          label: t('public.channelFieldLabel'),
          placeholder: t('public.channelPlaceholder'),
          autocomplete: 'off',
        },
        {
          id: 'localLabel',
          label: t('public.localLabelField'),
          placeholder: t('public.localLabelPlaceholder'),
          required: false,
          autocomplete: 'off',
        },
      ],
    });
    if (!result) return;
    const { identity, authorWallet } = result.resolved;
    const localLabel = result.localLabel?.trim();
    const name = localLabel || (
      identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS
        ? shortAddress(authorWallet)
        : displayIdentityLabel(identity)
    );
    const id = `wallet:${authorWallet}`;
    addCustomPublicChannel({
      id,
      name,
      avatar: publicChannelAvatar(name),
      subtitle: localLabel
        ? `${publicChannelSubtitleForIdentity(identity)} - ${publicChannelRouteLabel(identity, authorWallet)}`
        : publicChannelSubtitleForIdentity(identity),
      authorWallet,
    });
    if (publicChannelSearch) {
      publicChannelSearch.value = '';
      publicChannelSearchQuery = '';
    }
    setPublicStatus('channel added');
  } catch (error) {
    setPublicStatus('channel blocked');
    console.error(error);
  }
}

