async function runAccountActivation({ line = null } = {}) {
  try {
    registerVaultKeysButton.disabled = true;
    await submitVaultRegisterMessagingKeys();
  } catch (error) {
    const rateLimited = noteTonRpcRateLimit(error);
    holdStatusText(vaultDraftStatus, gramShortfallText(error) ?? (rateLimited ? t('errors.networkNotNow') : t('vault.activationBlocked')), {
      scope: plathoWallet?.address ?? null,
      refresh: refreshMessagingControls,
    });
    if (line === privateComposerCostStatus || line === publicComposerCostStatus) {
      const said = gramShortfallText(error) ?? (rateLimited ? t('errors.networkNotNow') : t('send.activationFailed'));
      holdStatusText(line, said, {
        scope: line === privateComposerCostStatus ? activeThreadId : publicComposerHoldScope(),
        refresh: refreshComposerCostStatus,
      });
      speakToScreenReader(said);
      const next = gramShortfallText(error)
        ? { label: t('wallet.receiveGram'), run: () => { void showReceiveWalletTonDialog(); } }
        : { label: t('wallet.activateAccount'), run: () => { void runAccountActivation({ line }); } };
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'composer-cost-action';
      button.textContent = next.label;
      button.addEventListener('click', next.run);
      appendLineButton(line, button);
    }
    if (!rateLimited) console.error(error);
  } finally {
    refreshMessagingControls();
  }
}
