profileAvatarInput?.addEventListener('change', async () => {
  const file = profileAvatarInput.files?.[0];
  if (!file) return;
  try {
    setAvatarButton?.toggleAttribute('disabled', true);
    const avatar = await requestProfileAvatarUploadDetails(file);
    if (!avatar) return;
    avatar.pricedGeneration = writeGenerationNow();
    avatar.signer = plathoWallet;
    pendingProfileAvatarModeId = avatar.mode.id;
    await submitProfileAvatarUpdate(avatar);
  } catch (error) {
    const rateLimited = noteTonRpcRateLimit(error);
    if (rateLimited || isTonRpcRecoverableReadError(error) || error?.code === 'PLATHO_AVATAR_PRECHECK_UNREADABLE' || error?.code === 'SHARD_DEBT_UNREAD') {
      setProfileAvatarStatus(t('avatar.needsRetry'), 'error');
    } else if (error?.code === 'PLATHO_ATH_REQUIRED' || error?.code === 'PLATHO_WALLET_GRAM_REQUIRED'
      || error?.code === 'PLATHO_AVATAR_NEEDS_ACTIVATION') {
      setProfileAvatarStatus(String(error.message), 'error');
    } else {
      const message = refusalTextFor(error) ?? String(error?.avatarDiagnosticStatus ?? error?.message ?? t('avatar.blocked'));
      setProfileAvatarStatus(message, 'error');
      console.error(error);
    }
  } finally {
    if (profileAvatarInput) profileAvatarInput.value = '';
    refreshMessagingControls();
  }
});

