async function confirmPublicPostPublish() {
  const costNow = () => {
    const plan = publicComposerSendPlan(publicMessageInput?.value ?? '', publicImageAttachments, publicFileAttachments);
    return (composerCostPrecondition(Math.max(1, plan.length)) ?? publicComposerFinalCostLine(plan))?.text?.trim() || '';
  };
  const result = await openActionDialog({
    title: t('public.confirmPublishTitle'),
    hint: t('public.confirmPublishHint'),
    priced: true,
    submitLabel: t('public.confirmPublishSubmit'),
    fields: [{
      id: 'publishConfirmed',
      type: 'checkbox',
      required: true,
      label: t('public.confirmPublishCheckbox'),
    }],
    summary: () => { const cost = costNow(); return cost ? [cost] : []; },
    validateSubmit: async (values) => (values.publishConfirmed ? { ok: true, result: { confirmed: true } } : { ok: false, error: t('public.confirmPublishTick') }),
  }).catch(() => null);
  return result?.confirmed === true;
}

publicComposer?.addEventListener('submit', async (event) => {
  event.preventDefault();
  enforcePublicComposerByteLimit();
  const text = publicMessageInput?.value.trim() ?? '';
  const attachments = normalizePublicImageAttachments(publicImageAttachments);
  const fileAttachments = normalizePrivateFileAttachments(publicFileAttachments);
  if (publicDocumentBlocksFromDraft(text, attachments, fileAttachments).length === 0) return;
  if (!plathoWallet) {
    setPublicStatus('create wallet first');
    return;
  }
  if (tonRpcLimited()) {
    refreshComposerCostStatus();
    return;
  }
  if (composerPricesMoved(publicComposerCostStatus)) return;
  if (publicComposerPartLimitMessage(publicComposerSendPlan(text, attachments, fileAttachments).length)) {
    refreshComposerCostStatus();
    setPublicStatus('message too large');
    return;
  }
  const commentsAllowed = publicComposerCommentsCheckbox?.checked !== false;
  if (!publicCommentTarget && commentsAllowed && !(await confirmPublicCommentsRisk())) {
    setPublicStatus('publish cancelled');
    return;
  }
  if (!publicCommentTarget && !(await confirmPublicPostPublish())) {
    setPublicStatus('publish cancelled');
    return;
  }
  const pressGeneration = writeGenerationNow();
  const send = publicComposer.querySelector('.send-button');
  send?.toggleAttribute('disabled', true);
  const draftCommentTarget = publicCommentTarget;
  const draftReplyTo = publicCommentReplyTo;
  const draftShare = publicShareDraft;
  const draftWasMaximized = publicComposer.classList.contains('is-maximized');
  const pressSession = walletSessionGeneration;
  const pressWallet = plathoWallet?.address ?? null;
  const recordsPlacedBefore = publicOptimisticRecordsPlaced;
  publicMessageInput.value = '';
  exitComposerMaximize();
  publicImageAttachments = [];
  publicFileAttachments = [];
  const pressQuote = { replyTo: draftReplyTo ?? null, share: draftShare ?? null };
  setPublicCommentReplyTo(null);
  setPublicShareDraft(null);
  updateImageAttachmentUi('public');
  updatePublicFileAttachmentUi();
  refreshComposerCostStatus();
  try {
    if (draftCommentTarget) {
      if (publicPostDetailOpen) publicPostDetailScrollToLatest = true;
      await enqueueOutgoingPublish(() => submitPublicCommentDirect(draftCommentTarget, text, attachments, fileAttachments, { pricedGeneration: pressGeneration, quote: pressQuote }));
    } else {
      await enqueueOutgoingPublish(() => submitPublicPostDirect({
        text,
        attachments,
        fileAttachments,
        commentsAllowed,
        pricedGeneration: pressGeneration,
        quote: pressQuote,
      }));
      void maybeWarnChannelNotDiscoverable();
    }
    if (!publicPostDetailOpen) setPublicCommentTarget(null);
  } catch (error) {
    if (!sameWalletSessionAsPress(pressSession, pressWallet)) {
      if (!noteTonRpcRateLimit(error)) console.warn('[public] a post of a session gone was refused', error);
      return;
    }
    const rateLimited = noteTonRpcRateLimit(error);
    const cancelled = isPublishPriceChangeCancelled(error);
    if (publicOptimisticRecordsPlaced === recordsPlacedBefore || error?.publicRowTakenBack === true) {
      const current = String(publicMessageInput.value ?? '');
      const writtenSince = (current.trim().length > 0 && current !== text)
        || (Array.isArray(publicImageAttachments) && publicImageAttachments.length > 0)
        || (Array.isArray(publicFileAttachments) && publicFileAttachments.length > 0);
      publicMessageInput.value = writtenSince && current.trim() && current !== text ? `${text}\n\n${current}` : text;
      publicImageAttachments = writtenSince ? [...attachments, ...(publicImageAttachments ?? [])] : attachments;
      publicFileAttachments = writtenSince ? [...fileAttachments, ...(publicFileAttachments ?? [])] : fileAttachments;
      if (draftReplyTo && !(writtenSince && publicCommentReplyTo)) setPublicCommentReplyTo(draftReplyTo);
      if (draftShare && !(writtenSince && publicShareDraft)) setPublicShareDraft(draftShare);
      updateImageAttachmentUi('public');
      updatePublicFileAttachmentUi();
      refreshComposerCostStatus();
      if (error?.code === 'PRICES_MOVED') {
        announceComposerPricesMoved(publicComposerCostStatus);
      } else if (!cancelled) {
        holdStatusText(publicComposerCostStatus, rateLimited ? TON_RPC_CONNECTING_STATUS
          : (gramShortfallText(error) ?? messageMetaReasonDisplayText(privateSendPreflightStatusText(error))), {
          scope: publicComposerHoldScope(draftCommentTarget),
          refresh: refreshComposerCostStatus,
        });
        speakToScreenReader(publicComposerCostStatus?.textContent);
      }
      if (draftWasMaximized && !publicComposer.classList.contains('is-maximized')) {
        toggleComposerMaximize(publicComposer, publicComposer.querySelector('.composer-toolbar-maximize'));
      }
    }
    setPublicStatus(cancelled ? 'publish cancelled' : (rateLimited ? 'sync delayed' : (draftCommentTarget ? 'comment blocked' : 'publish blocked')));
    if (!rateLimited && !cancelled) console.error(error);
  } finally {
    refreshPublicSendButtonState();
  }
});

composer?.addEventListener('submit', async (event) => {
  event.preventDefault();
  refreshComposerPublishPolicy();
  enforceComposerByteLimit();
  const text = messageInput.value.trim();
  const attachments = normalizePrivateImageAttachments(privateImageAttachments);
  if (!text && attachments.length === 0 && !privateShareDraft
    && normalizePrivateFileAttachments(privateFileAttachments).length === 0) {
    focusComposerField(messageInput);
    return;
  }
  const thread = threads.find((item) => item.id === activeThreadId) ?? null;
  if (!thread) return;
  if (!conversationLaneOnScreen(thread) || composerDraftThreadId !== thread.id) return;
  if (composerPricesMoved(privateComposerCostStatus)) return;
  if (thread.readOnly) {
    messageInput.value = '';
    renderConversation();
    return;
  }
  if (!plathoWallet?.address) {
    refreshMessagingControls();
    return;
  }
  if (isPublicGroupThread(thread)) {
    await sendGroupMessageFromComposer(thread, text);
    return;
  }
  if (!localIdentity || !localRecipientKeyPair || !localSignedPublicBundle) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('send.preparingKeys');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshMessagingControls();
    return;
  }
  if (!hasActivePlathoAccount()) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t(activationAnswerKnownFor(plathoWallet?.address) ? 'chat.activateBeforeSending' : 'send.checkingActivation');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  if (isGroupThread(thread)) {
    await sendGroupMessageFromComposer(thread, text);
    return;
  }
  if (tonRpcLimited()) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('chat.rpcBusy');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }

  const selectedSuite = currentOutgoingPrivateSuite();
  const senderOptions = currentPrivateSenderOptions();
  const sendPlan = privateComposerSendPlan(text, attachments, senderOptions);
  const limitMessage = privateComposerPartLimitMessage(sendPlan.length);
  if (limitMessage) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = limitMessage;
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  const replyDraft = privateReplyDraft ? { ...privateReplyDraft } : null;
  const shareDraft = privateShareDraft ? { ...privateShareDraft } : null;
  const fileAttachments = normalizePrivateFileAttachments(privateFileAttachments);
  const draftBlocks = composerBlocksFromDraft(text, attachments, replyDraft, fileAttachments, shareDraft);
  if (draftBlocks.length === 0) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('composer.nothingToSend');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  const displayBlocks = displayBlocksFromDocumentBlocks(draftBlocks);
  const message = {
    type: 'out',
    text: messagePreviewFromBlocks(displayBlocks),
    blocks: displayBlocks,
    meta: 'sending',
    senderAnonymous: senderOptions.includeSenderWalletMetadata === false,
    privateDraft: {
      text,
      attachments,
      selectedSuite,
      senderOptions,
      replyDraft,
      shareDraft,
      fileAttachments,
    },
    privateManualRetryAvailable: false,
    privateCancelAvailable: false,
    pressedThisSession: true,
    pricedGeneration: writeGenerationNow(),
    ...localMessageOrderFields(),
  };
  const releasePress = holdLiveSend(message);
  ownSendPendingRender = true;
  insertThreadMessage(thread, message);
  persistMessageToEncryptedHistory(thread, message).catch((error) => console.warn('[history] a pressed message could not be kept', error));
  const sendContext = {
    thread,
    message,
    text,
    attachments,
    selectedSuite,
    senderOptions,
    replyDraft,
    shareDraft,
    fileAttachments,
    retryAttempt: 0,
    confirmAttempt: 0,
  };
  refreshThreadAfterMessageChange(thread);
  messageInput.value = '';
  exitComposerMaximize();
  privateImageAttachments = [];
  setPrivateReplyDraft(null);
  setPrivateShareDraft(null);
  privateFileAttachments = [];
  updatePrivateFileAttachmentUi();
  updateImageAttachmentUi('private');
  focusComposerField(messageInput);
  refreshComposerCostStatus();
  if (sendButton) sendButton.disabled = true;
  renderThreads();
  renderConversation();


  const keylessBudget = usingKeylessTonRpc();
  const endPrivateOutboundWork = keylessBudget ? beginPrivateOutboundWork() : null;
  try {
    if (keylessBudget && privateChainSyncPromise) {
      await Promise.race([
        Promise.resolve(privateChainSyncPromise).catch(() => {}),
        delay(PRIVATE_SEND_SYNC_WAIT_CAP_MS),
      ]);
    }
    await enqueueOutgoingPublish(() => attemptPrivateComposerMessagePublish(sendContext));
  } catch (error) {
    await settlePrivateComposerSendError(sendContext, error);
  } finally {
    if (endPrivateOutboundWork) endPrivateOutboundWork();
    releasePress();
  }
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
});

