function shortAddress(address) {
  const text = displayWalletAddress(address);
  if (text.length <= 16) return text || t('wallet.connected');
  return `${text.slice(0, 6)}...${text.slice(-6)}`;
}

function requireAthMasterAddress() {
  const address = appConfig.ath?.masterAddress ?? globalThis.plathoAthMasterAddress;
  if (!address) throw new Error('ATHMaster contract address is not configured');
  return address;
}

function requireUsernameRegistryAddress() {
  const address = appConfig.usernameRegistry?.address ?? globalThis.plathoUsernameRegistryAddress;
  if (!address) throw new Error('UsernameRegistry contract address is not configured');
  return address;
}

function requireProfileRegistryAddress() {
  const address = appConfig.profileRegistry?.address ?? globalThis.plathoProfileRegistryAddress;
  if (!address) throw new Error('ProfileRegistry contract address is not configured');
  return address;
}

function requireBasechainAddress(address, label) {
  const parsed = parseTonAddress(address);
  if (parsed.workchain !== 0) throw new Error(`${label} must be a basechain address`);
  return parsed.raw;
}

function requirePlathoWallet() {
  if (!plathoWallet?.address) throw new Error('Create or import a Platho wallet first');
  return plathoWallet;
}

function requirePlathoWalletAddress() {
  return requirePlathoWallet().address;
}

function parseDecimalAmount(input, decimals, symbol) {
  const text = String(input ?? '').trim().replace(',', '.');
  const match = text.match(new RegExp(`^([0-9]+)(?:\\.([0-9]{0,${decimals}}))?$`));
  if (!match) throw Object.assign(new Error(t('wallet.amountFormatInvalid', { symbol, decimals })), { code: 'AMOUNT_FORMAT' });
  const whole = BigInt(match[1]);
  const fraction = BigInt((match[2] ?? '').padEnd(decimals, '0'));
  const amount = whole * (10n ** BigInt(decimals)) + fraction;
  if (amount <= 0n) throw Object.assign(new Error(t('wallet.amountNotPositive', { symbol })), { code: 'AMOUNT_NOT_POSITIVE' });
  return amount;
}

function parseTonAmountNanotons(input) {
  return parseDecimalAmount(input, 9, 'GRAM');
}

function formatDecimalAmount(units, decimals, fractionDigits = 4) {
  const amount = BigInt(units ?? 0n);
  const scale = 10n ** BigInt(decimals);
  const whole = amount / scale;
  const fraction = amount % scale;
  if (fractionDigits <= 0) return whole.toString();
  const divisor = 10n ** BigInt(decimals - fractionDigits);
  const shown = (fraction / divisor).toString().padStart(fractionDigits, '0').replace(/0+$/, '');
  return shown ? `${whole}.${shown}` : whole.toString();
}

function formatTonNanotons(value) {
  return formatDecimalAmount(value, 9, 4);
}

function formatDecimalAmountUp(units, decimals, fractionDigits = 4) {
  const amount = BigInt(units ?? 0n);
  if (fractionDigits <= 0 || fractionDigits >= decimals) return formatDecimalAmount(amount, decimals, fractionDigits);
  const divisor = 10n ** BigInt(decimals - fractionDigits);
  return formatDecimalAmount(((amount + divisor - 1n) / divisor) * divisor, decimals, fractionDigits);
}

function formatTonNanotonsUp(value) {
  return formatDecimalAmountUp(value, 9, 4);
}

function formatAthAtomic(value) {
  return formatDecimalAmount(value, 9, 4);
}

function groupDecimalText(text) {
  const [whole, fraction] = String(text ?? '').split('.');
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, '\u202F');
  return fraction ? `${grouped}.${fraction}` : grouped;
}

function formatAthProfileAmount(value) {
  if (value === null || value === undefined) return '-';
  return `${formatAthAtomicGrouped(value)} ATH`;
}

function formatAthAtomicGrouped(value) {
  return groupDecimalText(formatAthAtomic(value));
}

function renderAthProfileStats() {
  setText(athSupplyStatus, formatAthProfileAmount(athProtocolState.total_supply));
}

let feeVaultState = { wallet: null, address: null, snapshot: null };
let feeVaultStakeInFlight = false;
let vaultRestoreInFlight = false;
let vaultRestoreChecking = false;
let vaultRestoreLost = null;

const FEE_VAULT_RENT_NANOTONS_PER_YEAR = 2_143_751n;
const FEE_VAULT_CUSTODY_RENT_NANOTONS_PER_YEAR = 5_781_618n;

const stakedAthOf = (snapshot) => (snapshot?.staked ?? 0n) / FV_ATOMIC_PER_ATH;

const VAULT_SNAPSHOT_MAX_AGE_S = 600;
const VAULT_DEPLOY_SETTLE_MS = 120_000;
function vaultClock() {
  return { nowSec: Math.floor(Date.now() / 1000), chainSec: chainNowSec(), clockMarginSec: Math.ceil(WALLET_CLOCK_TOLERANCE_MS / 1000) };
}

function vaultSnapshotOutdated() {
  const snapshot = feeVaultState.wallet === plathoWallet?.address ? feeVaultState.snapshot : null;
  if (!snapshot) return false;
  if (snapshot.assumed === true) return Date.now() - Number(snapshot.assumedAt ?? 0) > VAULT_DEPLOY_SETTLE_MS;
  if (snapshot.restoreSentAt && (snapshot.state === VAULT_FROZEN || snapshot.custodyFrozen)) return true;
  if (snapshot.state !== VAULT_LIVE && snapshot.state !== VAULT_ABSENT && snapshot.state !== VAULT_FROZEN) return false;
  return Math.floor(Date.now() / 1000) - Number(snapshot.nowSec ?? 0) > VAULT_SNAPSHOT_MAX_AGE_S;
}

const OWN_VAULT_EXIT_SETTLE_MS = VAULT_DEPLOY_SETTLE_MS;
const OWN_VAULT_EXIT_LAND_MS = WALLET_EXTERNAL_VALIDITY_S * 1000 + VAULT_DEPLOY_SETTLE_MS;
const OWN_VAULT_EXIT_CLOCK_SKEW_MS = 60_000;
const OWN_VAULT_EXIT_STORAGE_KEY = 'platho.vault.ownExit.v2';
const ownVaultExitMarks = new Map();

function ownVaultExitStorageKey(wallet) {
  return `${scopedStorageKey(OWN_VAULT_EXIT_STORAGE_KEY)}:${walletIndexedDbSuffix(wallet)}`;
}

function validOwnVaultExitMark(wallet, stored, now = Date.now()) {
  if (!stored || !/^\d+$/.test(String(stored.feeDueAfter ?? '')) || !(Number(stored.at) > 0)) return null;
  const feeDueAfter = BigInt(stored.feeDueAfter);
  const at = Number(stored.at);
  if (feeDueAfter > FV_PROTOCOL_FEE || at > now + OWN_VAULT_EXIT_CLOCK_SKEW_MS) return null;
  return { wallet, feeDueAfter, at, stored: true };
}

function forgetOwnVaultExit(wallet) {
  ownVaultExitMarks.delete(wallet);
  try { localStorage.removeItem(ownVaultExitStorageKey(wallet)); } catch { }
}

function ownVaultExitInFlight(wallet = plathoWallet?.address) {
  if (!wallet) return null;
  const now = Date.now();
  let mark = ownVaultExitMarks.get(wallet) ?? null;
  try {
    const raw = localStorage.getItem(ownVaultExitStorageKey(wallet));
    if (raw !== null) {
      mark = validOwnVaultExitMark(wallet, JSON.parse(raw), now);
      if (!mark) forgetOwnVaultExit(wallet);
    } else if (mark?.stored === true) {
      mark = null;
      ownVaultExitMarks.delete(wallet);
    }
  } catch { }
  if (mark && now >= mark.at + OWN_VAULT_EXIT_LAND_MS) { forgetOwnVaultExit(wallet); return null; }
  return mark;
}

function noteOwnVaultExit(wallet, feeDueAfter) {
  if (!wallet || feeDueAfter === undefined || feeDueAfter === null) return;
  const earlier = ownVaultExitInFlight(wallet);
  const due = BigInt(feeDueAfter);
  const mark = { wallet, feeDueAfter: earlier && earlier.feeDueAfter > due ? earlier.feeDueAfter : due, at: Date.now(), stored: false };
  ownVaultExitMarks.set(wallet, mark);
  if (plathoLocalDataClearing) return;
  try {
    localStorage.setItem(ownVaultExitStorageKey(wallet), JSON.stringify({ feeDueAfter: String(mark.feeDueAfter), at: mark.at }));
    mark.stored = true;
  } catch { }
}

async function broadcastOwnVaultExit(messages, feeDueAfter, purpose, { signer: given = null } = {}) {
  const signer = given ?? requirePlathoWallet();
  const wallet = signer.address;
  const need = messages.reduce((sum, message) => sum + BigInt(message.amount), 0n);
  await assertWalletGramAtLeast(need + walletSendFeeReserveNanotons(), purpose);
  noteOwnVaultExit(wallet, feeDueAfter);
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  try {
    await sendPlathoWalletTransaction(requireSameWallet(signer), { messages }, { transport, awaitOutcome: true });
  } catch (error) {
    if (broadcastMayHaveLanded(error)) noteOwnVaultExit(wallet, feeDueAfter);
    throw error;
  }
  noteOwnVaultExit(wallet, feeDueAfter);
}

function ownVaultExitReflectedBy(exit, snapshot) {
  if (!exit || !snapshot) return false;
  if (Number(snapshot.nowSec ?? 0) * 1000 >= exit.at + OWN_VAULT_EXIT_LAND_MS) return true;
  return snapshot.state === VAULT_LIVE && snapshot.stale !== true && snapshot.assumed !== true
    && BigInt(snapshot.feeDue ?? 0n) >= exit.feeDueAfter;
}

function settleOwnVaultExit() {
  const exit = ownVaultExitInFlight(feeVaultState.wallet);
  if (!exit || !ownVaultExitReflectedBy(exit, feeVaultState.snapshot)) return;
  forgetOwnVaultExit(exit.wallet);
}

function ownVaultFeeDue(snapshot) {
  const read = BigInt(snapshot?.feeDue ?? FV_PROTOCOL_FEE);
  const exit = ownVaultExitInFlight();
  if (!exit || Number(snapshot?.nowSec ?? 0) * 1000 >= exit.at + OWN_VAULT_EXIT_LAND_MS) return read;
  return exit.feeDueAfter > read ? exit.feeDueAfter : read;
}

function rememberVaultReading(wallet, address, snapshot) {
  if (!wallet || plathoWallet?.address !== wallet || !address) return;
  const store = walletLocalStorage();
  if (snapshot?.state === VAULT_ABSENT) {
    rememberedVaultReading = null;
    if (store.getItem(WALLET_LOCAL_VAULT_READING_KEY) !== null) store.removeItem(WALLET_LOCAL_VAULT_READING_KEY);
    return;
  }
  if (snapshot?.state !== VAULT_LIVE || snapshot.assumed === true || snapshot.stale === true) return;
  const feeDue = BigInt(snapshot.feeDue ?? FV_PROTOCOL_FEE);
  const low = BigInt(snapshot.balance ?? 0n) < FV_FLOAT_TOPUP_BELOW;
  rememberedVaultReading = { wallet, address, feeDue, low };
  const text = JSON.stringify({ address, feeDue: String(feeDue), low });
  if (store.getItem(WALLET_LOCAL_VAULT_READING_KEY) !== text) store.setItem(WALLET_LOCAL_VAULT_READING_KEY, text);
}

async function loadRememberedVaultReading(wallet) {
  if (!wallet?.address || !vaultSupported()) return;
  let held = null;
  try { held = JSON.parse(walletLocalStorage().getItem(WALLET_LOCAL_VAULT_READING_KEY) ?? 'null'); } catch { held = null; }
  if (!held || typeof held !== 'object') return;
  let address = null;
  try { address = await vaultAddressFor(wallet.address); } catch { return; }
  if (plathoWallet !== wallet) return;
  let feeDue = null;
  try { feeDue = BigInt(held.feeDue); } catch { feeDue = null; }
  if (!sameWalletAddress(held.address, address) || feeDue === null || feeDue < 0n || feeDue > FV_PROTOCOL_FEE) {
    walletLocalStorage().removeItem(WALLET_LOCAL_VAULT_READING_KEY);
    return;
  }
  if (feeVaultState.wallet === wallet.address && feeVaultState.snapshot) return;
  rememberedVaultReading = { wallet: wallet.address, address, feeDue, low: held.low === true };
  refreshComposerCostStatus();
}

const PUBLIC_ROUTING_READ_DEADLINE_MS = 8_000;

const VAULT_ROUTING_FAILURE_MEMORY_MS = 60_000;
let feeVaultRoutingRead = null;
let feeVaultRoutingFailedAt = 0;

function readFeeVaultForRouting() {
  if (!feeVaultRoutingRead) {
    feeVaultRoutingRead = refreshFeeVaultState({ critical: true })
      .catch(() => { })
      .then(() => { if (feeVaultState.snapshot?.state === VAULT_UNKNOWN || vaultSnapshotOutdated() || feeVaultState.snapshot?.stale === true) feeVaultRoutingFailedAt = Date.now(); })
      .finally(() => { feeVaultRoutingRead = null; });
  }
  return feeVaultRoutingRead;
}

async function boundedFeeVaultRoutingRead() {
  if (Date.now() - feeVaultRoutingFailedAt < VAULT_ROUTING_FAILURE_MEMORY_MS && !feeVaultRoutingRead) return;
  let timer = null;
  const deadline = new Promise((resolve) => { timer = setTimeout(resolve, PUBLIC_ROUTING_READ_DEADLINE_MS); });
  try {
    await Promise.race([readFeeVaultForRouting(), deadline]);
  } finally {
    clearTimeout(timer);
  }
}

async function publicPublishRouting() {
  if (!vaultSupported() || !plathoWallet?.address) return {};
  if (writeGenerationNow() < 18) return {};
  const own = feeVaultState.wallet === plathoWallet.address ? feeVaultState.snapshot : null;
  if (!own || (own.state !== VAULT_LIVE && own.state !== VAULT_ABSENT && own.state !== VAULT_FROZEN) || vaultSnapshotOutdated()) {
    await boundedFeeVaultRoutingRead();
    if (vaultSnapshotOutdated()) return {};
  }
  const snapshot = feeVaultState.snapshot;
  if (feeVaultState.wallet !== plathoWallet?.address) return {};
  if (!vaultSupported() || !feeVaultState.address || snapshot?.state !== VAULT_LIVE) return {};
  if (snapshot.stale || snapshot.assumed) return {};
  return { vaultAddress: feeVaultState.address, feeDue: ownVaultFeeDue(snapshot), prices: await messageNetworkPrices() };
}

async function convVaultRouting() {
  if (!vaultSupported() || !plathoWallet?.address) return {};
  let mine = feeVaultState.wallet === plathoWallet.address ? feeVaultState : null;
  if (!mine || (mine.snapshot?.state !== VAULT_LIVE && mine.snapshot?.state !== VAULT_ABSENT && mine.snapshot?.state !== VAULT_FROZEN)
    || vaultSnapshotOutdated()) {
    await boundedFeeVaultRoutingRead();
    mine = feeVaultState.wallet === plathoWallet.address ? feeVaultState : null;
  }
  if (mine?.snapshot?.assumed === true && mine.snapshot.assumedFrom) {
    await settleUnconfirmedVaultDeploy(plathoWallet.address);
    mine = feeVaultState.wallet === plathoWallet.address ? feeVaultState : null;
  }
  const aged = vaultSnapshotOutdated();
  if (mine?.snapshot?.state === VAULT_FROZEN) throw convVaultFrozenError();
  if (mine?.snapshot?.state !== VAULT_LIVE && mine?.snapshot?.state !== VAULT_ABSENT) throw convVaultStateUnknownError();
  if (mine.snapshot.state === VAULT_ABSENT && aged) throw convVaultStateUnknownError();
  const wantsDeploy = (snap) => snap?.state === VAULT_ABSENT
    || (snap?.state === VAULT_LIVE && snap.assumed !== true && BigInt(snap.balance ?? 0n) < FV_FLOAT_TOPUP_BELOW);
  const vaultAddress = (feeVaultState.wallet === plathoWallet.address ? feeVaultState.address : null) ?? await vaultAddressFor(plathoWallet.address);
  let deployVault = wantsDeploy(mine.snapshot);
  let flight = null;
  if (deployVault) {
    for (let round = 0; deployVault && round < 3; round += 1) {
      const carried = await feeVaultDeployCarriedElsewhere(plathoWallet.address);
      const after = feeVaultState.wallet === plathoWallet.address ? feeVaultState.snapshot : null;
      deployVault = !carried && wantsDeploy(after);
      if (!deployVault || !(feeVaultDeployFlight && feeVaultDeployFlight.wallet === plathoWallet.address)) break;
    }
  }
  if (deployVault) flight = openFeeVaultDeployFlight(plathoWallet.address);
  if (deployVault) {
    const wallet = plathoWallet.address;
    const own = heldVaultDeployLock(wallet);
    if (own) renewVaultDeployHold(wallet);
    const lock = own ?? await acquireVaultDeployLock(wallet);
    const readJustNow = Boolean(lock) && !lock.waited && Math.floor(Date.now() / 1000) - Number(feeVaultState.snapshot?.nowSec ?? 0) <= 2;
    if (!own && !readJustNow) {
      await refreshFeeVaultState({ critical: true });
      const read = plathoWallet?.address === wallet && feeVaultState.wallet === wallet ? feeVaultState.snapshot : null;
      if (read?.state === VAULT_FROZEN) { releaseVaultDeployLock(wallet); flight.settle(false); throw convVaultFrozenError(); }
      if ((read?.state !== VAULT_LIVE && read?.state !== VAULT_ABSENT) || (read.state === VAULT_ABSENT && vaultSnapshotOutdated())) {
        releaseVaultDeployLock(wallet);
        flight.settle(false);
        throw convVaultStateUnknownError();
      }
      if (!wantsDeploy(read)) {
        releaseVaultDeployLock(wallet);
        flight.settle(true);
        flight = null;
        deployVault = false;
      }
    }
    if (!lock && deployVault) console.warn('[vault] another window held the deploy past the wait; the vault is still absent, deployed here');
  }
  const snapshot = feeVaultState.wallet === plathoWallet.address ? feeVaultState.snapshot : null;
  const fresh = snapshot?.state === VAULT_LIVE && !snapshot.stale && !snapshot.assumed && !vaultSnapshotOutdated();
  return {
    vaultAddress,
    feeDue: fresh ? ownVaultFeeDue(snapshot) : FV_PROTOCOL_FEE,
    deployVault,
    deployFlight: flight,
    prices: await messageNetworkPrices(),
  };
}

const FEE_VAULT_DEPLOY_WAIT_MS = 45_000;
let feeVaultDeployFlight = null;

function openFeeVaultDeployFlight(wallet) {
  let resolve = null;
  const done = new Promise((r) => { resolve = r; });
  const flight = {
    wallet, at: Date.now(), done,
    settle: (landed) => {
      resolve(landed === true);
      if (feeVaultDeployFlight === flight) feeVaultDeployFlight = null;
      if (landed === true) { if (heldVaultDeployLock(wallet)) void watchVaultDeployAcrossWindows(wallet); } else releaseVaultDeployLock(wallet);
    },
  };
  const replaced = feeVaultDeployFlight;
  if (replaced && replaced.wallet === wallet) void done.then((landed) => replaced.settle(landed));
  feeVaultDeployFlight = flight;
  return flight;
}

function settleFeeVaultDeployFlight(wallet, landed, flight = null) {
  if (flight && typeof flight.settle === 'function') { flight.settle(landed); return; }
  if (feeVaultDeployFlight && feeVaultDeployFlight.wallet === wallet) feeVaultDeployFlight.settle(landed);
}

async function feeVaultDeployCarriedElsewhere(wallet) {
  const flight = feeVaultDeployFlight;
  if (!flight || flight.wallet !== wallet) return false;
  if (Date.now() - flight.at >= VAULT_DEPLOY_SETTLE_MS) { feeVaultDeployFlight = null; return false; }
  let timer = null;
  const timeout = new Promise((resolve) => { timer = setTimeout(() => resolve(false), FEE_VAULT_DEPLOY_WAIT_MS); });
  try {
    return await Promise.race([flight.done, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

async function acquireVaultDeployLock(wallet) {
  if (acquireVaultDeployLock.held && acquireVaultDeployLock.held.wallet !== wallet) releaseVaultDeployLock();
  const locks = globalThis.navigator?.locks;
  if (typeof locks?.request !== 'function') return { release: () => {}, waited: false };
  const name = `platho-vault-deploy.v1:${wallet}`;
  const take = (options) => new Promise((resolve) => {
    let free = () => {};
    const held = new Promise((done) => { free = done; });
    Promise.resolve(locks.request(name, options, (lock) => {
      if (!lock) { resolve(null); return undefined; }
      resolve(() => free());
      return held;
    })).catch(() => resolve(undefined));
  });
  let waited = false;
  let release = await take({ ifAvailable: true });
  if (release === undefined) return { release: () => {}, waited: false };
  if (!release) {
    waited = true;
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), FEE_VAULT_DEPLOY_WAIT_MS) : null;
    try { release = await take(controller ? { signal: controller.signal } : {}); } finally { if (timer) clearTimeout(timer); }
    if (!release) return null;
  }
  const held = { wallet, release, timer: null, watching: false };
  held.timer = setTimeout(() => { if (acquireVaultDeployLock.held === held) releaseVaultDeployLock(wallet); }, VAULT_DEPLOY_SETTLE_MS);
  acquireVaultDeployLock.held = held;
  return { release, waited };
}

function renewVaultDeployHold(wallet) {
  const held = acquireVaultDeployLock.held;
  if (!held || held.wallet !== wallet) return;
  clearTimeout(held.timer);
  held.timer = setTimeout(() => { if (acquireVaultDeployLock.held === held) releaseVaultDeployLock(wallet); }, VAULT_DEPLOY_SETTLE_MS);
  held.watching = false;
}

function heldVaultDeployLock(wallet) {
  const held = acquireVaultDeployLock.held;
  return held && held.wallet === wallet ? { release: held.release, waited: false } : null;
}

function releaseVaultDeployLock(wallet = null) {
  const held = acquireVaultDeployLock.held;
  if (!held || (wallet && held.wallet !== wallet)) return;
  acquireVaultDeployLock.held = null;
  clearTimeout(held.timer);
  try { held.release(); } catch { }
}

const VAULT_DEPLOY_WATCH_PAUSES_MS = Object.freeze([2_000, 4_000, 8_000, 16_000, 30_000]);
async function watchVaultDeployAcrossWindows(wallet) {
  const held = acquireVaultDeployLock.held;
  if (!held || held.wallet !== wallet || held.watching) return;
  held.watching = true;
  for (const pause of VAULT_DEPLOY_WATCH_PAUSES_MS) {
    await new Promise((resolve) => { setTimeout(resolve, pause); });
    if (acquireVaultDeployLock.held !== held || plathoWallet?.address !== wallet) return;
    await refreshFeeVaultState().catch(() => {});
  }
}

function requireSameWallet(signer) {
  if (!signer || plathoWallet !== signer) throw walletChangedBeforeSigningError();
  return signer;
}

function walletChangedBeforeSigningError() {
  const error = new Error(t('errors.walletChangedNothingSent'));
  error.code = 'PLATHO_WALLET_CHANGED';
  return error;
}

function sameWalletSessionAsPress(pressSession, pressWallet) {
  if (pressSession === walletSessionGeneration) return true;
  return Boolean(plathoWallet && pressWallet && sameWalletAddress(plathoWallet.address, pressWallet));
}

function walletOfSend(owner = undefined) {
  const wallet = plathoWallet;
  if (owner !== undefined && wallet && !(owner && sameWalletAddress(wallet.address, owner))) throw walletChangedBeforeSigningError();
  return wallet;
}

function noOtherWalletThan(signer) {
  return !plathoWallet || sameWalletAddress(plathoWallet.address, signer?.address);
}

function convVaultStateUnknownError() {
  const error = new Error('the fee vault could not be read — nothing was signed; the send will be retried');
  error.code = 'CONV_VAULT_STATE_UNKNOWN';
  return error;
}

function convVaultFrozenError() {
  const error = new Error('the fee vault is frozen for its rent — nothing was signed; it takes nothing until it is unfrozen');
  error.code = 'CONV_VAULT_FROZEN';
  return error;
}

function ownVaultFreeze() {
  const snapshot = feeVaultState.wallet === plathoWallet?.address ? feeVaultState.snapshot : null;
  if (!snapshot) return null;
  if (snapshot.state === VAULT_FROZEN) return { vault: true, custody: false };
  if (snapshot.state === VAULT_LIVE && snapshot.custodyFrozen) return { vault: false, custody: true };
  return null;
}

function noteFeeVaultDeployed(wallet, address, flight = null, { unconfirmed = null } = {}) {
  settleFeeVaultDeployFlight(wallet, true, flight);
  if (!wallet || plathoWallet?.address !== wallet) return;
  const from = Number.isInteger(unconfirmed?.seqno) && unconfirmed.seqno >= 0
    ? { seqno: unconfirmed.seqno, validUntil: Number(unconfirmed.validUntil) || 0, boc: unconfirmed.boc ?? null } : null;
  feeVaultState = {
    wallet, address, realAtoms: null,
    snapshot: { ...vaultSnapshot(null, vaultClock()), state: VAULT_LIVE, assumed: true, assumedAt: Date.now(), assumedFrom: from },
  };
}

function unconfirmedExternalOf(source) {
  if (!source || typeof source !== 'object') return null;
  if (Number(source.batchCount) > 1) return null;
  if (source.partialSend && Number(source.partialSend.sentChunks) > 0) return null;
  if (source.resumedAfterPartial) return null;
  const seqno = Number(source.pendingSeqno ?? source.builtSeqno);
  const validUntil = Number(source.pendingValidUntil ?? source.builtValidUntil);
  const boc = source.pendingBoc ?? source.builtBoc ?? null;
  if (Number.isInteger(seqno) && seqno >= 0) return { seqno, validUntil: Number.isFinite(validUntil) ? validUntil : 0, boc };
  const signed = walletExternalSignedFields(boc);
  return signed ? { seqno: signed.seqno, validUntil: signed.validUntil, boc } : null;
}

let unconfirmedVaultDeploy = null;
async function settleUnconfirmedVaultDeploy(wallet) {
  const asked = feeVaultState.wallet === wallet ? feeVaultState.snapshot : null;
  const from = asked?.assumed === true ? asked.assumedFrom ?? null : null;
  if (!from || !plathoWallet || plathoWallet.address !== wallet) return;
  if (!unconfirmedVaultDeploy || unconfirmedVaultDeploy.wallet !== wallet || unconfirmedVaultDeploy.seqno !== from.seqno) {
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    const outcome = awaitWalletExternalOutcome(plathoWallet, transport, from);
    const held = { wallet, seqno: from.seqno, outcome };
    unconfirmedVaultDeploy = held;
    void outcome.then(() => {}, () => {}).then(() => { if (unconfirmedVaultDeploy === held) unconfirmedVaultDeploy = null; });
  }
  let result;
  try { result = await unconfirmedVaultDeploy.outcome; } catch { throw convVaultStateUnknownError(); }
  const now = feeVaultState.wallet === wallet ? feeVaultState.snapshot : null;
  if (now?.assumed !== true || now.assumedFrom?.seqno !== from.seqno) return;
  const ran = result === 'consumed' || result === 'unverified';
  const late = ran && (result === 'unverified' || (Number(from.validUntil) > 0 && walletChainNowMs() > Number(from.validUntil) * 1000));
  feeVaultState = {
    ...feeVaultState,
    snapshot: ran
      ? { ...now, assumedFrom: null, assumedAt: late ? Date.now() - VAULT_DEPLOY_SETTLE_MS - 1 : Date.now() }
      : vaultSnapshot(null, vaultClock()),
  };
  if (late) {
    await boundedFeeVaultRoutingRead();
    if ((feeVaultState.wallet === wallet ? feeVaultState.snapshot : null)?.assumed === true) throw convVaultStateUnknownError();
  }
}

async function readAccountFreeze(transport, address, readOptions = {}) {
  if (typeof transport?.getAccountState !== 'function') throw new Error('no account-state door to tell a frozen account from an absent one');
  const row = accountStateRow(await transport.getAccountState({ address }, readOptions));
  if (row.status === ACCOUNT_FROZEN) return { hash: row.frozenHash };
  if (row.status === ACCOUNT_UNINIT || row.status === ACCOUNT_NONEXIST) return null;
  const disagree = new Error(`the account reads ${row.status} where its get-method found nothing`);
  disagree.code = 'ACCOUNT_STATE_DISAGREES';
  throw disagree;
}

const feeVaultAbsenceConfirmed = new Set();
const feeVaultFreezeAskedAt = new Map();
const VAULT_FREEZE_REASK_MS = 10 * 60_000;

async function refreshFeeVaultState({ critical = false } = {}) {
  const wallet = plathoWallet?.address ?? null;
  if (!vaultSupported() || !wallet) {
    feeVaultState = { wallet: null, address: null, snapshot: vaultSnapshot(null) };
    renderFeeDiscountRows();
    return feeVaultState;
  }
  let address = null;
  let transport = null;
  let readOptions = {};
  try {
    address = feeVaultState.wallet === wallet && feeVaultState.address
      ? feeVaultState.address
      : await vaultAddressFor(wallet);
    transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    if (!transport?.runGetMethod) {
      feeVaultState = { wallet, address, snapshot: vaultSnapshot(null, { state: VAULT_UNKNOWN }) };
      renderFeeDiscountRows();
      return feeVaultState;
    }
    readOptions = critical ? { cacheTtlMs: 0, priority: 'critical', skipIfRateLimited: false, queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS } : {};
    const view = await withVaultReadLock(() => createFeeVaultReader((call) => transport.runGetMethod({ ...call, ...readOptions }))(address));
    if (view === null && feeVaultState.wallet === wallet && feeVaultState.snapshot?.assumed === true
      && Date.now() - Number(feeVaultState.snapshot.assumedAt ?? 0) < VAULT_DEPLOY_SETTLE_MS) {
      renderFeeDiscountRows();
      return feeVaultState;
    }
    const absenceKey = `${wallet}|${address}`;
    const freeze = view === null && !feeVaultAbsenceConfirmed.has(absenceKey)
      ? await withVaultReadLock(() => readAccountFreeze(transport, address, readOptions))
      : null;
    if (view === null && freeze === null) feeVaultAbsenceConfirmed.add(absenceKey);
    const prior = feeVaultState.wallet === wallet && feeVaultState.address === address ? feeVaultState.snapshot : null;
    let snapshot = freeze
      ? vaultSnapshot(null, { ...vaultClock(), state: VAULT_FROZEN, frozenHash: freeze.hash })
      : vaultSnapshot(view, vaultClock());
    let realAtoms = null;
    if (snapshot.state === VAULT_LIVE) {
      let vaultAthWallet = null;
      try {
        const master = await resolveAthMasterProvider();
        vaultAthWallet = await withVaultReadLock(() => master.getWalletAddress(address, {
          address: requireAthMasterAddress(), ...criticalChainReadOptions(),
        }));
        const data = await withVaultReadLock(() => createAthWalletTonRpcProvider({ athWalletAddress: vaultAthWallet })
          .getWalletData({ address: vaultAthWallet }));
        realAtoms = nonNegativeBigInt(data.balance);
      } catch (error) {
        const limited = noteTonRpcRateLimit(error);
        if (isAthWalletNotDeployedError(error)) realAtoms = 0n;
        else if (!limited) console.warn('[vault] vault ATH wallet read failed', error);
        if (vaultAthWallet && !limited && ((snapshot.staked ?? 0n) > 0n || (snapshot.pending ?? 0n) > 0n)) {
          const custody = await withVaultReadLock(() => readAccountFreeze(transport, vaultAthWallet, readOptions)).catch(() => null);
          if (custody) {
            snapshot = { ...snapshot, custodyFrozen: { address: vaultAthWallet, hash: custody.hash } };
            realAtoms = null;
          }
        }
      }
    }
    snapshot = inheritVaultMarks(snapshot, prior, { custodyAnswered: realAtoms !== null });
    if (plathoWallet?.address !== wallet) return feeVaultState;
    feeVaultState = { wallet, address, snapshot, realAtoms };
    if ((snapshot.state === VAULT_LIVE || snapshot.state === VAULT_FROZEN) && acquireVaultDeployLock.held?.watching === true) releaseVaultDeployLock(wallet);
    if ((prior?.state === VAULT_FROZEN && snapshot.state !== VAULT_FROZEN) || (prior?.custodyFrozen && !snapshot.custodyFrozen)) refreshComposerCostStatus();
    rememberVaultReading(wallet, address, snapshot);
    settleOwnVaultExit();
  } catch (error) {
    const busy = isTonRpcRateLimitError(error) || error?.code === 'QUEUE_TIMEOUT' || error?.code === 'TIMEOUT';
    const askedKey = `${wallet}|${address}`;
    const askedRecently = Date.now() - (feeVaultFreezeAskedAt.get(askedKey) ?? -Infinity) < VAULT_FREEZE_REASK_MS;
    if (!busy && !askedRecently && address && transport && plathoWallet?.address === wallet) {
      feeVaultFreezeAskedAt.set(askedKey, Date.now());
      const freeze = await withVaultReadLock(() => readAccountFreeze(transport, address, readOptions)).catch(() => null);
      if (freeze && plathoWallet?.address === wallet) {
        const held = feeVaultState.wallet === wallet ? feeVaultState.snapshot : null;
        const sentAt = Number(held?.restoreSentAt) > 0 && Date.now() - Number(held.restoreSentAt) < VAULT_RESTORE_LANDING_MS ? held.restoreSentAt : null;
        feeVaultState = { wallet, address, snapshot: { ...vaultSnapshot(null, { ...vaultClock(), state: VAULT_FROZEN, frozenHash: freeze.hash }), ...(sentAt ? { restoreSentAt: sentAt } : {}) }, realAtoms: null };
        renderFeeDiscountRows();
        return feeVaultState;
      }
    }
    if (feeVaultState.wallet === wallet && feeVaultState.snapshot?.state === VAULT_FROZEN) {
      feeVaultState = { ...feeVaultState, snapshot: { ...feeVaultState.snapshot, stale: true } };
      if (!noteTonRpcRateLimit(error)) console.warn('[vault] fee vault read failed', error);
      renderFeeDiscountRows();
      return feeVaultState;
    }
    if (feeVaultState.wallet !== wallet || feeVaultState.snapshot?.state !== VAULT_LIVE) {
      feeVaultState = { wallet, address: feeVaultState.wallet === wallet ? feeVaultState.address : null,
        snapshot: vaultSnapshot(null, { state: VAULT_UNKNOWN }) };
    } else {
      feeVaultState = { ...feeVaultState, snapshot: { ...feeVaultState.snapshot, stale: true } };
    }
    if (!noteTonRpcRateLimit(error)) console.warn('[vault] fee vault read failed', error);
  }
  renderFeeDiscountRows();
  return feeVaultState;
}

function renderFeeDiscountRows() {
  if (!feeDiscountStatus) return;
  if (!vaultSupported()) {
    setText(feeDiscountStatus, t('profile.feeDiscountAfterUpgrade'));
    if (unstakeAthButton) unstakeAthButton.hidden = true;
    return;
  }
  if (feeVaultState.wallet !== (plathoWallet?.address ?? null)) {
    setText(feeDiscountStatus, t('profile.statusChecking'));
    if (unstakeAthButton) unstakeAthButton.hidden = true;
    return;
  }
  const snapshot = feeVaultState.snapshot;
  const freeze = ownVaultFreeze();
  const restoreLanding = Boolean(freeze) && vaultRestoreLanding(snapshot, feeVaultState.address);
  const restoreLost = Boolean(freeze) && vaultRestoreLostNow();
  if (vaultRestoreButton) {
    vaultRestoreButton.hidden = !freeze;
    vaultRestoreButton.disabled = vaultRestoreInFlight || restoreLanding || restoreLost;
  }
  if (freeze && !vaultRestoreInFlight) setText(vaultRestoreStatus, restoreLost ? t('profile.vaultRestoreLost') : t(restoreLanding ? 'profile.stakeSent' : 'profile.vaultRestoreAction'));
  const restoreLabel = vaultRestoreButton?.querySelector?.('span[data-i18n]');
  if (restoreLabel && freeze) {
    const key = freeze.vault ? 'profile.vaultRestore' : 'profile.custodyRestore';
    restoreLabel.setAttribute('data-i18n', key);
    restoreLabel.textContent = t(key);
  }
  if (freeze?.vault) {
    setText(feeDiscountStatus, t('profile.vaultFrozenStatus'));
    if (unstakeAthButton) unstakeAthButton.hidden = true;
    if (recoverAthButton) recoverAthButton.hidden = true;
    if (vaultFloatButton) vaultFloatButton.hidden = true;
    return;
  }
  if (snapshot?.state === VAULT_UNKNOWN) {
    setText(feeDiscountStatus, t('profile.statusChecking'));
    if (unstakeAthButton) unstakeAthButton.hidden = true;
    return;
  }
  const staked = snapshot?.staked ?? 0n;
  const wholeAth = stakedAthOf(snapshot);
  setText(feeDiscountStatus, staked > 0n
    ? `${(Number(snapshot.bps) / 100).toFixed(2)}%`
    : t('profile.feeDiscountNone'));
  if (unstakeAthButton) {
    const parked = snapshot?.pending ?? 0n;
    unstakeAthButton.hidden = (wholeAth <= 0n && parked <= 0n) || Boolean(freeze?.custody);
    setText(unstakeAthStatus, parked > 0n
      ? t('profile.unstakePending')
      : `${groupDecimalText(String(wholeAth))} ATH`);
  }
  if (recoverAthButton) {
    const plan = planRecovery({ vaultAddress: feeVaultState.address, snapshot, realAtoms: feeVaultState.realAtoms ?? null });
    recoverAthButton.hidden = !plan.ok;
    if (plan.ok) setText(recoverAthStatus, `${groupDecimalText(String(plan.stranded / FV_ATOMIC_PER_ATH))} ATH`);
  }
  if (vaultFloatButton) {
    const plan = planWithdrawFloat({ vaultAddress: feeVaultState.address, snapshot });
    vaultFloatButton.hidden = !plan.ok;
    if (plan.ok) setText(vaultFloatStatus, `${formatGramNanotons(plan.amount)} GRAM`);
  }
}

async function openVaultFloatDialog() {
  if (!vaultSupported() || !plathoWallet?.address) return;
  await readVaultAtPress(vaultFloatStatus);
  const snapshot = feeVaultState.wallet === plathoWallet.address ? feeVaultState.snapshot : null;
  const plan = planWithdrawFloat({ vaultAddress: feeVaultState.address, snapshot });
  if (!plan.ok) { renderFeeDiscountRows(); return; }
  const amount = formatGramNanotons(plan.amount);
  const proceed = await openActionDialog({
    title: t('profile.vaultFloatTitle'),
    hint: t('profile.vaultFloatHint', { amount }),
    submitLabel: t('profile.vaultFloatSubmit', { amount }),
    fields: [],
    summary: () => [
      { label: t('profile.vaultFloat'), value: `${amount} GRAM` },
      { label: t('common.balanceNeeded'), value: balanceNeededText(plan.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n) + walletSendFeeReserveNanotons()) },
    ],
  });
  if (!proceed) return;
  if (feeVaultStakeInFlight) { setText(vaultFloatStatus, t('profile.stakeSending')); return; }
  feeVaultStakeInFlight = true;
  if (vaultFloatButton) vaultFloatButton.disabled = true;
  setText(vaultFloatStatus, t('profile.stakeSending'));
  try {
    const signer = requirePlathoWallet();
    const owner = signer.address;
    const vaultAddress = await vaultAddressFor(owner);
    if (vaultAddress !== feeVaultState.address) throw new Error('vault does not belong to the signing wallet');
    const need = plan.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n);
    await assertWalletGramAtLeast(need + walletSendFeeReserveNanotons(), 'withdraw vault float');
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    await sendPlathoWalletTransaction(requireSameWallet(signer), { messages: plan.messages }, { transport, awaitOutcome: true });
    setText(vaultFloatStatus, t('profile.stakeSent'));
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (broadcastMayHaveLanded(error)) { setText(vaultFloatStatus, t('profile.stakeSent')); queueAthPostTransactionRefresh(); return; }
    setText(vaultFloatStatus, error?.code === 'PLATHO_WALLET_GRAM_REQUIRED' ? error.message : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('profile.stakeFailed'));
    if (error?.code !== 'PLATHO_WALLET_GRAM_REQUIRED' && !noteTonRpcRateLimit(error)) console.warn('[vault] float withdrawal failed', error);
  } finally {
    feeVaultStakeInFlight = false;
    if (vaultFloatButton) vaultFloatButton.disabled = false;
  }
}

async function readFrozenAccountRestore(address, frozenHash, { candidates = [], alive = () => true } = {}) {
  const requestOptions = { priority: 'critical', skipIfRateLimited: false, queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS };
  const whileAlive = (read) => async (...args) => {
    if (!alive()) throw Object.assign(new Error('the session that asked for the unfreeze is over'), { code: 'PLATHO_SESSION_OVER' });
    return read(...args);
  };
  let frozen = await matchFrozenState(frozenHash, candidates);
  let reason = null;
  if (!frozen) {
    const readState = createAccountStateAtReader({ requestOptions });
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    const search = await preFreezeStateFromArchive({
      address, frozenHash,
      listTransactions: whileAlive(createAccountHistoryReader({ requestOptions })),
      readStateAt: whileAlive(async (account, seqno) => accountStateRow(await readState(account, seqno))),
      readLatestSeqno: whileAlive(async () => Number((await transport.getMasterchainInfo(requestOptions))?.last?.seqno)),
    });
    frozen = search.found;
    reason = search.reason;
    if (!frozen) console.warn('[vault] the frozen state was not found in the archive', { address, reason });
  }
  const last = await whileAlive(createShardLastTransactionReader({ requestOptions }))(address);
  const debt = last ? frozenAccountDebtNanotons({ dueCarried: last.storageFeesDue, lastTransactionAt: last.now, nowSec: chainNowSec() }) : null;
  return { frozen, debt, reason };
}

async function frozenVaultCustody(vaultAddress) {
  try {
    const custody = await resolveVaultCustodyWallet(vaultAddress);
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    const freeze = await withVaultReadLock(() => readAccountFreeze(transport, custody, { cacheTtlMs: 0, priority: 'critical',
      skipIfRateLimited: false, queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS }));
    return freeze ? { address: custody, hash: freeze.hash } : null;
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[vault] the stake\'s wallet could not be asked whether it froze', error);
    return null;
  }
}

const VAULT_ARCHIVE_LOST_REASONS = new Set(['hash-mismatch', 'no-state-before', 'no-frozen-hash']);

function vaultFrozenComposerReason() {
  if (vaultRestoreInFlight) return t('send.unfreezeSending');
  if (vaultRestoreLanding()) return t('send.unfreezeSent');
  if (vaultRestoreChecking) return t('send.unfreezeChecking');
  if (vaultRestoreLostNow()) return t('send.vaultFrozenLost');
  return t('send.vaultFrozen');
}
function vaultRestoreLostNow() {
  const lost = vaultRestoreLost;
  return Boolean(lost) && lost.wallet === plathoWallet?.address && lost.vault === feeVaultState.address && lost.hash === feeVaultState.snapshot?.frozenHash;
}

function vaultRestoreRefusalText(plan) {
  if (plan?.reason === 'state-lost') return t('profile.vaultRestoreLost');
  if (plan?.reason === 'state-unfound') return t('profile.vaultRestoreUnfound');
  if (plan?.reason === 'nothing-frozen') return t('profile.statusChecking');
  return t('profile.vaultReadUnanswered');
}

function vaultRestoreSay(text, line = null, lineText = text) {
  setText(vaultRestoreStatus, text);
  if (!line || (line !== privateComposerCostStatus && line !== publicComposerCostStatus)) return;
  const tookFocus = holdStatusText(line, lineText, { scope: line === privateComposerCostStatus ? activeThreadId : publicComposerHoldScope(), refresh: refreshComposerCostStatus });
  if (!tookFocus) speakToScreenReader(lineText);
}

async function openVaultRestoreDialog({ line = null } = {}) {
  if (!vaultSupported() || !plathoWallet?.address) return;
  if (vaultRestoreInFlight) { vaultRestoreSay(t('profile.stakeSending'), line, t('send.unfreezeSending')); return; }
  if (vaultRestoreLanding()) { vaultRestoreSay(t('profile.stakeSent'), line, t('send.unfreezeSent')); return; }
  if (vaultRestoreChecking) return;
  const ask = {};
  vaultRestoreChecking = ask;
  const session = walletSessionGeneration;
  const ours = () => session === walletSessionGeneration;
  try {
    vaultRestoreSay(t('profile.statusChecking'), line, t('send.unfreezeChecking'));
    await readVaultAtPress(vaultRestoreStatus);
    if (!ours()) return;
    const wallet = plathoWallet?.address ?? null;
    const freeze = ownVaultFreeze();
    const snapshot = feeVaultState.wallet === wallet ? feeVaultState.snapshot : null;
    const vaultAddress = feeVaultState.wallet === wallet ? feeVaultState.address : null;
    if (!freeze || !vaultAddress || !snapshot) {
      renderFeeDiscountRows();
      if (line) { releaseHeldStatus(line); refreshComposerCostStatus(); }
      return;
    }
    setText(vaultRestoreStatus, t('profile.statusChecking'));
    let plan;
    try {
      const vault = freeze.vault
        ? await readFrozenAccountRestore(vaultAddress, snapshot.frozenHash,
          { candidates: [{ codeBoc: feeVaultCodeBoc(), dataBoc: cellToBoc(feeVaultInitializedDataCell(wallet)) }], alive: ours })
        : null;
      const custodyFreeze = freeze.custody ? snapshot.custodyFrozen : await frozenVaultCustody(vaultAddress);
      const custody = custodyFreeze
        ? { address: custodyFreeze.address, ...(await readFrozenAccountRestore(custodyFreeze.address, custodyFreeze.hash, { alive: ours })) }
        : null;
      plan = planVaultRestore({ vaultAddress, vault, custody });
      if (!plan.ok && plan.reason === 'state-unfound' && [vault?.reason, custody?.reason].some((reason) => VAULT_ARCHIVE_LOST_REASONS.has(reason))) {
        plan = { ...plan, reason: 'state-lost' };
      }
    } catch (error) {
      if (!noteTonRpcRateLimit(error)) console.warn('[vault] the unfreeze could not be prepared', error);
      plan = { ok: false, reason: 'debt-unread' };
    }
    if (!ours() || plathoWallet?.address !== wallet) return;
    if (!plan.ok) {
      if (plan.reason === 'state-lost') vaultRestoreLost = { wallet, vault: vaultAddress, hash: snapshot.frozenHash };
      if (plan.reason === 'nothing-frozen') {
        setText(vaultRestoreStatus, vaultRestoreRefusalText(plan));
        if (line) releaseHeldStatus(line);
        return;
      }
      vaultRestoreSay(vaultRestoreRefusalText(plan), line);
      if (!line || (line !== privateComposerCostStatus && line !== publicComposerCostStatus)) showAppNotice(vaultRestoreRefusalText(plan), 6_000);
      return;
    }
    const debt = formatGramNanotonsUp(plan.debt);
    const kept = formatGramNanotonsUp(plan.kept);
    const need = vaultRestoreNeed(plan);
    const shortOf = (balance) => (balance !== null && balance < need
      ? `${t('dialog.labelPrefix', { label: t('common.balanceNeeded') })}${t('common.balanceNeededShort', { amount: formatTonNanotonsUp(need), available: formatTonNanotons(balance) })}`
      : null);
    const short = shortOf(await loadConnectedTonWalletBalance().catch(() => null));
    if (!ours() || plathoWallet?.address !== wallet) return;
    if (vaultRestoreChecking === ask) vaultRestoreChecking = false;
    setText(vaultRestoreStatus, '');
    if (line) { releaseHeldStatus(line); refreshComposerCostStatus(); }
    const stakeKnown = plan.parts.some((part) => part.account === 'custody')
      || (rememberedVaultReading?.wallet === wallet && BigInt(rememberedVaultReading.feeDue ?? FV_PROTOCOL_FEE) < FV_PROTOCOL_FEE);
    const hint = plan.parts.some((part) => part.account === 'vault')
      ? joinHintSentences(t('profile.vaultRestoreHint'), stakeKnown ? t('profile.vaultRestoreStakeClause') : '')
      : t('profile.vaultRestoreCustodyHint');
    const proceed = await openActionDialog({
      title: t(plan.parts.some((part) => part.account === 'vault') ? 'profile.vaultRestoreTitle' : 'profile.custodyRestoreTitle'),
      hint: short ? joinHintSentences(hint, short) : hint,
      tone: short ? 'error' : 'muted',
      hintAction: short ? { label: t('wallet.receiveGram'), run: () => showReceiveWalletTonDialog() } : null,
      validateSubmit: async () => {
        const shortNow = shortOf(await loadConnectedTonWalletBalance().catch(() => null));
        return shortNow ? { ok: false, error: shortNow } : { ok: true };
      },
      submitLabel: t('profile.vaultRestoreSubmit', { amount: formatGramNanotonsUp(plan.total) }),
      fields: [],
      summary: () => [
        { label: t('profile.vaultRestoreDebt'), value: `${debt} GRAM` },
        { label: t('profile.vaultRestoreKept'), value: `${kept} GRAM` },
        { label: t('common.balanceNeeded'), value: balanceNeededText(need) },
      ],
    });
    if (!proceed) {
      renderFeeDiscountRows();
      if (line) { releaseHeldStatus(line); refreshComposerCostStatus(); }
      return;
    }
    const locks = globalThis.navigator?.locks;
    if (typeof locks?.request === 'function') {
      const ran = await locks.request(vaultRestoreMarkKey(vaultAddress), { mode: 'exclusive', ifAvailable: true },
        (lock) => (lock ? signVaultRestore(plan, need, wallet, vaultAddress, { line }).then(() => true) : false));
      if (!ran) vaultRestoreSay(t('profile.stakeSending'), line, t('send.unfreezeSending'));
      return;
    }
    await signVaultRestore(plan, need, wallet, vaultAddress, { line });
  } finally {
    if (vaultRestoreChecking === ask) { vaultRestoreChecking = false; refreshComposerCostStatus(); }
  }
}

function vaultRestoreNeed(plan) {
  const classes = (plan?.messages ?? []).map((message) => {
    const bytes = (message?.stateInit ? tonCell.serializeBoc(message.stateInit).length : 0) + Math.ceil(String(message?.payload ?? '').length * 3 / 4);
    return [1, 2, 4, 8, 16, 32].find((sizeClass) => bytes / 1024 <= sizeClass) ?? 32;
  });
  return BigInt(plan?.total ?? 0n) + walletSendFeeReserveNanotons(classes);
}

async function signVaultRestore(plan, need, wallet, vaultAddress, { line = null } = {}) {
  if (vaultRestoreLanding()) { vaultRestoreSay(t('profile.stakeSent'), line, t('send.unfreezeSent')); return; }
  vaultRestoreInFlight = true;
  let marked = false;
  if (vaultRestoreButton) vaultRestoreButton.disabled = true;
  setText(vaultRestoreStatus, t('profile.stakeSending'));
  refreshComposerCostStatus();
  try {
    const signer = requirePlathoWallet();
    if (await vaultAddressFor(signer.address) !== vaultAddress) throw new Error('vault does not belong to the signing wallet');
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    for (const message of plan.messages) {
      let still;
      try {
        still = await withVaultReadLock(() => readAccountFreeze(transport, message.address, criticalChainReadOptions()));
      } catch (error) {
        if (error?.code === 'ACCOUNT_STATE_DISAGREES') still = null;
        else {
          if (!noteTonRpcRateLimit(error)) console.warn('[vault] the account could not be read again before the unfreeze', error);
          vaultRestoreSay(t('profile.vaultRestoreRecheck'), line);
          return;
        }
      }
      if (!still) {
        vaultRestoreSay(t('profile.vaultRestoreAlready'), line);
        queueAthPostTransactionRefresh();
        return;
      }
    }
    vaultRestoreSay(t('profile.stakeSending'), line, t('send.unfreezeSending'));
    await assertWalletGramAtLeast(need, 'unfreeze vault');
    await sendPlathoWalletTransaction(requireSameWallet(signer), { messages: plan.messages }, {
      transport, awaitOutcome: true, requiredBalance: need,
      onSigned: () => { marked = true; noteVaultRestoreSent(signer.address); },
    });
    noteVaultRestoreSent(signer.address);
    vaultRestoreSay(t('profile.stakeSent'), line, t('send.unfreezeSent'));
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (broadcastMayHaveLanded(error)) {
      noteVaultRestoreSent(wallet);
      vaultRestoreSay(t('profile.stakeSent'), line, t('send.unfreezeSent'));
      queueAthPostTransactionRefresh();
      return;
    }
    if (marked) forgetVaultRestoreSent(wallet);
    const said = error?.code === 'PLATHO_WALLET_GRAM_REQUIRED' ? error.message : walletTransferNotRun(error) ? t('wallet.transferNotRun') : null;
    vaultRestoreSay(said ?? t('profile.stakeFailed'), line, said ?? t('send.unfreezeFailed'));
    if (error?.code !== 'PLATHO_WALLET_GRAM_REQUIRED' && !noteTonRpcRateLimit(error)) console.warn('[vault] the unfreeze failed', error);
  } finally {
    vaultRestoreInFlight = false;
    if (vaultRestoreButton) vaultRestoreButton.disabled = false;
    refreshComposerCostStatus();
  }
}

function noteVaultRestoreSent(wallet) {
  if (!wallet || feeVaultState.wallet !== wallet) return;
  const snapshot = feeVaultState.snapshot;
  if (snapshot?.state !== VAULT_FROZEN && !snapshot?.custodyFrozen) return;
  const at = Date.now();
  feeVaultState = { ...feeVaultState, snapshot: { ...snapshot, restoreSentAt: at } };
  try { globalThis.localStorage?.setItem(vaultRestoreMarkKey(feeVaultState.address), String(at)); } catch { }
  refreshComposerCostStatus();
}
function forgetVaultRestoreSent(wallet) {
  if (!wallet || feeVaultState.wallet !== wallet) return;
  const snapshot = feeVaultState.snapshot;
  if (snapshot?.restoreSentAt) {
    const { restoreSentAt: _dropped, ...rest } = snapshot;
    feeVaultState = { ...feeVaultState, snapshot: rest };
  }
  try { globalThis.localStorage?.removeItem(vaultRestoreMarkKey(feeVaultState.address)); } catch { }
  refreshComposerCostStatus();
}

const VAULT_RESTORE_LANDING_MS = (WALLET_EXTERNAL_VALIDITY_S + 90) * 1000;

function inheritVaultMarks(snapshot, prior, { custodyAnswered = false } = {}) {
  let next = snapshot;
  if (next.state === VAULT_LIVE && !next.custodyFrozen && !custodyAnswered && prior?.state === VAULT_LIVE && prior.custodyFrozen) {
    next = { ...next, custodyFrozen: prior.custodyFrozen };
  }
  if ((next.state === VAULT_FROZEN || next.custodyFrozen) && Number(prior?.restoreSentAt) > 0
    && Date.now() - Number(prior.restoreSentAt) < VAULT_RESTORE_LANDING_MS) next = { ...next, restoreSentAt: prior.restoreSentAt };
  return next;
}
const VAULT_RESTORE_MARK = 'platho.vault-restore-sent.v1:';
function vaultRestoreMarkKey(vaultAddress) {
  const digest = nobleSha256(new TextEncoder().encode(String(vaultAddress ?? '')));
  return `${VAULT_RESTORE_MARK}${Array.from(digest.slice(0, 12), (byte) => byte.toString(16).padStart(2, '0')).join('')}`;
}
function vaultRestoreLanding(snapshot = feeVaultState.snapshot, vaultAddress = feeVaultState.address) {
  const fresh = (at) => Number(at) > 0 && Date.now() - Number(at) < VAULT_RESTORE_LANDING_MS;
  if (fresh(snapshot?.restoreSentAt)) return true;
  try { return fresh(globalThis.localStorage?.getItem(vaultRestoreMarkKey(vaultAddress))); } catch { return false; }
}

function feeDiscountFootnotes() {
  if (!vaultSupported()) return [t('profile.stakeFootUnavailable')];
  return [
    t('profile.stakeFootBand', { min: String(FV_STAKE_MIN_ATH), max: groupDecimalText(String(FV_STAKE_MAX_ATH)), threshold: groupDecimalText('1000') }),
    t('profile.stakeFootRent', {
      min: String(FV_STAKE_MIN_ATH),
      rent: formatGramNanotons(FEE_VAULT_RENT_NANOTONS_PER_YEAR + FEE_VAULT_CUSTODY_RENT_NANOTONS_PER_YEAR),
    }),
  ];
}

async function readVaultAtPress(statusNode = null) {
  if (statusNode) setText(statusNode, t('profile.statusChecking'));
  await refreshFeeVaultState({ critical: true });
  const snapshot = feeVaultState.wallet === plathoWallet?.address ? feeVaultState.snapshot : null;
  if (!snapshot || snapshot.state === VAULT_UNKNOWN || snapshot.stale) showAppNotice(t('profile.vaultReadUnanswered'), 6_000);
}

async function openStakeAthDialog() {
  if (!vaultSupported()) {
    setText(feeDiscountStatus, t('profile.feeDiscountAfterUpgrade'));
    return;
  }
  if (!plathoWallet?.address) {
    setText(feeDiscountStatus, t('profile.stakeWalletRequired'));
    return;
  }
  await readVaultAtPress(feeDiscountStatus);
  if (ownVaultFreeze()) return openVaultRestoreDialog();
  const snapshot = feeVaultState.snapshot;
  if (snapshot?.state === VAULT_UNKNOWN || !snapshot || snapshot.stale || snapshot.assumed) {
    setText(feeDiscountStatus, snapshot?.assumed && !snapshot.stale ? t('profile.statusChecking') : t('profile.vaultReadUnanswered'));
    return;
  }
  const quote = vaultGramQuote(quoteStakeGram(snapshot), 'stake');
  const keptLabel = t(snapshot?.state === VAULT_LIVE ? 'profile.vaultTopUpKept' : 'profile.stakeSummarySetup');
  const keptBefore = snapshot?.state !== VAULT_LIVE ? FV_DEPLOY_FUNDING + FV_CUSTODY_TOPUP
    : BigInt(snapshot.balance ?? 0n) < FV_FLOAT_TOPUP_BELOW ? FV_DEPLOY_FUNDING : 0n;

  let typed = 0n;
  const input = document.createElement('input');
  const readTyped = () => {
    const clean = String(input.value ?? '').replace(/[\s ]/g, '');
    if (!/^\d+$/.test(clean)) return null;
    return BigInt(clean);
  };
  const fields = [{
    type: 'custom',
    className: 'action-custom-field buy-ath-inputs',
    render: () => {
      input.type = 'text';
      input.inputMode = 'numeric';
      input.autocomplete = 'off';
      input.id = 'stakeAthAmountInput';
      input.className = 'buy-ath-input';
      input.placeholder = '0';
      input.setAttribute('aria-label', t('profile.stakeAmountLabel'));
      input.addEventListener('input', () => { typed = readTyped() ?? 0n; updateActiveActionSummary(); });
      const wrap = document.createElement('label');
      wrap.className = 'buy-ath-card';
      const span = document.createElement('span');
      span.textContent = 'ATH';
      wrap.append(span, input);
      const box = document.createElement('div');
      box.className = 'buy-ath-pair';
      box.append(wrap);
      return box;
    },
  }];

  const proceed = await openActionDialog({
    title: t('profile.stakeTitle'),
    hint: '',
    submitLabel: t('profile.stakeSubmit'),
    fields,
    footnotes: () => feeDiscountFootnotes(),
    summary: () => {
      const verdict = stakeBandVerdict(typed, { stakedAtoms: snapshot?.staked ?? 0n });
      return [
        { label: t('profile.stakeSummaryStaked'), value: `${groupDecimalText(String(stakedAthOf(snapshot)))} ATH` },
        { label: t('profile.stakeSummaryAfter'), value: `${groupDecimalText(String(verdict.whole ?? 0n))} ATH` },
        { label: t('profile.stakeSummaryDiscount'), value: `${(verdict.percent ?? 0).toFixed(2)}%` },
        { label: t('profile.stakeSummaryFee'), value: `${formatGramNanotonsUp(vaultTakeFor(verdict.feeDue ?? 0n))} GRAM` },
        ...(quote?.gram ? [{ label: t('profile.vaultParkedWithStake'), value: `${formatGramNanotonsUp(FV_STAKE_FORWARD_NANOTONS)} GRAM` }] : []),
        ...vaultGramRows(quote, keptLabel, { keptBefore }),
        { label: t('profile.stakeSummaryBalance'), value: formatAthProfileAmount(connectedWalletAthBalanceAtomic()) },
      ];
    },
    validateSubmit: async () => {
      if (readTyped() === null) return { ok: false, error: t('profile.stakeWholeOnly') };
      const verdict = stakeBandVerdict(typed, { stakedAtoms: snapshot?.staked ?? 0n });
      if (!verdict.ok) {
        if (verdict.reason === 'below-band') {
          return { ok: false, error: t('profile.stakeBelowBand', { min: String(FV_STAKE_MIN_ATH) }) };
        }
        if (verdict.reason === 'above-band') {
          return { ok: false, error: t('profile.stakeAboveBand', { max: groupDecimalText(String(FV_STAKE_MAX_ATH)) }) };
        }
        return { ok: false, error: t('profile.stakeEnterAmount') };
      }
      const have = connectedWalletAthBalanceAtomic();
      if (have !== null && have < verdict.atoms) {
        return { ok: false, error: t('profile.stakeLowAth', { have: formatAthAtomic(have) }) };
      }
      const window = snapshot?.exitWindow;
      if (window?.open) {
        return { ok: false, error: t('profile.stakeExitDebtOpen', { seconds: String(window.secondsLeft) }) };
      }
      return { ok: true };
    },
  });
  if (!proceed || typed <= 0n) return;
  await submitStakeAth(typed);
}

function vaultPlanRefusalText(plan) {
  switch (plan?.reason) {
    case 'exit-debt-open':
      return t('profile.stakeExitDebtOpen', { seconds: String(plan.debtWindow?.secondsLeft ?? 0) });
    case 'unstake-in-flight':
      return t('profile.unstakePending');
    case 'more-than-staked':
      return t('profile.unstakeMoreThanStaked', {
        staked: groupDecimalText(String(stakedAthOf(feeVaultState.snapshot))),
      });
    case 'above-band':
      return t('profile.stakeAboveBand', { max: groupDecimalText(String(FV_STAKE_MAX_ATH)) });
    case 'below-band':
      return t('profile.stakeBelowBand', { min: String(FV_STAKE_MIN_ATH) });
    case 'unjam-too-early':
      return t('profile.stakeExitDebtOpen', { seconds: String(plan.secondsLeft ?? 0) });
    case 'nothing-parked':
    case 'nothing-to-send':
    case 'nothing-stranded':
    case 'dust':
      return t('profile.stakeEnterAmount');
    case 'not-a-whole-number':
      return t('profile.stakeWholeOnly');
    case 'position-unknown':
    case 'unavailable':
    case 'no-vault':
    case 'no-wallet':
      return t('profile.statusChecking');
    case 'vault-frozen':
      return t('profile.vaultFrozenStatus');
    case 'custody-frozen':
      return t('profile.custodyRestore');
    default:
      return t('profile.stakeFailed');
  }
}

async function resolveVaultCustodyWallet(vaultAddress) {
  return recentAthWalletAddress(vaultAddress, async () => {
    const master = await resolveAthMasterProvider();
    const custody = await withVaultReadLock(() => master.getWalletAddress(vaultAddress, {
      address: requireAthMasterAddress(), ...criticalChainReadOptions(),
    }));
    return publicAddrKey(custody);
  });
}

const ATH_WALLET_ADDRESS_FRESH_MS = 60_000;
const recentAthWalletAddresses = new Map();
function recentAthWalletAddress(owner, read) {
  const key = `${requireAthMasterAddress()}|${owner}`;
  const held = recentAthWalletAddresses.get(key);
  if (held && Date.now() - held.at < ATH_WALLET_ADDRESS_FRESH_MS) return held.answer;
  const answer = read();
  recentAthWalletAddresses.set(key, { at: Date.now(), answer });
  answer.catch(() => { if (recentAthWalletAddresses.get(key)?.answer === answer) recentAthWalletAddresses.delete(key); });
  return answer;
}

async function readVaultCustodyBalance(vaultAddress) {
  let custodyWallet = null;
  let custodyBalance = null;
  try {
    custodyWallet = await resolveVaultCustodyWallet(vaultAddress);
    const rows = await withVaultReadLock(() => readAccountStates([custodyWallet],
      { request: createShardStatesRequest({ strict: true, requestOptions: { priority: 'critical', skipIfRateLimited: false, queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS } }) }));
    const row = rows?.get?.(custodyWallet) ?? null;
    custodyBalance = row === null ? 0n : (row.status === 'unknown' ? null : BigInt(row.balance ?? 0n));
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[vault] custody wallet read failed — the stake goes without its top-up', error);
    custodyBalance = null;
  }
  return { custodyWallet, custodyBalance };
}

async function quoteStakeGram(snapshot) {
  const held = stakedAthOf(snapshot);
  const probe = held >= FV_STAKE_MIN_ATH ? 1n : FV_STAKE_MIN_ATH - held;
  if (held + probe > FV_STAKE_MAX_ATH) return null;
  const owner = requirePlathoWalletAddress();
  const athWalletAddress = await loadConnectedAthWalletAddress();
  const vaultAddress = await vaultAddressFor(owner);
  const { custodyWallet, custodyBalance } = await readVaultCustodyBalance(vaultAddress);
  const plan = planStake({ ownerWallet: owner, vaultAddress, athWalletAddress, ath: probe, snapshot, custodyWallet, custodyBalance: custodyBalance ?? (custodyWallet ? 0n : null) });
  if (!plan.ok) return null;
  const priced = await priceVaultStakeForSend(plan);
  const unplacedCustody = !custodyWallet ? FV_CUSTODY_TOPUP : 0n;
  return {
    need: priced.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n) + walletSendFeeReserveNanotons() + unplacedCustody,
    kept: (plan.deploys ? FV_DEPLOY_FUNDING : 0n) + (plan.fundsCustody ? FV_CUSTODY_TOPUP : 0n) + BigInt(priced.ownerTopUp ?? 0n) + unplacedCustody,
  };
}

async function quoteExitGram(plan, vaultAddress) {
  if (!plan?.ok) return null;
  const priced = await priceVaultExitForSend(plan, vaultAddress);
  return {
    need: priced.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n) + walletSendFeeReserveNanotons(),
    kept: BigInt(priced.custodyTopUp ?? 0n),
  };
}

function vaultGramRows(quote, keptLabel, { keptBefore = 0n, intoVault = false } = {}) {
  const gram = quote?.gram ?? null;
  if (gram) {
    return [
      ...(gram.kept > 0n ? [{ label: keptLabel, value: `${formatGramNanotonsUp(gram.kept)} GRAM` }] : []),
      { label: t('common.balanceNeeded'), value: balanceNeededText(gram.need, { intoVault }) },
    ];
  }
  if (quote?.state === 'none') return [];
  const unread = quote?.state === 'failed';
  return [
    ...(keptBefore > 0n ? [{ label: keptLabel, value: `${formatGramNanotonsUp(keptBefore)} GRAM` }] : []),
    { label: t('common.balanceNeeded'), value: t(unread ? 'profile.vaultQuoteUnread' : 'dialog.checking') },
  ];
}

function vaultGramQuote(read, what) {
  const quote = { state: 'reading', gram: null };
  read
    .then((gram) => { quote.gram = gram; quote.state = gram ? 'ready' : 'none'; updateActiveActionSummary(); })
    .catch((error) => {
      quote.state = 'failed';
      updateActiveActionSummary();
      if (!noteTonRpcRateLimit(error)) console.warn(`[vault] ${what} quote failed`, error);
    });
  return quote;
}

function vaultSendErrorSaysWhatToDo(error) {
  return error?.code === 'PLATHO_WALLET_GRAM_REQUIRED' || error?.code === 'ATH_REQUEST_UNPRICED';
}

function groupWriteRefusalText(error, fallbackKey = 'group.controlFailed') {
  if (error?.code === 'PRICES_MOVED') return t('dialog.pricesMoved');
  return vaultSendErrorSaysWhatToDo(error) ? error.message : t(fallbackKey);
}

async function submitStakeAth(ath) {
  if (feeVaultStakeInFlight) return;
  const signer = plathoWallet;
  feeVaultStakeInFlight = true;
  if (feeDiscountButton) feeDiscountButton.disabled = true;
  setText(feeDiscountStatus, t('profile.stakeSending'));
  let owner = null;
  let vaultAddress = null;
  let plan = null;
  try {
    owner = requirePlathoWalletAddress();
    const athWalletAddress = await loadConnectedAthWalletAddress();
    vaultAddress = await vaultAddressFor(owner);
    const { custodyWallet, custodyBalance } = await readVaultCustodyBalance(vaultAddress);
    plan = planStake({
      ownerWallet: owner,
      vaultAddress,
      athWalletAddress,
      ath,
      snapshot: feeVaultState.snapshot,
      queryId: nextQueryId(),
      custodyWallet,
      custodyBalance,
    });
    if (!plan.ok) {
      setText(feeDiscountStatus, vaultPlanRefusalText(plan));
      return;
    }
    plan = await priceVaultStakeForSend(plan);
    const stakeNeed = plan.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n);
    await assertWalletGramAtLeast(stakeNeed + walletSendFeeReserveNanotons(), 'stake ATH');
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    const staked = await sendPlathoWalletTransaction(requireSameWallet(signer), { messages: plan.messages }, { transport, awaitOutcome: true });
    setText(feeDiscountStatus, t('profile.stakeSent'));
    if (plan.deploys) noteFeeVaultDeployed(owner, vaultAddress, null, { unconfirmed: unconfirmedExternalOf(staked) });
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (broadcastMayHaveLanded(error)) {
      setText(feeDiscountStatus, t('profile.stakeSent'));
      if (plan?.deploys && owner && vaultAddress) noteFeeVaultDeployed(owner, vaultAddress, null, { unconfirmed: unconfirmedExternalOf(error) });
      queueAthPostTransactionRefresh();
      return;
    }
    setText(feeDiscountStatus, vaultSendErrorSaysWhatToDo(error)
      ? error.message
      : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('profile.stakeFailed'));
    if (!vaultSendErrorSaysWhatToDo(error) && !noteTonRpcRateLimit(error)) {
      console.warn('[vault] stake failed', error);
    }
  } finally {
    feeVaultStakeInFlight = false;
    if (feeDiscountButton) feeDiscountButton.disabled = false;
  }
}

async function openUnstakeAthDialog() {
  await readVaultAtPress(unstakeAthStatus);
  if (ownVaultFreeze()) return openVaultRestoreDialog();
  const snapshot = feeVaultState.snapshot;
  if (snapshot?.state !== VAULT_LIVE) return;
  if (snapshot.stale || snapshot.assumed) { setText(unstakeAthStatus, t('profile.statusChecking')); return; }
  if ((snapshot.staked ?? 0n) <= 0n && (snapshot.pending ?? 0n) <= 0n) return;
  if ((snapshot.pending ?? 0n) > 0n) {
    const unjam = planUnstakeUnjam({ vaultAddress: feeVaultState.address, snapshot });
    if (!unjam.ok) {
      setText(unstakeAthStatus, unjam.reason === 'unjam-too-early'
        ? t('profile.unstakePending')
        : vaultPlanRefusalText(unjam));
      return;
    }
    const proceedUnjam = await openActionDialog({
      title: t('profile.unstakeTitle'),
      hint: t('profile.unstakeStuckHint'),
      submitLabel: t('profile.unstakeRelease'),
      fields: [],
      summary: () => [
        { label: t('profile.unstakeParked'), value: `${groupDecimalText(String((snapshot.pending ?? 0n) / FV_ATOMIC_PER_ATH))} ATH` },
        { label: t('common.balanceNeeded'), value: balanceNeededText(unjam.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n) + walletSendFeeReserveNanotons(), { intoVault: true }) },
      ],
    });
    if (!proceedUnjam) return;
    const signer = plathoWallet;
    setText(unstakeAthStatus, t('profile.stakeSending'));
    try {
      const need = unjam.messages.reduce((sum, message) => sum + BigInt(message.amount), 0n);
      await assertWalletGramAtLeast(need + walletSendFeeReserveNanotons(), 'release stake');
      const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
      await sendPlathoWalletTransaction(requireSameWallet(signer), { messages: unjam.messages }, { transport, awaitOutcome: true });
      setText(unstakeAthStatus, t('profile.stakeSent'));
      queueAthPostTransactionRefresh();
    } catch (error) {
      if (broadcastMayHaveLanded(error)) { setText(unstakeAthStatus, t('profile.stakeSent')); queueAthPostTransactionRefresh(); return; }
      setText(unstakeAthStatus, error?.code === 'PLATHO_WALLET_GRAM_REQUIRED' ? error.message : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('profile.stakeFailed'));
      if (error?.code !== 'PLATHO_WALLET_GRAM_REQUIRED' && !noteTonRpcRateLimit(error)) {
        console.warn('[vault] unstake release failed', error);
      }
    }
    return;
  }
  const quote = vaultGramQuote(quoteExitGram(planUnstake({ vaultAddress: feeVaultState.address, ath: 1n, snapshot }), feeVaultState.address), 'withdrawal');
  let typed = 0n;
  const input = document.createElement('input');
  const readTyped = () => {
    const clean = String(input.value ?? '').replace(/[\s ]/g, '');
    return /^\d+$/.test(clean) ? BigInt(clean) : null;
  };
  const proceed = await openActionDialog({
    title: t('profile.unstakeTitle'),
    hint: '',
    submitLabel: t('profile.unstakeSubmit'),
    fields: [{
      type: 'custom',
      className: 'action-custom-field buy-ath-inputs',
      render: () => {
        input.type = 'text';
        input.inputMode = 'numeric';
        input.autocomplete = 'off';
        input.id = 'unstakeAthAmountInput';
        input.className = 'buy-ath-input';
        input.placeholder = '0';
        input.setAttribute('aria-label', t('profile.unstakeAmountLabel'));
        input.addEventListener('input', () => { typed = readTyped() ?? 0n; updateActiveActionSummary(); });
        const wrap = document.createElement('label');
        wrap.className = 'buy-ath-card';
        const span = document.createElement('span');
        span.textContent = 'ATH';
        wrap.append(span, input);
        const box = document.createElement('div');
        box.className = 'buy-ath-pair';
        box.append(wrap);
        return box;
      },
    }],
    summary: () => {
      const plan = planUnstake({ vaultAddress: feeVaultState.address, ath: typed, snapshot });
      const remaining = plan.ok ? plan.remaining : snapshot.staked;
      return [
        { label: t('profile.stakeSummaryStaked'), value: `${groupDecimalText(String(stakedAthOf(snapshot)))} ATH` },
        { label: t('profile.unstakeSummaryRemaining'), value: `${groupDecimalText(String(remaining / FV_ATOMIC_PER_ATH))} ATH` },
        { label: t('profile.stakeSummaryFee'), value: `${formatGramNanotonsUp(vaultTakeFor(plan.ok ? plan.remainingFeeDue : snapshot.feeDue))} GRAM` },
        ...vaultGramRows(quote, t('profile.vaultTopUpKept'), { intoVault: true }),
      ];
    },
    validateSubmit: async () => {
      const plan = planUnstake({ vaultAddress: feeVaultState.address, ath: typed, snapshot });
      if (plan.ok) return { ok: true };
      if (plan.reason === 'more-than-staked') {
        return { ok: false, error: t('profile.unstakeMoreThanStaked', { staked: groupDecimalText(String(stakedAthOf(snapshot))) }) };
      }
      if (plan.reason === 'not-a-whole-number') return { ok: false, error: t('profile.stakeWholeOnly') };
      return { ok: false, error: t('profile.stakeEnterAmount') };
    },
  });
  if (!proceed || typed <= 0n) return;
  await submitUnstakeAth(typed);
}

async function submitUnstakeAth(ath) {
  if (feeVaultStakeInFlight) return;
  feeVaultStakeInFlight = true;
  if (unstakeAthButton) unstakeAthButton.disabled = true;
  setText(unstakeAthStatus, t('profile.stakeSending'));
  const signer = plathoWallet;
  try {
    const unpriced = planUnstake({ vaultAddress: feeVaultState.address, ath, snapshot: feeVaultState.snapshot });
    if (!unpriced.ok) {
      setText(unstakeAthStatus, vaultPlanRefusalText(unpriced));
      return;
    }
    const plan = await priceVaultExitForSend(unpriced, feeVaultState.address);
    await broadcastOwnVaultExit(plan.messages, unpriced.remainingFeeDue, 'withdraw stake', { signer: requireSameWallet(signer) });
    setText(unstakeAthStatus, t('profile.stakeSent'));
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (broadcastMayHaveLanded(error)) { setText(unstakeAthStatus, t('profile.stakeSent')); queueAthPostTransactionRefresh(); return; }
    setText(unstakeAthStatus, vaultSendErrorSaysWhatToDo(error)
      ? error.message
      : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('profile.stakeFailed'));
    if (!vaultSendErrorSaysWhatToDo(error) && !noteTonRpcRateLimit(error)) {
      console.warn('[vault] unstake failed', error);
    }
  } finally {
    feeVaultStakeInFlight = false;
    if (unstakeAthButton) unstakeAthButton.disabled = false;
  }
}

async function openRecoverAthDialog() {
  await readVaultAtPress(recoverAthStatus);
  if (ownVaultFreeze()) return openVaultRestoreDialog();
  const snapshot = feeVaultState.snapshot;
  const plan = planRecovery({ vaultAddress: feeVaultState.address, snapshot, realAtoms: feeVaultState.realAtoms ?? null });
  if (!plan.ok) {
    setText(recoverAthStatus, vaultPlanRefusalText(plan));
    renderFeeDiscountRows();
    return;
  }
  const strandedAth = groupDecimalText(String(plan.stranded / FV_ATOMIC_PER_ATH));
  const drainAth = groupDecimalText(String(plan.drain / FV_ATOMIC_PER_ATH));
  const quote = vaultGramQuote(quoteExitGram(plan, feeVaultState.address), 'recovery');
  const proceed = await openActionDialog({
    title: t('profile.recoverTitle'),
    hint: t('profile.recoverHint', { stranded: strandedAth, drain: drainAth }),
    submitLabel: t('profile.recoverSubmit'),
    fields: [],
    summary: () => [
      { label: t('profile.recoverSummaryStranded'), value: `${strandedAth} ATH` },
      { label: t('profile.recoverSummaryDrain'), value: `${drainAth} ATH` },
      ...vaultGramRows(quote, t('profile.vaultTopUpKept'), { intoVault: true }),
    ],
  });
  if (!proceed) return;
  await submitRecoverAth(plan);
}

async function submitRecoverAth(plan) {
  if (feeVaultStakeInFlight) return;
  feeVaultStakeInFlight = true;
  if (recoverAthButton) recoverAthButton.disabled = true;
  setText(recoverAthStatus, t('profile.stakeSending'));
  const signer = plathoWallet;
  try {
    const owner = requirePlathoWalletAddress();
    const vaultAddress = await vaultAddressFor(owner);
    if (vaultAddress !== feeVaultState.address) throw new Error('vault does not belong to the signing wallet');
    const priced = await priceVaultExitForSend(plan, vaultAddress);
    await broadcastOwnVaultExit(priced.messages, FV_PROTOCOL_FEE, 'recover ATH', { signer: requireSameWallet(signer) });
    setText(recoverAthStatus, t('profile.stakeSent'));
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (broadcastMayHaveLanded(error)) { setText(recoverAthStatus, t('profile.stakeSent')); queueAthPostTransactionRefresh(); return; }
    setText(recoverAthStatus, vaultSendErrorSaysWhatToDo(error) ? error.message : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('profile.stakeFailed'));
    if (!vaultSendErrorSaysWhatToDo(error) && !noteTonRpcRateLimit(error)) {
      console.warn('[vault] recovery failed', error);
    }
  } finally {
    feeVaultStakeInFlight = false;
    if (recoverAthButton) recoverAthButton.disabled = false;
  }
}

function doorPress(open, { money = false } = {}) {
  return () => {
    if (doorPressHeld) return;
    if (money && offeredWaitingBuild()) return;
    const mine = {};
    doorPressHeld = mine;
    Promise.resolve().then(() => open()).catch((error) => console.error(error)).finally(() => { if (doorPressHeld === mine) doorPressHeld = null; });
  };
}
function offeredWaitingBuild() {
  if (!pendingServiceWorkerAppShellReload) return false;
  offerAppUpdate({ asked: true });
  return true;
}
feeDiscountButton?.addEventListener('click', doorPress(openStakeAthDialog, { money: true }));
recoverAthButton?.addEventListener('click', doorPress(openRecoverAthDialog, { money: true }));
vaultFloatButton?.addEventListener('click', doorPress(openVaultFloatDialog, { money: true }));
vaultRestoreButton?.addEventListener('click', doorPress(openVaultRestoreDialog, { money: true }));
unstakeAthButton?.addEventListener('click', doorPress(openUnstakeAthDialog, { money: true }));

function normalizeUsernameInput(input) {
  const raw = String(input ?? '').trim().toLowerCase();
  const username = raw.endsWith('.ath') ? raw.slice(0, -4) : raw;
  if (!/^[a-z0-9_-]{4,16}$/.test(username)) {
    throw new Error(t('username.nameRules'));
  }
  return username;
}

function localUsernameMintPriceAtomic(username) {
  const tier = plathoUsernameTier(username);
  if (tier === PLATHO_USERNAME_TIERS.EPIC) return USERNAME_PRICE_4_CHARS_ATOMIC;
  if (tier === PLATHO_USERNAME_TIERS.RARE) return USERNAME_PRICE_5_CHARS_ATOMIC;
  if (tier === PLATHO_USERNAME_TIERS.COMMON) return USERNAME_PRICE_6_PLUS_CHARS_ATOMIC;
  return null;
}

function usernameMintPendingMatches(record, username, owner) {
  if (!record) return false;
  const normalized = normalizeUsernameInput(username);
  const ownerAddress = requireBasechainAddress(owner, 'Connected wallet');
  return record.username === normalized
    && record.expiresAt > Date.now()
    && sameWalletAddress(record.owner, ownerAddress);
}

function pendingUsernameMintRecord(username, owner) {
  const record = globalThis.plathoPendingUsernameMint;
  if (usernameMintPendingMatches(record, username, owner)) return record;
  if (record?.expiresAt && record.expiresAt <= Date.now()) {
    globalThis.plathoPendingUsernameMint = null;
  }
  return null;
}

function rememberPendingUsernameMint(username, owner, submission = {}) {
  const normalized = normalizeUsernameInput(username);
  const now = Date.now();
  globalThis.plathoPendingUsernameMint = {
    username: normalized,
    label: `${normalized}.ath`,
    owner: requireBasechainAddress(owner, 'Connected wallet'),
    clientNonce: submission?.clientNonce === undefined || submission?.clientNonce === null
      ? null
      : String(submission.clientNonce),
    at: now,
    expiresAt: now + USERNAME_MINT_LOCAL_PENDING_MS,
  };
  return globalThis.plathoPendingUsernameMint;
}

function clearPendingUsernameMint(username, owner) {
  if (usernameMintPendingMatches(globalThis.plathoPendingUsernameMint, username, owner)) {
    globalThis.plathoPendingUsernameMint = null;
  }
}

function assertNoPendingUsernameMintRetry(username, owner) {
  if (pendingUsernameMintRecord(username, owner)) {
    throw new Error('Username mint is still finalizing; sync ownership before retrying');
  }
}

function usernameMintPricePreview(input) {
  try {
    const username = normalizeUsernameInput(input);
    const price = localUsernameMintPriceAtomic(username);
    return price === null
      ? t('username.priceRangeBurn')
      : t('common.athPriceBurn', { price: formatAthAtomic(price) });
  } catch {
    return t('username.priceRangeBurn');
  }
}

function usernameMintStatusText(error) {
  const message = shortUiErrorText(error, 'username blocked');
  if (error?.code === 'PLATHO_ATH_REQUIRED' || error?.code === 'PLATHO_WALLET_GRAM_REQUIRED') return message;
  if (/activate platho account|usernameregistry rejected/i.test(message)) {
    return message;
  }
  if (/verification unavailable/i.test(message)) return t('username.rpcVerificationUnavailable');
  if (/provider is not configured|username.*provider|ton rpc|sendboc/i.test(message)) return message;
  return t('username.blockedWithDetail', { message });
}

