async function requestWalletTonTransferDetails() {
  const seenRecipient = { value: null };
  const wallet = requirePlathoWallet();
  const fromAddress = walletAddressForCopy(wallet);
  const result = await openActionDialog({
    title: t('wallet.sendGram'),
    hint: t('wallet.sendGramHint'),
    submitLabel: t('wallet.sendGram'),
    fields: [
      {
        id: 'recipient',
        label: t('dialog.recipient'),
        type: 'text',
        placeholder: t('dialog.recipientPlaceholder'),
        autocomplete: 'off',
        spellcheck: false,
      },
      {
        id: 'amount',
        label: t('common.amount'),
        type: 'text',
        placeholder: '0.1',
        inputMode: 'decimal',
        autocomplete: 'off',
      },
      { id: 'comment', label: t('wallet.commentOptional'), type: 'text', autocomplete: 'off', required: false },
      ...spendPasswordFields(),
    ],
    formAutocomplete: 'on',
    summary: (values) => {
      const lines = [
        { label: t('wallet.from'), value: shortAddress(fromAddress) },
        { label: t('wallet.source'), value: t('wallet.localWalletNotVault') },
      ];
      const recipientText = values.recipient?.trim();
      if (recipientText) {
        const parsed = parseRecipientIdentity(recipientText);
        if (!parsed.ok) {
          lines.push({ label: t('wallet.recipient'), value: t('username.recipientInvalid') });
        } else if (parsed.identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
          try {
            const recipient = requireBasechainAddress(parsed.identity.value, 'Recipient');
            lines.push({
              label: t('wallet.recipient'),
              value: shortAddress(formatTonUserFriendlyAddress(recipient, {
                testOnly: Number(wallet.networkGlobalId) === PLATHO_WALLET_NETWORK_GLOBAL_IDS.TESTNET,
              })),
            });
          } catch {
            lines.push({ label: t('wallet.recipient'), value: t('wallet.recipientNotBasechain') });
          }
        } else {
          lines.push({ label: t('wallet.recipient'), value: parsed.identity.label });
        }
      }
      if (values.amount?.trim()) {
        try {
          const amountNanotons = parseTonAmountNanotons(values.amount);
          lines.push({ label: t('common.amount'), value: t('wallet.gramAmount', { amount: formatDecimalAmount(amountNanotons, 9, 9) }) });
          const commentBytes = new TextEncoder().encode(String(values.comment ?? '').trim()).length;
          lines.push({ label: t('common.costLabel'), value: `${formatGramNanotonsUp(amountNanotons + walletTransferFeeFinalCost({ prices: composerNetworkPrices(), commentBytes }))} GRAM` });
          lines.push({ label: t('common.balanceNeeded'), value: balanceNeededText(amountNanotons + walletSendFeeReserveNanotons()) });
        } catch (error) {
          lines.push({ label: t('common.amount'), value: error.message });
        }
      }
      return lines;
    },
    validateSubmit: async (submitted) => {
      const entered = String(submitted?.recipient ?? '').trim();
      let resolved = null;
      try {
        resolved = await resolveTransferRecipient(entered);
      } catch (error) {
        return { ok: false, error: transferRecipientError(error, entered) };
      }
      const refusal = await transferRecipientRefusal(resolved, entered, seenRecipient);
      if (refusal) return { ok: false, error: refusal };
      let amount = null;
      try {
        amount = parseTonAmountNanotons(submitted?.amount);
      } catch (error) {
        return { ok: false, error: error?.message ?? String(error) };
      }
      const comment = String(submitted?.comment ?? '').trim();
      const tooLong = walletCommentRefusal(comment);
      if (tooLong) return { ok: false, error: tooLong };
      const passwordRefusal = await spendPasswordRefusal(submitted);
      if (passwordRefusal) return { ok: false, error: passwordRefusal };
      return { ok: true, result: { recipient: resolved.wallet, amount: amount.toString(), comment } };
    },
  });
  if (!result) return null;
  const recipient = requireBasechainAddress(result.recipient, 'Recipient');
  const amount = BigInt(result.amount);
  return { recipient, amount, comment: result.comment ?? '' };
}

function forgetUnlandedBroadcast(error) {
  if (error && typeof error === 'object' && error.builtBoc && !broadcastMayHaveLanded(error)) {
    try { delete error.builtBoc; } catch { }
  }
  return error;
}

function broadcastMayHaveLanded(error) {
  if (!(error && typeof error === 'object' && typeof error.builtBoc === 'string' && error.builtBoc)) return false;
  if (error.partialSend) return true;
  if (error.broadcastVerdict === 'rejected' && error.tonRpcPriorDeliveryAmbiguous !== true) return false;
  if ((error.broadcastVerdict === 'refused' || String(error.code ?? '') === 'QUEUE_TIMEOUT') && error.tonRpcPriorDeliveryAmbiguous !== true) return false;
  if (error.walletExternalExpired === true && error.seqnoReadFailed !== true) return false;
  return true;
}

const TRANSFER_BOUNCE_ACCOUNT_STATUSES = new Set(['active', 'frozen']);
const TRANSFER_NO_BOUNCE_ACCOUNT_STATUSES = new Set(['uninit', 'uninitialized', 'nonexist', 'nonexistent', 'empty', 'none']);

async function transferRecipientAccountStatus(address) {
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (typeof transport?.getAccountState !== 'function') throw new Error('TON RPC account state is required to send GRAM');
  const account = await transport.getAccountState({ address }, { skipIfRateLimited: false, priority: 'critical' });
  const status = String(
    account?.state ?? account?.status ?? account?.account_state
    ?? account?.result?.state ?? account?.result?.status ?? account?.result?.account_state ?? '',
  ).trim().toLowerCase();
  if (TRANSFER_BOUNCE_ACCOUNT_STATUSES.has(status) || TRANSFER_NO_BOUNCE_ACCOUNT_STATUSES.has(status)) return status;
  throw new Error(`recipient account status could not be read (${status || 'empty answer'})`);
}

function transferBounceForStatus(status) {
  return TRANSFER_BOUNCE_ACCOUNT_STATUSES.has(String(status ?? '').trim().toLowerCase());
}

function walletTransferNotRun(error) {
  if (error?.code === 'PLATHO_WALLET_EXTERNAL_REPLACED') return true;
  return error?.walletExternalExpired === true && error?.seqnoReadFailed !== true && error?.builtBoc === undefined;
}

async function submitWalletTonTransfer(hold = null) {
  const details = await requestWalletTonTransferDetails();
  if (!details) return null;
  hold?.();
  const signer = requirePlathoWallet();
  const owner = signer.address;
  const ownSession = () => sameWalletAddress(plathoWallet?.address, owner);
  setVaultStatus('reading the recipient account');
  const recipientStatus = await transferRecipientAccountStatus(details.recipient);
  const bounce = transferBounceForStatus(recipientStatus);
  setVaultStatus('sending GRAM from wallet');
  const payload = details.comment ? serializeBoc(buildTextCommentBody(details.comment)) : null;
  const need = details.amount + walletSendFeeReserveNanotons(payload ? [walletSendSizeClassForPayloadBytes(payload.length)] : []);
  const message = {
    address: details.recipient,
    amount: details.amount.toString(),
    ...(payload ? { payload: tonCell.bytesToBase64(payload) } : {}),
    bounce,
  };
  const transaction = createWalletTransaction(message);
  await assertWalletGramAtLeast(need, 'wallet transfer');
  let result = null;
  setText(sendWalletTonStatus, t('wallet.gramTransferSending'));
  if (ownSession()) flashWalletIdentityStatus(t('wallet.gramTransferSending'), 30_000);
  try {
    result = await sendPlathoWalletTransaction(requireSameWallet(signer), transaction, {
      requiredBalance: need, awaitOutcome: true,
    });
  } catch (error) {
    if (!broadcastMayHaveLanded(error)) throw error;
    watchWalletTonTransfer(owner, { seqno: error.builtSeqno, validUntil: error.builtValidUntil, boc: error.builtBoc }, bounce);
    if (!ownSession()) return null;
    globalThis.plathoLastWalletTonTransfer = { details, recipientStatus, message, transaction, result: null, ambiguous: true, boc: error.builtBoc, seqno: error.builtSeqno ?? null };
    setText(sendWalletTonStatus, '');
    flashWalletIdentityStatus(t(bounce ? 'wallet.gramTransferSubmitted' : 'wallet.gramTransferRecipientNew'));
    setVaultStatus('wallet GRAM transfer submitted (unconfirmed)');
    queueVaultPostTransactionRefresh();
    return null;
  }
  const ran = result?.outcome === 'consumed';
  if (!ran) watchWalletTonTransfer(owner, { seqno: result?.pendingSeqno, validUntil: result?.pendingValidUntil, boc: result?.pendingBoc }, bounce);
  if (!ownSession()) return result;
  globalThis.plathoLastWalletTonTransfer = { details, recipientStatus, message, transaction, result };
  setText(sendWalletTonStatus, '');
  flashWalletIdentityStatus(t(ran
    ? (bounce ? 'wallet.gramTransferSent' : 'wallet.gramTransferSentRecipientNew')
    : (bounce ? 'wallet.gramTransferSubmitted' : 'wallet.gramTransferRecipientNew')));
  setVaultStatus('wallet GRAM transfer submitted');
  queueVaultPostTransactionRefresh();
  return result;
}

const WALLET_TON_TRANSFER_WATCH_MS = 7 * 60_000;
const WALLET_TON_TRANSFER_WATCH_STEPS_MS = Object.freeze([15_000, 30_000, 60_000]);
function watchWalletTonTransfer(address, { seqno, validUntil, boc }, bounce) {
  const target = Number(seqno);
  if (typeof address !== 'string' || !address || !boc || !Number.isInteger(target)) return;
  const startedAt = Date.now();
  let looks = 0;
  const live = watchWalletTonTransfer.live ?? (watchWalletTonTransfer.live = new Set());
  const token = {};
  live.add(token);
  const ended = () => { live.delete(token); };
  const mine = () => sameWalletAddress(plathoWallet?.address, address);
  const again = () => {
    const wait = WALLET_TON_TRANSFER_WATCH_STEPS_MS[Math.min(looks, WALLET_TON_TRANSFER_WATCH_STEPS_MS.length - 1)];
    if (Date.now() + wait - startedAt > WALLET_TON_TRANSFER_WATCH_MS) return false;
    setTimeout(look, wait);
    return true;
  };
  const look = async () => {
    if (plathoWallet && !mine()) { ended(); return; }
    let fate = null;
    if (plathoWallet) {
      const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
      try {
        fate = await walletExternalOutcomeNow({ address }, transport, { seqno: target, validUntil, boc }, { quick: true, priority: looks === 0 ? 'critical' : 'background' });
      } catch { fate = null; }
      looks += 1;
    }
    if (plathoWallet && !mine()) { ended(); return; }
    if (plathoWallet && fate === 'consumed') {
      ended();
      flashWalletIdentityStatus(t(bounce ? 'wallet.gramTransferSent' : 'wallet.gramTransferSentRecipientNew'));
      queueVaultPostTransactionRefresh();
      return;
    }
    if (plathoWallet && (fate === 'replaced' || fate === 'expired')) {
      ended();
      flashWalletIdentityStatus(t('wallet.transferNotRun'), 8_000);
      queueVaultPostTransactionRefresh();
      return;
    }
    if (again()) return;
    ended();
    if (plathoWallet) flashWalletIdentityStatus(t('wallet.transferUnconfirmed'), 8_000);
  };
  if (!again()) ended();
}

async function requestWalletSeedImport() {
  let value = '';
  let hint = t('wallet.importWalletHint');
  let tone = 'muted';
  for (;;) {
    const result = await openActionDialog({
      title: t('wallet.importWallet'),
      hint,
      tone,
      submitLabel: t('wallet.importWallet'),
      fields: [{
        id: 'recoveryPhrase',
        label: t('wallet.recoveryPhrase'),
        type: 'textarea',
        placeholder: t('wallet.paste24Words'),
        autocomplete: 'off',
        secret: true,
        value,
      }],
      summary: [t('wallet.importWalletSummary')],
    });
    const typed = String(result?.recoveryPhrase ?? '');
    if (!result || !typed.trim()) return null;
    const words = recoveryWordsAsWritten(typed);
    const list = requestWalletSeedImport.words ?? (requestWalletSeedImport.words = new Set(TON_MNEMONIC_WORDLIST));
    value = typed;
    tone = 'error';
    if (words.length !== 24) { hint = t('wallet.recoveryPhraseWordCount', { count: words.length }); continue; }
    const places = (test) => words.map((word, index) => (test(word) ? index + 1 : 0)).filter(Boolean);
    const foreign = places((word) => /[^a-z]/.test(word) && /\p{L}/u.test(word.replace(/[a-z]/g, '')));
    if (foreign.length > 0) { hint = t('wallet.recoveryWordsNotLatin', { positions: foreign.slice(0, 6).join(', ') }); continue; }
    const unknown = places((word) => !list.has(word));
    if (unknown.length > 0) { hint = t('wallet.unknownRecoveryWords', { positions: unknown.slice(0, 6).join(', ') }); continue; }
    let valid = false;
    try { valid = await validateTonMnemonic(words); } catch { valid = false; }
    if (!valid) { hint = t('wallet.recoveryPhraseNotValid'); continue; }
    return words.join(' ');
  }
}
function recoveryWordsAsWritten(text) {
  const numbered = [...String(text ?? '').normalize('NFKC').replace(/\p{Cf}/gu, '').toLowerCase().matchAll(/(?:^|[\s,;])(\d{1,2})\s*[.):-]\s*([a-z]+)/g)];
  const order = numbered.map((match) => Number(match[1]));
  if (numbered.length === 24 && new Set(order).size === 24 && order.every((n) => n >= 1 && n <= 24) && order.some((n, index) => n !== index + 1)) {
    return [...numbered].sort((a, b) => Number(a[1]) - Number(b[1])).map((match) => match[2]);
  }
  return String(text ?? '').normalize('NFKC').replace(/[\u200B-\u200D\u2060\uFEFF\u00AD]/g, '').toLowerCase()
    .replace(/(^|\s)\d{1,2}\s*[.):\-]/g, ' ')
    .split(/[\s,;\u3001\uFF0C]+/).map((word) => word.trim()).filter(Boolean);
}

