async function confirmWalletReplacement(actionLabel = t('wallet.replaceThisWallet'), { incoming = null, incomingWallet = null } = {}) {
  if (!plathoWallet && !hasStoredPlathoWalletRecord()) return true;
  const listed = keyringRecords(readDeviceKeyring());
  const alreadyHere = (incoming && listed.some((one) => sameWalletRecords(one, incoming)))
    || (incomingWallet && listed.some((one) => one.address && sameWalletAddress(one.address, incomingWallet.address)));
  if (listed.length >= DEVICE_WALLETS_MAX && !alreadyHere) {
    showAppNotice(t('wallet.deviceWalletsFull', { count: DEVICE_WALLETS_MAX }), 12_000);
    return false;
  }
  const livesInTelegram = walletHomeState() === 'telegram';
  const storedRecord = readEncryptedPlathoWalletRecord();
  const legacyHere = !storedRecord && Boolean(readLegacyPlaintextPlathoWalletRecord());
  const sameWalletOlderFile = Boolean(incoming && storedRecord) && incoming.ciphertext !== storedRecord.ciphertext && sameWalletRecords(incoming, storedRecord);
  const identical = Boolean(incoming && storedRecord) && incoming.ciphertext === storedRecord.ciphertext;
  const sameWalletWords = Boolean(incomingWallet) && sameWalletAddress(incomingWallet.address, plathoWallet?.address ?? storedRecord?.address ?? '');
  const effect = legacyHere ? 'wallet.legacyWalletNotKept'
    : identical ? 'wallet.sameWalletNothingChanges'
    : sameWalletOlderFile ? 'wallet.sameWalletTakesFilePassword'
    : sameWalletWords ? 'wallet.sameWalletWordsNewPassword'
    : livesInTelegram ? 'wallet.localReplacedTelegramStays' : 'wallet.localWalletReplacedKept';
  const lead = legacyHere ? 'wallet.replaceLegacyHint'
    : identical ? 'wallet.replaceIdenticalHint'
    : (sameWalletOlderFile || sameWalletWords) ? 'wallet.replaceSameWalletHint' : 'wallet.replaceLocalWalletHint';
  const result = await openActionDialog({
    title: t('wallet.replaceLocalWalletTitle'),
    hint: t(lead),
    tone: 'muted',
    submitLabel: actionLabel,
    fields: [],
    summary: [
      { label: t('wallet.currentWallet'), value: plathoWallet ? shortAddress(walletAddressForCopy(plathoWallet)) : storedWalletShortLabel() },
      { label: t('wallet.storedOn'), value: t(livesInTelegram ? 'wallet.thisDeviceAndTelegram' : 'wallet.thisDeviceOnly') },
      { label: t('wallet.effect'), value: t(effect) },
    ],
  });
  return Boolean(result);
}

async function confirmClearLocalData() {
  const inBot = inTelegramBot();
  const answered = inBot && hasStoredPlathoWalletRecord() ? await Promise.race([syncWalletsWithTelegram(), delay(3_000).then(() => null)]).catch(() => null) : null;
  const state = readDeviceKeyring();
  const safe = (record) => Boolean(answered) && Boolean(record) && (sameSeal(record, telegramSealOf(record) ?? {}) || untaggedCopiesOf(record).length > 0);
  const silent = inBot && hasStoredPlathoWalletRecord() && !answered;
  const deviceOnly = Boolean(answered) && Boolean(state.active) && walletKeptInTelegram(state.active) === false;
  const there = state.active ? telegramSealOf(state.active) : null;
  const behind = Boolean(answered) && Boolean(there) && supersedes(state.active, counted(there));
  const keptHere = state.others.filter((entry) => !safe(entry.record)).length;
  const result = await openActionDialog({
    title: t('profile.clearLocalDataTitle'),
    hint: joinHintSentences(t(inBot ? 'profile.clearLocalDataHintTelegram' : 'profile.clearLocalDataHint'),
      silent ? t('profile.clearLocalDataTelegramSilent') : '',
      deviceOnly ? t('profile.clearLocalDataDeviceWallet') : '',
      behind ? t('profile.clearLocalDataCopyOwed') : '',
      keptHere > 0 ? t('profile.clearLocalDataKeptWallets', { count: keptHere }) : ''),
    tone: 'error',
    submitLabel: t('profile.clearLocalData'),
    dismissOnBackdrop: false,
    fields: [{
      id: 'clearLocalDataConfirmText',
      name: 'confirmText',
      label: t('profile.clearConfirmLabel', { word: 'CLEAR' }),
      type: 'text',
      placeholder: 'CLEAR',
      autocomplete: 'off',
      autocapitalize: 'characters',
      spellcheck: false,
    }],
    summary: [
      { label: t('profile.scope'), value: t('profile.scopeThisDevice') },
      { label: t('profile.deletes'), value: t('profile.clearDeletesList') },
      { label: t('profile.keeps'), value: t('profile.clearKeepsList') },
    ],
  });
  return String(result?.confirmText ?? '').trim() === 'CLEAR';
}

function spendPasswordFields() {
  const wallet = plathoWallet;
  return walletPasswordFieldSpecs(wallet ? { passwordManagerUsername: wallet.address, passwordManagerNetworkGlobalId: wallet.networkGlobalId } : {})
    .map((field) => (field.id === 'walletPassword' ? { ...field, label: t('wallet.spendPasswordLabel') }
      : { ...field, name: 'walletPasswordManagerUsername' }));
}
async function spendPasswordRefusal(values) {
  const wallet = plathoWallet;
  const record = readEncryptedPlathoWalletRecord();
  if (!wallet || !record) return t('wallet.spendPasswordUnavailable');
  const password = String(values?.walletPassword ?? '');
  if (!password) return t('wallet.spendPasswordWrong');
  let payload = null;
  try { payload = await withWorkInHand(() => openPlathoWalletRecordPayload(record, password)); } catch { payload = null; }
  const words = (text) => String(text ?? '').trim().toLowerCase().split(/\s+/).join(' ');
  return payload && wallet.seedText && words(payload.recoveryPhrase) === words(wallet.seedText) ? '' : t('wallet.spendPasswordWrong');
}

async function confirmWalletPasswordForExport(wallet) {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) return true;
  const unlocked = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.showRecoveryPhrase'),
    hint: t('wallet.showRecoveryPhraseHint'),
    submitLabel: t('wallet.showRecoveryPhrase'),
  });
  if (!unlocked) return false;
  if (!sameWalletAddress(unlocked.address, wallet.address)) {
    throw new Error('Unlocked wallet does not match current wallet');
  }
  return true;
}

async function exportEncryptedWalletKeyFile(alreadyUnlocked = null) {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) throw new Error('No encrypted wallet key is stored on this device');
  const proven = alreadyUnlocked && record.address && sameWalletAddress(record.address, alreadyUnlocked.address) ? alreadyUnlocked : null;
  const unlocked = proven ?? await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.exportWalletKey'),
    hint: t('wallet.exportWalletKeyHint'),
    submitLabel: t('wallet.exportWalletKey'),
  });
  if (!unlocked) return false;
  return downloadEncryptedWalletKeyBackup(record, unlocked);
}

async function activateImportedEncryptedWalletRecord(wallet, record, { toncenterApiKey = null, switched = false } = {}) {
  prepareWalletScopedRuntimeForWallet(wallet, switched ? 'wallet switched' : 'wallet key imported');
  try {
    await withWorkInHand(() => placeOpenedWallet(record, wallet, { asNewest: !switched }));
  } catch (error) {
    try { lockPlathoWallet(); } catch (lockError) { console.warn('[wallet] the refused wallet could not be locked away', lockError); }
    throw error;
  }
  walletFlowOnce.release?.();
  if (toncenterApiKey) applyToncenterApiKey(toncenterApiKey);
  plathoWallet = wallet;
  if (!switched) markWalletKeyBackupDone(wallet.address);
  localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet.address);
  markWalletUnlocked();
  refreshMessagingControls();
  await bootCrypto();
  queueVaultRefreshAfterWalletChange();
  refreshMessagingControls();
  renderWalletIdentity(t(switched ? 'wallet.walletSwitched' : 'wallet.walletKeyImported'));
  return true;
}

async function importEncryptedWalletKeyFile(file) {
  if (!(await walletDoorClearOfTelegramCloud())) return false;
  const parsed = await readJsonFile(file);
  const record = encryptedWalletRecordFromBackup(parsed);
  const wallet = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.importWalletKey'),
    hint: t('wallet.importWalletKeyHint'),
    submitLabel: t('wallet.importWalletKey'),
  });
  if (!wallet) return false;
  let restoredApiKey = null;
  if (parsed?.kind === PLATHO_WALLET_KEY_BACKUP_KIND) {
    if (parsed.toncenterApiKeyEnc) {
      try { restoredApiKey = await decryptToncenterApiKeyFromBackup(parsed.toncenterApiKeyEnc, wallet); }
      catch (error) { console.error(error); restoredApiKey = null; }
    } else if (typeof parsed.toncenterApiKey === 'string' && parsed.toncenterApiKey.trim()) {
      restoredApiKey = parsed.toncenterApiKey.trim();
    }
  }
  if (!(await confirmWalletReplacement(t('wallet.importWalletKey'), { incoming: record }))) return false;
  return activateImportedEncryptedWalletRecord(wallet, record, { toncenterApiKey: restoredApiKey?.trim() || null });
}


async function requestUsernameMintName() {
  let feedback = t('username.mintHint');
  let tone = 'muted';
  let usernameValue = '';
  let availability = { name: '', state: 'idle' };
  let availabilityTimer = 0;
  const probeAvailability = (name) => {
    window.clearTimeout(availabilityTimer);
    availabilityTimer = window.setTimeout(async () => {
      availability = { name, state: 'checking' };
      updateActiveActionSummary();
      let state = 'unknown';
      let parked = false;
      try {
        if (tonRpcLimited()) throw Object.assign(new Error('rpc busy'), { code: 'RATE_LIMITED' });
        await resolvePlathoUsernameOwner(name);
        state = 'taken';
      } catch (error) {
        if (error instanceof UsernameNotRegisteredError) state = 'free';
        else parked = error?.code === 'RATE_LIMITED' || noteTonRpcRateLimit(error);
      }
      if (availability.name !== name) return;
      availability = { name, state };
      updateActiveActionSummary();
      if (parked && activeActionDialog) availabilityTimer = window.setTimeout(() => { availability = { name: '', state: 'idle' }; updateActiveActionSummary(); }, 5000);
    }, 600);
  };
  await refreshVaultNavBalanceInBackground().catch(() => null);
  let hintAction = null;
  while (true) {
    const result = await openActionDialog({
      title: t('username.mintPlathoName'),
      hint: feedback,
      hintAction,
      tone,
      submitLabel: t('username.createUsername'),
      fields: [{
        id: 'username',
        label: t('username.usernameLabel'),
        placeholder: t('username.mintPlaceholder'),
        autocomplete: 'off',
        value: usernameValue,
      }, ...spendPasswordFields()],
      formAutocomplete: 'on',
      validateSubmit: async (submitted) => {
        try { normalizeUsernameInput(submitted?.username); } catch (error) { return { ok: false, error: error.message }; }
        const passwordRefusal = await spendPasswordRefusal(submitted);
        return passwordRefusal ? { ok: false, error: passwordRefusal } : { ok: true, result: { username: String(submitted?.username ?? '') } };
      },
      summary: (values) => {
        const raw = values.username?.trim() || t('common.notSet');
        const lines = [
          { label: t('username.display'), value: canonicalUsernameDisplay(raw) },
          { label: t('username.athPrice'), value: usernameMintPricePreview(raw) },
        ];
        let normalized = null;
        try { normalized = normalizeUsernameInput(raw); } catch { normalized = null; }
        if (normalized && availability.name !== normalized) probeAvailability(normalized);
        const known = normalized && availability.name === normalized ? availability.state : (normalized ? 'checking' : 'idle');
        const availabilityText = known === 'free' ? t('username.availabilityFree')
          : known === 'taken' ? t('username.availabilityTaken')
            : known === 'checking' ? t('username.availabilityChecking')
              : known === 'unknown' ? t('username.availabilityUnknown') : '';
        if (availabilityText) lines.push({ label: t('username.availability'), value: availabilityText });
        let blocked = known === 'taken' || known === 'checking';
        const athBalance = connectedWalletAthBalanceAtomic();
        if (athBalance !== null) {
          let priceAtomic = null;
          try { priceAtomic = localUsernameMintPriceAtomic(normalizeUsernameInput(raw)); } catch { priceAtomic = null; }
          const short = priceAtomic !== null && athBalance < priceAtomic;
          lines.push({ label: t('username.yourAth'), value: short ? t('username.athBalanceNotEnough', { amount: formatAthAtomic(athBalance) }) : t('username.athBalance', { amount: formatAthAtomic(athBalance) }) });
          if (short) blocked = true;
        }
        lines.push({ label: t('common.cost'), value: t('common.gramCostValue', { amount: formatTonNanotonsUp(estimatedUsernameMintTonFeeNanotons()) }) });
        setActiveActionSubmitEnabled(!blocked);
        return lines;
      },
    });
    if (!result) return null;
    usernameValue = result.username;
    try {
      const username = normalizeUsernameInput(result.username);
      const priceAtomic = localUsernameMintPriceAtomic(username);
      const athBalance = connectedWalletAthBalanceAtomic();
      if (priceAtomic !== null && athBalance !== null && athBalance < priceAtomic) {
        const error = new Error(t('errors.notEnoughAth', { need: formatAthAtomic(priceAtomic), have: formatAthAtomic(athBalance) }));
        error.code = 'PLATHO_ATH_REQUIRED';
        throw error;
      }
      return username;
    } catch (error) {
      feedback = error.message;
      hintAction = error?.code === 'PLATHO_ATH_REQUIRED' && buyAthButton ? { label: t('profile.buyAth'), run: doorPress(openBuyAthDialog, { money: true }) } : null;
      tone = 'error';
    }
  }
}

