const PLATHO_ACTIVATION_CONFIRMED_KEY_PREFIX = 'platho.activation.confirmed.v1:';

function activationConfirmedStorageKey(walletAddress) {
  const raw = rawWalletAddress(walletAddress);
  return raw ? `${PLATHO_ACTIVATION_CONFIRMED_KEY_PREFIX}${raw}` : null;
}

function activationDeploymentRaw() {
  try { return rawWalletAddress(requireProfileRegistryAddress()); } catch { return null; }
}

function rememberConfirmedActivation(walletAddress, user) {
  const key = activationConfirmedStorageKey(walletAddress);
  const registry = activationDeploymentRaw();
  if (!key || !registry || user?.exists !== true) return;
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify({
      v: 1, walletAddress: rawWalletAddress(walletAddress), registry, confirmedAt: Date.now(),
      current_key_id: String(user.current_key_id ?? 0n), key_generation: String(user.key_generation ?? 0n),
      enc_pubkey: String(user.enc_pubkey ?? 0n), sign_pubkey: String(user.sign_pubkey ?? 0n), scan_pubkey: String(user.scan_pubkey ?? 0n),
    }));
  } catch { }
}

function forgetConfirmedActivation(walletAddress) {
  const key = activationConfirmedStorageKey(walletAddress);
  if (!key) return;
  try { localStorageOrNull()?.removeItem(key); } catch { }
}

function readConfirmedActivation(walletAddress, draftMessage) {
  const key = activationConfirmedStorageKey(walletAddress);
  const registry = activationDeploymentRaw();
  if (!key || !registry || !draftMessage) return null;
  let record = null;
  try { record = JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'); } catch { return null; }
  if (!record || record.v !== 1 || record.walletAddress !== rawWalletAddress(walletAddress) || record.registry !== registry) return null;
  try {
    if (BigInt(record.enc_pubkey) !== BigInt(draftMessage.enc_pubkey ?? 0n)) return null;
    if (BigInt(record.sign_pubkey) !== BigInt(draftMessage.sign_pubkey ?? 0n)) return null;
    if (BigInt(record.current_key_id) <= 0n) return null;
    return {
      exists: true,
      current_key_id: BigInt(record.current_key_id),
      key_generation: BigInt(record.key_generation ?? 0),
      enc_pubkey: BigInt(record.enc_pubkey),
      sign_pubkey: BigInt(record.sign_pubkey),
      scan_pubkey: BigInt(record.scan_pubkey ?? 0),
      confirmedAt: Number(record.confirmedAt ?? 0),
    };
  } catch { return null; }
}

function applyConfirmedActivation(walletAddress, draftMessage, localAuthPubkey) {
  const user = readConfirmedActivation(walletAddress, draftMessage);
  if (!user) return false;
  globalThis.plathoVaultBinding = { walletAddress, user: { ...user, auth_pubkey: localAuthPubkey }, keyRecord: null, remembered: true };
  return true;
}

function activationAnswerKnownFor(walletAddress) {
  const binding = globalThis.plathoVaultBinding;
  const raw = rawWalletAddress(walletAddress);
  return Boolean(binding?.user && raw && rawWalletAddress(binding.walletAddress) === raw);
}

async function refreshVaultActivationStatus(options = {}) {
  if (!plathoWallet?.address || !localVaultDraft?.message) {
    setText(vaultRecordStatus, plathoWallet ? t('vault.keysPending') : t('common.walletRequiredStatus'));
    refreshMessageActionStatuses();
    refreshComposerPublishPolicy();
    return null;
  }
  let rereadFor = null;
  try {
    const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
    const provider = createKeyShardTonRpcProvider({ profileRegistryAddress: registry, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
    const forWallet = plathoWallet.address;
    const forWalletRaw = rawWalletAddress(forWallet);
    rereadFor = forWalletRaw;
    let view;
    try {
      view = await withVaultReadLock(() => provider.getView(forWallet, { verify: true, priority: 'critical', cacheTtlMs: 0, stopOnUninitializedAccount: true }));
    } catch (readError) {
      if (!isKeyShardUninitError(readError)) throw readError;
      view = { exists: false };
    }
    if (!plathoWallet?.address || rawWalletAddress(plathoWallet.address) !== forWalletRaw) return globalThis.plathoVaultBinding ?? null;
    const localAuthPubkey = localVaultAuthKeyPair?.publicKey ? bytesToBigIntValue(localVaultAuthKeyPair.publicKey) : 0n;
    const registeredMine = view?.exists === true
      && BigInt(view.enc_pubkey ?? 0n) === BigInt(localVaultDraft.message.enc_pubkey ?? 0n)
      && BigInt(view.sign_pubkey ?? 0n) === BigInt(localVaultDraft.message.sign_pubkey ?? 0n);
    if (!registeredMine) {
      globalThis.plathoVaultBinding = { walletAddress: forWallet, user: { exists: view?.exists === true, current_key_id: 0n }, keyRecord: null };
      clearPlathoActivationReread();
      forgetConfirmedActivation(forWallet);
      setText(vaultRecordStatus, t('vault.activationRequired'));
      refreshMessageActionStatuses();
      refreshMessagingControls();
      refreshComposerPublishPolicy();
      return null;
    }
    const user = {
      exists: true,
      current_key_id: BigInt(view.key_id),
      auth_pubkey: localAuthPubkey,
      key_generation: BigInt(view.key_generation ?? 0n),
      enc_pubkey: BigInt(view.enc_pubkey),
      sign_pubkey: BigInt(view.sign_pubkey),
      scan_pubkey: BigInt(view.scan_pubkey ?? 0n),
    };
    globalThis.plathoVaultBinding = { walletAddress: forWallet, user, keyRecord: null };
    clearPlathoActivationReread();
    rememberConfirmedActivation(forWallet, user);
    setText(vaultRecordStatus, t('vault.activated'));
    maybeShowActivationWelcome(forWallet);
    refreshMessageActionStatuses();
    refreshMessagingControls();
    refreshComposerPublishPolicy();
    return globalThis.plathoVaultBinding;
  } catch (error) {
    if (!isTonRpcRateLimitError(error)) console.warn('[keyshard] activation status read failed', error);
    if (rereadFor && rawWalletAddress(plathoWallet?.address) === rereadFor) schedulePlathoActivationReread(rereadFor);
    setText(vaultRecordStatus, t('vault.keysPending'));
    refreshMessageActionStatuses();
    refreshComposerPublishPolicy();
    return globalThis.plathoVaultBinding ?? null;
  }
}

const bootScreen = document.querySelector('#bootScreen');
let bootSignalCanvas = document.querySelector('#bootSignal');
let bootScreenActive = Boolean(bootScreen) && bootScreen.hidden !== true;
let stopBootSignalField = null;
let bootScreenSafetyTimer = null;
let bootScreenIdleFailsafe = null;

function setBootDebug(step) {
  try { console.log('[platho boot]', step); } catch { }
}

function startBootSignalField(canvas) {
  if (!canvas) return () => {};
  if (backgroundMode === 'none') { canvas.hidden = true; return () => {}; }
  if (backgroundMode === 'plasma') return startBootPlasmaField(canvas);
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const reduceMotion = Boolean(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  if (typeof Worker !== 'undefined' && typeof canvas.transferControlToOffscreen === 'function') {
    try {
      const worker = new Worker(new URL('./boot-signal-worker.js?v=19', import.meta.url), { type: 'module' });
      const offscreen = canvas.transferControlToOffscreen();
      const { mark: _boot_mark_not_cloneable, ...sliders } = nodesFieldOptions();
      worker.postMessage(
        { type: 'init', canvas: offscreen, width: window.innerWidth, height: window.innerHeight, dpr, reduceMotion, ...sliders, patternUrl: bootFieldPatternUrl(), ink: bootFieldInk() },
        [offscreen],
      );
      const onResize = () => { try { worker.postMessage({ type: 'resize', width: window.innerWidth, height: window.innerHeight }); } catch { } };
      window.addEventListener('resize', onResize);
      return () => {
        window.removeEventListener('resize', onResize);
        try { worker.postMessage({ type: 'stop' }); } catch { }
        try { worker.terminate(); } catch { }
      };
    } catch (error) {
      console.error(error);
    }
  }
  const ctx = canvas.getContext('2d');
  if (!ctx) return () => {};
  const field = createBootSignalField(ctx, { reduceMotion, ...nodesFieldOptions() });
  field.resize(window.innerWidth, window.innerHeight, dpr);
  field.start();
  const patternUrl = bootFieldPatternUrl();
  if (patternUrl && typeof createImageBitmap === 'function') {
    Promise.resolve(patternUrl).then((url) => { const [head, body] = String(url).split(','); const mime = /^data:([^;]+)/.exec(head)?.[1] ?? 'image/png'; const bin = atob(body); const bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i); return new Blob([bytes], { type: mime }); }).then((b) => createImageBitmap(b))
      .then((bitmap) => { field.setMark(bitmap); field.paintOnce(); })
      .catch(() => { });
  }
  let raf = null;
  let stopped = false;
  const loop = (now) => { raf = null; if (stopped) return; field.tick(now); raf = requestAnimationFrame(loop); };
  const onResize = () => { field.resize(window.innerWidth, window.innerHeight, dpr); field.paintOnce(); };
  window.addEventListener('resize', onResize);
  if (!reduceMotion) raf = requestAnimationFrame(loop);
  return () => {
    stopped = true;
    if (raf !== null) { cancelAnimationFrame(raf); raf = null; }
    window.removeEventListener('resize', onResize);
  };
}

function startBootPlasmaField(canvas) {
  const screen = canvas.closest('.boot-screen');
  if (!screen) return () => {};
  canvas.hidden = true;
  const layer = attachAuroraLayer(screen);
  const stage = createAuroraStage(auroraCount);
  const view = createAuroraView(layer, stage, 'shell');
  auroraScenes.push(view);
  auroraLastFrameAt = 0;
  startAuroraLoop();
  return () => {
    const sceneAt = auroraScenes.indexOf(view);
    if (sceneAt >= 0) auroraScenes.splice(sceneAt, 1);
    const stageAt = auroraStages.indexOf(stage);
    if (stageAt >= 0) auroraStages.splice(stageAt, 1);
    layer.remove();
  };
}

function armBootScreenIdleFailsafe() {
  if (bootScreenIdleFailsafe) clearTimeout(bootScreenIdleFailsafe);
  const tick = () => {
    if (!bootScreenActive) return;
    if (activeActionDialog) { bootScreenIdleFailsafe = setTimeout(tick, 5_000); return; }
    setBootDebug('idle-failsafe:reveal');
    hideBootScreen();
  };
  bootScreenIdleFailsafe = setTimeout(tick, 12_000);
}

function initBootScreen() {
  if (!bootScreenActive) return;
  setBootDebug('init');
  try {
    stopBootSignalField = startBootSignalField(bootSignalCanvas);
    setBootDebug(`init:field-ok:${backgroundMode}`);
  } catch (error) {
    setBootDebug(`init:field-err ${error?.message ?? error}`);
    console.error(error);
  }
  armBootScreenIdleFailsafe();
}

function showBootScreenForRelock() {
  if (!bootScreen || bootScreenActive) return;
  if (plathoWallet || !hasStoredPlathoWalletRecord()) return;
  setBootDebug('relock:show');
  bootScreen.dataset.phase = 'idle';
  bootScreen.classList.remove('is-hiding');
  bootScreen.hidden = false;
  bootScreenActive = true;
  try {
    const fresh = document.createElement('canvas');
    fresh.className = 'boot-signal';
    fresh.id = 'bootSignal';
    fresh.setAttribute('aria-hidden', 'true');
    bootSignalCanvas.replaceWith(fresh);
    bootSignalCanvas = fresh;
    stopBootSignalField = startBootSignalField(bootSignalCanvas);
  } catch (error) {
    console.error(error);
  }
  armBootScreenIdleFailsafe();
}

function setBootScreenPhase(phase) {
  if (!bootScreenActive || !bootScreen) return;
  bootScreen.dataset.phase = phase;
  if (phase === 'loading') {
    if (bootScreenIdleFailsafe) { clearTimeout(bootScreenIdleFailsafe); bootScreenIdleFailsafe = null; }
    if (!bootScreenSafetyTimer) bootScreenSafetyTimer = setTimeout(() => hideBootScreen(), 45_000);
  }
}

const BOOT_SCREEN_MOVE_MAX_MS = 5 * 60_000;
let bootScreenMoveSince = 0;
function noteBootScreenProgress(text) {
  if (!bootScreenActive || !bootScreen) return;
  const label = document.getElementById('bootLoadingLabel');
  if (label) label.textContent = text ?? t('boot.loading');
  if (text === null || bootScreen.dataset.phase !== 'loading') return;
  const now = Date.now();
  if (!bootScreenMoveSince) bootScreenMoveSince = now;
  if (now - bootScreenMoveSince > BOOT_SCREEN_MOVE_MAX_MS) return;
  if (bootScreenSafetyTimer) clearTimeout(bootScreenSafetyTimer);
  bootScreenSafetyTimer = setTimeout(() => hideBootScreen(), 45_000);
}

async function runBootScreenUnlock() {
  try {
    setBootDebug('unlock:open');
    const wallet = await loadPlathoWallet();
    if (!wallet) { setBootDebug('unlock:cancel'); markBootAppReady(); return; }
    setBootDebug('unlock:ok');
    await enforceTelegramSeedBackupGate(wallet).catch((error) => console.warn('[wallet] the 24-word gate', error));
    await bootCrypto();
    flashWalletIdentityStatus(t('wallet.unlocked'));
  } catch (error) {
    setBootDebug(`unlock:err ${error?.message ?? error}`);
    markBootAppReady();
    console.error(error);
  }
}

function surfaceFeedOnReveal() {
  if (!publicFeed) return;
  let index = 0;
  for (const node of Array.from(publicFeed.children)) {
    const key = node.dataset?.itemId;
    if (!key) continue;
    node.classList.remove('is-surfacing');
    void node.offsetWidth;
    publicFeedSurfacedIds.delete(key);
    if (surfaceRow(node, publicFeedSurfacedIds, key, index)) index += 1;
  }
}

function hideBootScreen() {
  if (!bootScreenActive || !bootScreen) return;
  setBootDebug('ready');
  bootScreenActive = false;
  try { surfaceFeedOnReveal(); } catch (error) { console.warn('[feed] reveal surfacing skipped', error); }
  if (bootScreenSafetyTimer) { clearTimeout(bootScreenSafetyTimer); bootScreenSafetyTimer = null; }
  if (bootScreenIdleFailsafe) { clearTimeout(bootScreenIdleFailsafe); bootScreenIdleFailsafe = null; }
  bootScreen.classList.add('is-hiding');
  const finalize = () => {
    bootScreen.hidden = true;
    if (typeof stopBootSignalField === 'function') { try { stopBootSignalField(); } catch { } stopBootSignalField = null; }
  };
  let done = false;
  const once = () => { if (done) return; done = true; bootScreen.removeEventListener('transitionend', once); finalize(); };
  bootScreen.addEventListener('transitionend', once);
  setTimeout(once, 620);
}

function markBootAppReady() {
  hideBootScreen();
}

async function bootCrypto() {
  const session = walletSessionGeneration;
  if (plathoWallet) void refreshWalletChainClock();
  try {
    if (!plathoWallet) {
      const hasStoredWallet = hasStoredPlathoWalletRecord();
      const requiredStatus = hasStoredWallet ? t('wallet.unlockRequired') : t('common.walletRequiredStatus');
      await bootWalletScopedLocalStores();
      if (plathoWallet || session !== walletSessionGeneration) return null;
      localIdentity = null;
      localVaultAuthKeyPair = null;
      localRecipientKeyPair = null;
      localSignedPublicBundle = null;
      localVaultDraft = null;
      if (hasStoredWallet) clearMessageAutoSyncTimer();
      else scheduleMessageAutoSync(2_000);
      refreshMessagingControls();
      renderWalletIdentity();
      setText(encryptionStatus, requiredStatus);
      setText(keyAuthStatus, requiredStatus);
      vaultDraftStatus.textContent = requiredStatus;
      setText(vaultRecordStatus, requiredStatus);
      setText(vaultRotateStatus, requiredStatus);
      localProfileAvatarPointer = null;
      refreshComposerPublishPolicy();
      if (!hasStoredWallet) markBootAppReady();
      return null;
    }
    const bootPhases = { startedAt: Date.now() };
    const phase = (name, since) => { bootPhases[name] = Date.now() - since; };
    let since = Date.now();
    renderWalletIdentity();
    localProfileAvatarPointer = readStoredProfileAvatarPointer(plathoWallet.address);
    localVaultAuthKeyPair = await deriveVaultAuthKeyPairFromWallet(plathoWallet);
    localIdentity = await loadMessagingIdentityFromWallet(VAULT_RECEIVE_CRYPTO_SUITE);
    localRecipientKeyPair = localIdentity?.encryptionKeyPair ?? null;
    localSignedPublicBundle = await exportSignedPublicKeyBundle(localIdentity, {
      purpose: appConfig.crypto?.signedBundlePurpose ?? 'pwa-runtime',
      ownerWallet: plathoWallet.address,
      vaultAddress: appConfig.profileRegistry?.address ?? null,
    });
    const verifiedBundle = await verifySignedPublicKeyBundle(localSignedPublicBundle);
    localVaultDraft = await createVaultMessagingKeyDraft(verifiedBundle.bundle, verifiedBundle.signingPublicKey, {
      authPublicKey: localVaultAuthKeyPair.publicKey,
    });
    phase('keysMs', since);
    const localAuthPubkey = localVaultAuthKeyPair?.publicKey ? bytesToBigIntValue(localVaultAuthKeyPair.publicKey) : 0n;
    const activationRemembered = applyConfirmedActivation(plathoWallet.address, localVaultDraft?.message, localAuthPubkey);
    bootPhases.activationRemembered = activationRemembered;
    refreshMessagingControls();
    await restoreOwnAvatarFromCacheFast(plathoWallet.address).catch(() => {});
    since = Date.now();
    await bootWalletScopedLocalStores();
    phase('storesMs', since);
    globalThis.plathoRefreshVaultActivation = async (provider) => refreshVaultActivationStatus({ provider });
    if (activationRemembered) setText(vaultRecordStatus, t('vault.activated'));
    else setText(vaultRecordStatus, t('common.checking'));
    setText(vaultDraftStatus, t('common.checking'));
    since = Date.now();
    if (activationRemembered) {
      void refreshVaultActivationStatus({ skipGlobal: true }).then(() => { phase('activationReadMs', since); }).catch(() => {});
    } else {
      await refreshVaultActivationStatus({ skipGlobal: true });
      phase('activationReadMs', since);
    }
    bootPhases.revealedAfterMs = Date.now() - bootPhases.startedAt;
    globalThis.plathoLastBoot = bootPhases;
    setText(encryptionStatus, t('common.checking'));
    setText(capsulePolicyStatus, t('common.checking'));
    setText(keyAuthStatus, verifiedBundle.signingPublicKey.length === 32 ? t('vault.signedBundle') : t('vault.review'));
    refreshMessagingControls();
    if (session === walletSessionGeneration) markBootAppReady();
    new Promise((resolve) => setTimeout(resolve, 0))
      .then(() => runPlathoCryptoSelfTest())
      .then((result) => {
        setText(encryptionStatus, result.hybrid.aadTamperRejected ? t('vault.hybridPassed') : t('vault.review'));
        setText(capsulePolicyStatus, result.capsule.replayRejected ? t('vault.replayGuarded') : t('vault.review'));
      })
      .catch((error) => {
        console.error(error);
        setText(encryptionStatus, t('vault.review'));
        setText(capsulePolicyStatus, t('vault.review'));
      });
    void refreshVaultNavBalanceInBackground().catch(() => {});
    beginMessageSyncUi();
    const syncResult = await syncPrivateCapsulesFromChainOnce({ mode: 'auto' }).catch((error) => {
      refreshMessagingControls();
      if (noteTonRpcRateLimit(error)) {
        failMessageSyncUi(t('sync.delayedLabel'));
      } else {
        failMessageSyncUi(t('sync.failedLabel'));
        console.error(error);
      }
      return null;
    });
    if (syncResult) completeMessageSyncUi(syncResult);
    await refreshOwnProfileAvatar().catch((error) => {
      if (isUninitializedAccountError(error)) return;
      if (!noteTonRpcRateLimit(error)) console.error(error);
    });
    scheduleMessageAutoSync();
    armIntroReceiveLane().catch((error) => console.warn('[intro] arm on unlock failed', error));
    if (isVaultViewActive()) {
      await refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
        if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
        if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
      });
    } else {
      scheduleVaultAutoRefresh(2_000);
    }
  } catch (error) {
    setText(encryptionStatus, t('vault.unavailable'));
    localVaultAuthKeyPair = null;
    localVaultDraft = null;
    setText(keyAuthStatus, t('common.blocked'));
    vaultDraftStatus.textContent = t('common.blocked');
    setText(capsulePolicyStatus, t('common.blocked'));
    refreshMessagingControls();
    setText(walletAddressStatus, t('common.blocked'));
    setText(vaultRecordStatus, t('common.blocked'));
    markBootAppReady();
    console.error(error);
  }
}

