let serviceWorkerUpdateAskedAt = 0;
function checkForServiceWorkerUpdate(minIntervalMs = 60_000) {
  if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
  const now = Date.now();
  if (now - serviceWorkerUpdateAskedAt < minIntervalMs) return;
  serviceWorkerUpdateAskedAt = now;
  navigator.serviceWorker.getRegistration('/sw.js').then((registration) => registration?.update()).catch(() => {});
}
let feeLabelsGeneration = null;
let profileFeeLabelsOwed = false;
let generationBoundaryTimer = null;
const GENERATION_TIMER_MAX_MS = 2_000_000_000;
const GENERATION_REPAINT_SPREAD_MS = 30_000;
function refreshFeeLabelsAcrossGenerations() {
  const generation = writeGenerationNow();
  armGenerationBoundaryRepaint();
  if (feeLabelsGeneration === null) { feeLabelsGeneration = generation; return; }
  if (generation === feeLabelsGeneration) {
    if (profileFeeLabelsOwed) profileFeeLabelsOwed = !refreshProfileFeeLabels({ overLiveStatus: false });
    return;
  }
  feeLabelsGeneration = generation;
  const repaints = [
    () => { profileFeeLabelsOwed = !refreshProfileFeeLabels({ overLiveStatus: false }); },
    refreshComposerCostStatus,
    () => { repaintActiveActionDialogPrices(); },
    () => { renderConversation(); },
  ];
  for (const repaint of repaints) {
    try { repaint(); } catch (error) { console.warn('[fees] repaint across the generation boundary failed', error); }
  }
}

function armGenerationBoundaryRepaint(nowMs = Date.now()) {
  if (generationBoundaryTimer !== null || !(Number(CUTOVER_EPOCH) > 0)) return;
  const wait = Number(CUTOVER_EPOCH) * 86_400_000 - nowMs;
  if (!(wait > 0) || wait > GENERATION_TIMER_MAX_MS) return;
  const jitter = new Uint32Array(1);
  globalThis.crypto.getRandomValues(jitter);
  generationBoundaryTimer = window.setTimeout(() => { generationBoundaryTimer = null; refreshFeeLabelsAcrossGenerations(); }, wait + 250 + (jitter[0] % GENERATION_REPAINT_SPREAD_MS));
}

function composerPricesMoved(statusElement) {
  const painted = Number(statusElement?.dataset?.pricedGeneration);
  if (!statusElement || !Number.isInteger(painted) || painted === writeGenerationNow()) return false;
  announceComposerPricesMoved(statusElement);
  return true;
}

