const RAIL_LABEL_MIN_PX = 8;
function fitLabelsOneSize(pairs, minPx, inset = 0) {
  for (const [, label] of pairs) label.style.fontSize = '';
  const tooWide = () => pairs.some(([item, label]) => {
    const box = label.getBoundingClientRect().width;
    if (!(box > 0)) return false;
    const words = document.createRange();
    words.selectNodeContents(label);
    const style = getComputedStyle(item);
    const inner = item.getBoundingClientRect().width - parseFloat(style.borderLeftWidth) - parseFloat(style.borderRightWidth) - inset;
    return words.getBoundingClientRect().width > box + 0.05 || box > inner + 0.05;
  });
  let size = pairs.length > 0 ? parseFloat(getComputedStyle(pairs[0][1]).fontSize) : 0;
  while (size > minPx && tooWide()) {
    size -= 0.5;
    for (const [, label] of pairs) label.style.fontSize = `${size}px`;
  }
}
function fitRailLabels() {
  fitLabelsOneSize(railItems.map((item) => [item, item.querySelector(':scope > span:not(.icon):not(.rail-badge)')]).filter(([, label]) => label), RAIL_LABEL_MIN_PX);
}
