function quickStartActivationUnderfunded() {
  const bal = quickStartWalletTonNanotons();
  return bal !== null && bal < plathoAccountActivationFeeNanotons();
}


let quickStartActivationDone = false;
let quickStartActivationInFlight = false;
let quickStartActivationGeneration = 0;

function buildQuickStartActivateBody() {
  quickStartActivationGeneration += 1;
  quickStartActivationDone = false;
  quickStartActivationInFlight = plathoActivationInFlightForCurrentWallet();
  const generation0 = quickStartActivationGeneration;
  void refreshPlathoActivationArrear().then((changed) => { if (changed && generation0 === quickStartActivationGeneration) applyGate(); }).catch(() => {});
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const summary = document.createElement('div');
  summary.className = 'quick-start-balance-line';
  const hint = document.createElement('div');
  hint.className = 'quick-start-step-hint';
  const activate = document.createElement('button');
  activate.type = 'button';
  activate.className = 'discovery-cta-action quick-start-key-cta';
  activate.textContent = t('quickstart.activateAction');
  activate.addEventListener('click', async () => {
    const generation = quickStartActivationGeneration;
    const mine = () => generation === quickStartActivationGeneration;
    activate.disabled = true;
    setText(quickStartStepStatus, t('quickstart.working'));
    try {
      const published = await submitVaultRegisterMessagingKeys({ preConfirmed: true });
      if (!mine()) return;
      if (published !== null) {
        quickStartActivationInFlight = true;
        applyGate();
        setText(quickStartStepStatus, t('quickstart.activationSent'));
      }
      await confirmActivation(generation);
    } catch (error) {
      console.error(error);
      if (!mine()) return;
      quickStartActivationInFlight = false;
      applyGate();
      setText(quickStartStepStatus, error?.code === 'PLATHO_WALLET_GRAM_REQUIRED'
        ? error.message
        : t('quickstart.couldNotCompleteLater'));
    } finally {
      if (mine()) activate.disabled = false;
    }
  });
  const applyGate = () => {
    const bal = quickStartWalletTonNanotons();
    const fee = plathoAccountActivationFeeNanotons();
    summary.textContent = bal === null
      ? t('quickstart.activationNeedsChecking', { fee: formatTonNanotonsUp(fee) })
      : t('quickstart.balanceActivationNeeds', { balance: formatTonNanotons(bal), fee: formatTonNanotonsUp(fee) });
    const locked = !plathoWallet;
    const underfunded = quickStartActivationUnderfunded();
    const done = quickStartActivationDone || hasActivePlathoAccount();
    const inFlight = quickStartActivationInFlight && !done;
    const blocked = locked || underfunded;
    activate.hidden = blocked || done || inFlight;
    hint.hidden = done || !(blocked || inFlight);
    hint.textContent = inFlight
      ? t('quickstart.activationSentHint')
      : locked
      ? t('quickstart.unlockToActivate')
      : underfunded
      ? t('quickstart.notEnoughGramHint')
      : '';
    hint.classList.toggle('is-error', blocked && !inFlight);
  };
  const confirmActivation = async (generation) => {
    const mine = () => generation === quickStartActivationGeneration;
    const confirmed = await waitForPlathoAccountActivation(mine);
    if (!mine()) return;
    if (confirmed) {
      quickStartActivationDone = true;
      quickStartActivationInFlight = false;
      applyGate();
      setText(quickStartStepStatus, t('quickstart.activationConfirmed'));
      return;
    }
    applyGate();
    setText(quickStartStepStatus, t('quickstart.activationStillConfirming'));
  };
  const refresh = async () => {
    await quickStartRefreshWalletBalanceRaw();
    applyGate();
  };
  applyGate();
  refresh();
  if (quickStartActivationInFlight) {
    setText(quickStartStepStatus, t('quickstart.activationSent'));
    void confirmActivation(quickStartActivationGeneration);
  }
  wrap.append(summary, hint, activate);
  return wrap;
}

function buildQuickStartBackupBody() {
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const plate = (note, label, onClick) => {
    const hint = document.createElement('div');
    hint.className = 'quick-start-step-hint';
    hint.textContent = note;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'discovery-cta-action quick-start-key-cta';
    button.textContent = label;
    button.addEventListener('click', async () => {
      button.disabled = true;
      try { await onClick(); } catch (error) { console.error(error); } finally { button.disabled = false; }
    });
    wrap.append(hint, button);
  };
  plate(t('quickstart.seedPlateNote'), t('quickstart.saveSeedAction'), async () => {
    const wallet = plathoWallet ?? await loadPlathoWallet();
    if (!wallet) return;
    if ((walletLeftForegroundSinceUnlock || walletLeftUnattended()) && !(await confirmWalletPasswordForExport(wallet))) return;
    if (isTelegramEnv() && !isTelegramSeedBackupConfirmed(wallet.address)) { await enforceTelegramSeedBackupGate(wallet, { force: true }); return; }
    await showWalletSeed(t('wallet.recoveryPhrase'), exportPlathoWalletRecoveryPhrase(wallet));
  });
  const confirm = document.createElement('div');
  confirm.className = 'quick-start-key-confirm';
  confirm.hidden = true;
  const question = document.createElement('div');
  question.className = 'quick-start-step-hint';
  question.textContent = t('quickstart.keyFileConfirmQuestion');
  const yes = document.createElement('button');
  yes.type = 'button';
  yes.className = 'discovery-cta-action quick-start-key-cta';
  yes.textContent = t('quickstart.keyFileConfirmYes');
  const again = document.createElement('button');
  again.type = 'button';
  again.className = 'discovery-cta-action';
  again.textContent = t('quickstart.keyFileDownloadAgain');
  confirm.append(question, yes, again);
  const runKeyExport = async () => {
    const outcome = await exportEncryptedWalletKeyFile(plathoWallet ?? null);
    if (outcome === false) { setText(quickStartStepStatus, t('quickstart.notCompleted')); return; }
    if (outcome === 'cancelled') {
      confirm.hidden = true; quickStartKeyFileAwaitingConfirm = false;
      setText(quickStartStepStatus, t('quickstart.keyFileSaveCancelled'));
      return;
    }
    if (outcome === 'triggered') {
      confirm.hidden = false; quickStartKeyFileAwaitingConfirm = true;
      setText(quickStartStepStatus, t('quickstart.keyFileConfirmQuestion'));
      return;
    }
    confirm.hidden = true; quickStartKeyFileAwaitingConfirm = false;
    setText(quickStartStepStatus, t('quickstart.keyFileSaved'));
  };
  plate(t('quickstart.keyFilePlateNote'), t('quickstart.saveWalletKeyAction'), runKeyExport);
  yes.addEventListener('click', () => {
    confirmWalletKeyBackupArrived();
    confirm.hidden = true; quickStartKeyFileAwaitingConfirm = false;
    setText(quickStartStepStatus, t('quickstart.keyFileSaved'));
  });
  again.addEventListener('click', () => { runKeyExport().catch((error) => console.error(error)); });
  wrap.append(confirm);
  if (quickStartKeyFileAwaitingConfirm && walletKeyBackupPendingForStoredWallet()) confirm.hidden = false;
  return wrap;
}

