let quickStartStepIndex = 0;

function applicableQuickStartSteps() {
  return QUICK_START_STEPS.filter((step) => !step.skip?.());
}

function renderQuickStartProgress() {
  if (!quickStartProgress) return;
  quickStartProgress.innerHTML = '';
  const applicable = applicableQuickStartSteps();
  const currentIndex = applicable.indexOf(QUICK_START_STEPS[quickStartStepIndex]);
  applicable.forEach((_, i) => {
    const dot = document.createElement('span');
    dot.className = 'quick-start-progress-dot';
    if (currentIndex >= 0 && i < currentIndex) dot.classList.add('is-done');
    else if (i === currentIndex) dot.classList.add('is-current');
    quickStartProgress.appendChild(dot);
  });
}

function renderQuickStartStep({ skipCompleted = true } = {}) {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step) { finishQuickStart(); return; }
  if (step.skip?.()) {
    if (skipCompleted) { quickStartAdvance(); return; }
    if (quickStartStepIndex > 0) { quickStartStepIndex -= 1; renderQuickStartStep({ skipCompleted: false }); return; }
    finishQuickStart();
    return;
  }
  if (skipCompleted && !step.optional && step.autoDone()) { quickStartAdvance(); return; }
  renderQuickStartProgress();
  const applicable = applicableQuickStartSteps();
  setText(quickStartStepCounter, t('quickstart.stepCounter', { n: applicable.indexOf(step) + 1, total: applicable.length }));
  setText(quickStartStepTitle, step.title());
  setText(quickStartStepWhy, step.why());
  setText(quickStartStepStatus, '');
  if (quickStartStepBody) {
    quickStartStepBody.innerHTML = '';
    const body = step.body();
    if (body) quickStartStepBody.appendChild(body);
  }
  if (quickStartActionButton) quickStartActionButton.textContent = step.action();
  if (quickStartBackButton) quickStartBackButton.hidden = quickStartStepIndex === 0;
  if (!quickStartBackupMode) saveQuickStartProgress(quickStartStepIndex);
}

function quickStartAdvance() {
  if (quickStartStepIndex >= QUICK_START_STEPS.length - 1) { finishQuickStart(); return; }
  quickStartStepIndex += 1;
  renderQuickStartStep();
}

let quickStartBackupMode = false;
let quickStartKeyFileAwaitingConfirm = false;

closeQuickStart.closings = 0;
function closeQuickStart() {
  closeQuickStart.closings = (closeQuickStart.closings ?? 0) + 1;
  releaseModalHold(quickStartDialog);
  hideDialogAnimated(quickStartDialog);
  flushPendingActivationWelcome();
  if (quickStartInstallStepShown) dropDeferredInstallPrompt();
  else offerDeferredInstallPrompt();
  quickStartInstallStepShown = false;
  if (!quickStartBackupMode && !closeQuickStart.keepOnboarding) dismissQuickStartForGood();
  closeQuickStart.keepOnboarding = false;
  quickStartBackupMode = false;
}

function dismissQuickStartForGood() {
  try { globalThis.localStorage?.setItem(QUICK_START_DISMISSED_KEY, '1'); } catch { }
  try { telegramCloudSet(QUICK_START_DISMISSED_CLOUD_KEY, '1').catch(() => {}); } catch { }
  clearQuickStartProgress();
}

function finishQuickStart() {
  clearQuickStartProgress();
  closeQuickStart();
  const activated = hasActivePlathoAccount() || plathoAccountActivationPending || plathoActivationInFlightForCurrentWallet();
  flashWalletIdentityStatus(t(activated ? 'quickstart.setupComplete' : 'quickstart.setupLater'));
}

const activationWelcomeDialog = document.querySelector('#activationWelcomeDialog');
const activationWelcomeCloseButton = document.querySelector('#activationWelcomeCloseButton');
const activationWelcomeStartButton = document.querySelector('#activationWelcomeStartButton');
const ACTIVATION_WELCOME_SHOWN_KEY_PREFIX = 'platho.activationWelcome.v1.';
const activationWelcomeShownThisSession = new Set();
let pendingActivationWelcomeWallet = null;

function activationWelcomeStorageKey(walletAddress) {
  const raw = rawWalletAddress(walletAddress);
  return raw ? `${ACTIVATION_WELCOME_SHOWN_KEY_PREFIX}${raw}` : null;
}

function activationWelcomeAlreadyShown(walletAddress) {
  const key = activationWelcomeStorageKey(walletAddress);
  if (!key) return true;
  if (activationWelcomeShownThisSession.has(key)) return true;
  try { return globalThis.localStorage?.getItem(key) === '1'; } catch { return false; }
}

function markActivationWelcomeShown(walletAddress) {
  const key = activationWelcomeStorageKey(walletAddress);
  if (!key) return;
  activationWelcomeShownThisSession.add(key);
  try { globalThis.localStorage?.setItem(key, '1'); } catch { }
}

function openActivationWelcomeDialog() {
  if (activationWelcomeDialog) { activationWelcomeDialog.classList.remove('is-closing'); activationWelcomeDialog.hidden = false; }
}

function closeActivationWelcomeDialog() {
  hideDialogAnimated(activationWelcomeDialog);
  offerDeferredInstallPrompt();
}

function maybeShowActivationWelcome(walletAddress) {
  if (!walletAddress || activationWelcomeAlreadyShown(walletAddress)) return;
  if (quickStartDialog && !quickStartDialog.hidden) { pendingActivationWelcomeWallet = walletAddress; return; }
  markActivationWelcomeShown(walletAddress);
  openActivationWelcomeDialog();
}

function flushPendingActivationWelcome() {
  const wallet = pendingActivationWelcomeWallet;
  pendingActivationWelcomeWallet = null;
  if (!wallet || activationWelcomeAlreadyShown(wallet)) return;
  markActivationWelcomeShown(wallet);
  openActivationWelcomeDialog();
}

activationWelcomeCloseButton?.addEventListener('click', () => closeActivationWelcomeDialog());
activationWelcomeStartButton?.addEventListener('click', () => closeActivationWelcomeDialog());

function openQuickStartAtStep(index) {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = Math.max(0, Math.min(Number(index) || 0, QUICK_START_STEPS.length - 1));
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
  holdPageBehindModal(quickStartDialog);
  renderQuickStartStep();
  focusQuickStartStepTitle();
}

function maybeResumeQuickStartAfterUnlock() {
  if (!quickStartDialog) return;
  if (quickStartDismissedForever()) return;
  if (quickStartDialog.hidden === false) {
    quickStartRefreshCurrentBalanceStep();
    return;
  }
  const savedStep = readQuickStartProgress();
  if (savedStep !== null) openQuickStartAtStep(savedStep);
}

function quickStartRefreshCurrentBalanceStep() {
  if (!quickStartDialog || quickStartDialog.hidden !== false) return;
  if (!quickStartStepsView || quickStartStepsView.hidden) return;
  const key = QUICK_START_STEPS[quickStartStepIndex]?.key;
  if (key === 'topup' || key === 'activate') renderQuickStartStep();
}

function openQuickStart() {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = false;
  if (quickStartStepsView) quickStartStepsView.hidden = true;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
  holdPageBehindModal(quickStartDialog);
}

function quickStartStepIndexByKey(key) {
  const i = QUICK_START_STEPS.findIndex((step) => step.key === key);
  return i >= 0 ? i : 0;
}

function openQuickStartAtBackup() {
  if (!quickStartDialog) return;
  quickStartBackupMode = true;
  quickStartStepIndex = quickStartStepIndexByKey('export');
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
  holdPageBehindModal(quickStartDialog);
  renderQuickStartStep();
  focusQuickStartStepTitle();
}

function maybeShowQuickStartOnFirstRun() {
  if (!quickStartDialog) return false;
  const savedStep = readQuickStartProgress();
  if (savedStep !== null && !quickStartDismissedForever()) {
    openQuickStartAtStep(savedStep);
    return true;
  }
  if (!hasStoredPlathoWalletRecord()) {
    if (quickStartDismissedForever()) return false;
    openQuickStart();
    return true;
  }
  if (walletKeyBackupPendingForStoredWallet()) {
    openQuickStartAtBackup();
    return true;
  }
  return false;
}

function focusQuickStartStepTitle() {
  if (!quickStartStepTitle || quickStartDialog?.hidden) return;
  if (!quickStartStepTitle.hasAttribute('tabindex')) quickStartStepTitle.setAttribute('tabindex', '-1');
  quickStartStepTitle.focus({ preventScroll: true });
}

quickStartBeginButton?.addEventListener('click', () => {
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  renderQuickStartStep();
  focusQuickStartStepTitle();
});
quickStartCloseButton?.addEventListener('click', () => closeQuickStart());
quickStartImportButtonEl?.addEventListener('click', () => {
  closeQuickStart.keepOnboarding = true;
  closeQuickStart();
  closeQuickStart.importPending = true;
  walletKeyBackupInput?.click();
});
quickStartBackButton?.addEventListener('click', () => {
  if (quickStartStepIndex > 0) { quickStartStepIndex -= 1; renderQuickStartStep({ skipCompleted: false }); }
});
async function runQuickStartPrimaryAction() {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step || !quickStartActionButton) return;
  quickStartActionButton.disabled = true;
  setText(quickStartStepStatus, t('quickstart.working'));
  try {
    const ok = await step.run();
    if (typeof ok === 'string') {
      setText(quickStartStepStatus, ok);
    } else if (ok === false) {
      setText(quickStartStepStatus, step.optional ? t('quickstart.nothingEntered') : t('quickstart.notCompleted'));
    } else {
      setText(quickStartStepStatus, t('quickstart.done'));
      quickStartAdvance();
    }
  } catch (error) {
    console.error(error);
    setText(quickStartStepStatus, walletDeviceFaultWords(error) ?? (step.optional
      ? t('quickstart.couldNotCompleteLater')
      : t('quickstart.couldNotComplete', { reason: error?.message ?? t('quickstart.tryAgain') })));
  } finally {
    quickStartActionButton.disabled = false;
  }
}

quickStartActionButton?.addEventListener('click', () => { runQuickStartPrimaryAction(); });

