const PROFILE_CARD_RETRY_LADDER_MS = [0, 4_000, 12_000, 30_000];
const PROFILE_CARD_MAX_ATTEMPTS = PROFILE_CARD_RETRY_LADDER_MS.length + 1;
let profileCardRetryTimers = [];

function clearProfileCardRetries() {
  for (const timer of profileCardRetryTimers) window.clearTimeout(timer);
  profileCardRetryTimers = [];
}

function driveProfileCardRead(subject, lane, attempt = 0) {
  lane.load()
    .then((result) => {
      if (profileCardSubject !== subject) return;
      const incomplete = result?.complete === false;
      const retrying = incomplete && attempt + 1 < PROFILE_CARD_MAX_ATTEMPTS;
      lane.render(result, { retrying });
      if (retrying) scheduleProfileCardRetry(subject, lane, attempt);
      else if (incomplete) markProfileCardLaneDone(subject, lane.name, { partial: true });
    })
    .catch((error) => {
      console.warn('profile card read unavailable', error);
      if (profileCardSubject !== subject) return;
      const retrying = attempt + 1 < PROFILE_CARD_MAX_ATTEMPTS;
      lane.render(null, { retrying });
      if (retrying) scheduleProfileCardRetry(subject, lane, attempt);
      else markProfileCardLaneDone(subject, lane.name, { partial: true });
    });
}

function scheduleProfileCardRetry(subject, lane, attempt) {
  const wait = PROFILE_CARD_RETRY_LADDER_MS[Math.min(attempt, PROFILE_CARD_RETRY_LADDER_MS.length - 1)];
  profileCardRetryTimers.push(window.setTimeout(() => {
    if (profileCardSubject !== subject) return;
    driveProfileCardRead(subject, lane, attempt + 1);
  }, wait));
}

function renderProfileCardLatestPost(wallet) {
  if (!profileCardLatest) return;
  const hadFocus = profileCardLatest.contains(document.activeElement);
  const node = buildDiscoveryLatestNode(wallet);
  profileCardLatest.replaceChildren();
  if (node) profileCardLatest.append(node);
  profileCardLatest.hidden = !node;
  if (hadFocus) refocusInProfileCard(node?.tabIndex === 0 ? node : null);
}

function refocusInProfileCard(target) {
  const into = target ?? profileCardDialog?.querySelector('#profileCardCloseButton');
  try { into?.focus({ preventScroll: true }); } catch { }
}

const PROFILE_CARD_REREAD_AFTER_SEC = 60;

function renderProfileCardActions(raw, own) {
  const focused = profileCardActions?.contains(document.activeElement) ? document.activeElement : null;
  const key = focused ? (focused.dataset?.i18n ?? focused.getAttribute?.('aria-label') ?? null) : null;
  renderProfileCardActionsNow(raw, own);
  if (!focused) return;
  const again = [...(profileCardActions?.querySelectorAll('button') ?? [])].find((button) => (button.dataset?.i18n ?? button.getAttribute('aria-label')) === key);
  refocusInProfileCard(again ?? null);
}

function renderProfileCardActionsNow(raw, own) {
  if (!profileCardActions) return;
  profileCardActions.replaceChildren();
  profileCardActions.hidden = own;
  if (own) return;
  const add = (labelKey, pressed, onClick, { primary = false } = {}) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = primary ? 'profile-card-action profile-card-action--primary' : 'profile-card-action';
    if (pressed !== null) button.setAttribute('aria-pressed', pressed ? 'true' : 'false');
    button.textContent = t(labelKey);
    button.dataset.i18n = labelKey;
    button.addEventListener('click', onClick);
    profileCardActions.append(button);
    return button;
  };
  add('profileCard.actionChannel', null, () => {
    closeProfileCardDialog();
    setView('public', { restoreRoom: false });
    openPublicChannelView({ authorWallet: raw });
  });
  add('profileCard.actionChat', null, () => {
    closeProfileCardDialog();
    openPrivateThreadForWallet(raw);
  }, { primary: true });
  const rooms = profileCardPinnedGroups(raw);
  const roomsButton = add('profileCard.actionGroups', null, (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden) { hideIdentityPopover(); return; }
    showProfileCardGroupsMenu(raw, rooms, event.currentTarget);
  });
  if (rooms.length === 0) roomsButton.disabled = true;
  const more = document.createElement('button');
  more.type = 'button';
  more.className = 'profile-card-action profile-card-action--more';
  more.title = t('profileCard.actionMore');
  more.setAttribute('aria-label', t('profileCard.actionMore'));
  more.setAttribute('aria-haspopup', 'menu');
  const chevron = document.createElement('span');
  chevron.className = 'icon icon-chevron-down';
  more.append(chevron);
  more.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden) { hideIdentityPopover(); return; }
    showProfileCardMoreMenu(raw, own, event.currentTarget);
  });
  profileCardActions.append(more);
}

function profileCardPinnedGroups(raw) {
  const profile = cachedChannelProfile(raw);
  return Array.isArray(profile?.groups) ? profile.groups : [];
}

function showProfileCardGroupsMenu(raw, rooms, anchor) {
  if (!anchor || rooms.length === 0) return;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'menu');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('profileCard.actionGroups');
  popover.append(title);
  for (const room of rooms) {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'identity-variant identity-variant-action';
    row.setAttribute('role', 'menuitem');
    const strong = document.createElement('strong');
    const known = groupRecordOf(String(room.groupId))?.name ?? null;
    strong.textContent = known || room.name || t('group.untitled');
    const hint = document.createElement('span');
    hint.textContent = room.founder ? t('group.joinLabel') : t('group.askLabel');
    row.append(strong, hint);
    row.addEventListener('click', () => {
      hideIdentityPopover();
      closeProfileCardDialog();
      const held = groupRecordOf(String(room.groupId));
      if (held && !held.leftAt) { openGroupThread(ensureGroupThread(held)); return; }
      void joinOrAskGroup(room, raw);
    });
    popover.append(row);
  }
  showPopoverAt(popover, anchor);
  settleProfileCardPalette();
}

function showProfileCardMoreMenu(raw, own, anchor) {
  if (!anchor) return;
  const stored = readContactDisplayPreference(raw);
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'menu');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('chat.contactActions');
  popover.append(title);
  const row = (labelKey, hintKey, pressed, onPick) => {
    const node = document.createElement('button');
    node.type = 'button';
    node.className = 'identity-variant identity-variant-action';
    node.setAttribute('role', 'menuitem');
    node.setAttribute('aria-pressed', pressed ? 'true' : 'false');
    const strong = document.createElement('strong');
    strong.textContent = t(labelKey);
    const hint = document.createElement('span');
    hint.textContent = t(hintKey);
    node.append(strong, hint);
    node.addEventListener('click', () => { hideIdentityPopover(); onPick(); });
    popover.append(node);
  };
  if (!profileCardOpenedFromPublic) {
    const muted = stored?.muted === true;
    row(muted ? 'chat.unmuteContact' : 'chat.muteContact', 'chat.muteHint', muted, () => {
      setContactMuted(raw, !muted);
      renderProfileCardActions(raw, own);
    });
    const pinned = stored?.pinned === true;
    row(pinned ? 'chat.unpinContact' : 'chat.pinContact', 'chat.pinHint', pinned, () => {
      setContactPinned(raw, !pinned);
      renderProfileCardActions(raw, own);
    });
  }
  if (!own) row('chat.safetyCode', 'chat.safetyCodeHint', false, () => { void showConversationSafetyCode(raw, { returnFocus: anchor }); });
  showPopoverAt(popover, anchor);
  settleProfileCardPalette();
}

function keyedThreadWithWallet(raw) {
  return threads.find((thread) => !isGroupThread(thread) && !isSavedMessagesThread(thread) && Boolean(thread.convPeerKeyId)
    && sameWalletAddress(ownerWalletFromThread(thread) ?? '', raw)) ?? null;
}

async function showConversationSafetyCode(raw, { returnFocus = null } = {}) {
  const thread = keyedThreadWithWallet(raw);
  const selfKeyId = localRecipientKeyPair?.keyId ?? null;
  let groups = null;
  if (thread && selfKeyId) {
    try { groups = await conversationSafetyCode(selfKeyId, thread.convPeerKeyId); } catch (error) { console.warn('[safety] code', error); }
  }
  const rows = groups ? [0, 4, 8].map((start) => groups.slice(start, start + 4).join(' ')) : [];
  const hint = groups ? 'chat.safetyCodeBody' : (plathoWallet ? 'chat.safetyCodeNone' : 'chat.safetyCodeLocked');
  return openActionDialog({
    title: t('chat.safetyCode'),
    hint: t(hint),
    submitLabel: t('common.done'),
    fields: [],
    summary: rows,
    returnFocus,
  }).catch(() => null);
}

