async function runWalletAssetSend(picked) {
  const pressedBy = plathoWallet?.address ?? null;
  if (!pressedBy || walletTransferOnItsWay(pressedBy)) return;
  if (picked.kind === 'nft') {
    let registry = '';
    try { registry = rawAccount(parseTonAddress(requireUsernameRegistryAddress()).raw); } catch { registry = ''; }
    if (registry && picked.item.collection === registry) {
      const stored = await readStoredUsernameNftList(parseTonAddress(pressedBy).raw).catch(() => null);
      const label = stored?.owned?.find((one) => rawAccount(one?.itemAddress) === picked.item.address)?.label ?? null;
      void openUsernameNftTransferDialog({ itemAddress: picked.item.address, label }).then(() => walletAssetsSent('nft'));
      return;
    }
    const gifts = provenTelegramGiftsForWallet(pressedBy);
    const gift = (gifts?.gifts ?? []).find((one) => rawAccount(one.itemAddress) === picked.item.address);
    if (gift) { void openTelegramGiftTransferDialog(gift).then(() => walletAssetsSent('nft')); return; }
  }
  walletTonTransfersBusy.add(pressedBy);
  let held = false;
  const hold = () => { if (!held) { held = true; activeWindowHoldsWork.inHand = Number(activeWindowHoldsWork.inHand ?? 0) + 1; } };
  try {
    refreshMessagingControls();
    const sent = picked.kind === 'jetton' ? await openWalletJettonTransferDialog(picked.token, hold) : await openWalletNftTransferDialog(picked.item, hold);
    if (sent && sameWalletAddress(plathoWallet?.address, pressedBy)) flashWalletIdentityStatus(sent, 8_000);
  } catch (error) {
    console.error(error);
  } finally {
    if (held) activeWindowHoldsWork.inHand -= 1;
    walletTonTransfersBusy.delete(pressedBy);
    refreshMessagingControls();
  }
}
function walletAssetsSent(tab) {
  const sentBy = plathoWallet?.address;
  const again = () => {
    walletAssetsState.at.delete(tab);
    walletAssetsState.at.delete('history');
    void refreshWalletAssets({ force: true });
  };
  queueVaultPostTransactionRefresh();
  again();
  setTimeout(() => { if (sameWalletAddress(plathoWallet?.address, sentBy)) again(); }, 15_000);
}
function walletAssetSendRefusal(error) {
  return gramShortfallText(error)
    ?? (error?.code === 'PLATHO_WALLET_BALANCE_UNREAD' ? t('wallet.balanceUnreadNothingSent')
      : error?.code === 'APP_UPDATE_PENDING' ? t('wallet.updateReadyReload')
      : error?.code === 'JETTON_WALLET_DISAGREES' ? t('wallet.tokenWalletRefused')
        : error?.code === 'NFT_NOT_OWNED' ? t('wallet.nftNotYours')
          : walletTransferNotRun(error) ? t('wallet.transferNotRun') : t('common.blocked'));
}
async function walletTransferRecipient(entered, seenRecipient, ownContracts = []) {
  let resolved = null;
  try {
    resolved = await resolveTransferRecipient(entered);
  } catch (error) {
    return { error: transferRecipientError(error, entered) };
  }
  let recipient = '';
  try { recipient = requireBasechainAddress(resolved.wallet, 'Recipient'); } catch { return { error: t('wallet.recipientNotBasechain') }; }
  if (parseTonAddress(recipient).raw === parseTonAddress(plathoWallet.address).raw) return { error: t('username.recipientIsSelf') };
  const refusal = await transferRecipientRefusal(resolved, entered, seenRecipient, { ownContracts });
  if (refusal) return { error: refusal };
  return { recipient, display: transferRecipientDisplay(resolved.identity, recipient) };
}
function walletCommentRefusal(comment) {
  return new TextEncoder().encode(String(comment ?? '')).length > TRANSFER_COMMENT_MAX_BYTES ? t('wallet.commentTooLong') : '';
}
async function sendWalletAssetMessage(signer, { address, value, body }) {
  const payload = serializeBoc(body);
  const walletAssetSendNeed = BigInt(value) + walletSendFeeReserveNanotons([walletSendSizeClassForPayloadBytes(payload.length)]);
  await assertWalletGramAtLeast(walletAssetSendNeed, 'wallet asset');
  const message = { address, amount: BigInt(value).toString(), payload: tonCell.bytesToBase64(payload), bounce: true };
  try {
    const result = await sendPlathoWalletTransaction(requireSameWallet(signer), createWalletTransaction([message]),
      { requiredBalance: walletAssetSendNeed, awaitOutcome: true });
    return result?.outcome === 'consumed';
  } catch (error) {
    if (!broadcastMayHaveLanded(error)) throw error;
    return false;
  }
}
function walletTokenDecimals(token) {
  const listed = swapListedToken(token?.master)?.decimals;
  if (Number.isInteger(listed)) return listed;
  if (token?.decimalsKnown === false) return null;
  const stated = Number(token?.decimals);
  return Number.isInteger(stated) && stated >= 0 && stated <= 36 ? stated : null;
}
