function walletTraderHoldings(tokens, balance, priceOf) {
  const verified = [];
  let unverified = 0;
  for (const token of tokens ?? []) {
    if (!token.verified) { unverified += 1; continue; }
    const decimals = walletTokenDecimals(token) ?? token.decimals;
    const amount = Number(token.balance) / 10 ** decimals;
    const price = priceOf(token.master);
    verified.push({ token, decimals, value: price !== null && Number.isFinite(amount) ? amount * price : null });
  }
  verified.sort((a, b) => (b.value ?? -1) - (a.value ?? -1));
  const gram = balance === null ? null : Number(balance) / 1e9;
  const total = gram === null || tokens === null ? null : verified.reduce((sum, one) => sum + (one.value ?? 0), gram);
  return { verified, unverified, gram, total };
}
const TRADER_EXPLORER_ORIGIN = 'https://tonviewer.com';
