function walletSwapRate(route, pool) {
  const pair = route.pair;
  const rate = routeRate(route, pool);
  if (!rate || rate.unitOut <= 0n) return '';
  const reserveIn = rate.unitIn;
  const reserveOut = rate.unitOut;
  const forOne = (10n ** BigInt(pair.offer.decimals) * reserveOut) / reserveIn;
  if (forOne >= 10n ** BigInt(Math.max(0, pair.ask.decimals - 6))) return `1 ${pair.offer.symbol} \u2248 ${formatUnits(forOne, pair.ask.decimals, { shown: 6 })} ${pair.ask.symbol}`;
  return `1 ${pair.ask.symbol} \u2248 ${formatUnits((10n ** BigInt(pair.ask.decimals) * reserveIn) / reserveOut, pair.offer.decimals, { shown: 6 })} ${pair.offer.symbol}`;
}
